"use client";

import React, { useState, useEffect } from "react";
import {
  Heart,
  X,
  Sparkles,
  Sun,
  Sunset,
  Moon,
  CheckCircle2,
  AlertCircle,
  Lock,
  Loader2,
  Tag,
} from "lucide-react";
import {
  CheckinPeriod,
  MindCheckin,
  RATING_LABELS,
  EXTERNAL_CONTEXT_TAGS,
  PRIVACY_DISCLAIMER,
  getDefaultCheckinPeriod,
} from "@/lib/checkin";
import { supabase } from "@/lib/supabase/client";
import { useI18n } from "@/lib/i18n/I18nContext";

interface MoodCheckinModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  existingCheckins?: MindCheckin[];
  onCheckinSaved?: (checkin: MindCheckin) => void;
}

export function MoodCheckinModal({
  isOpen,
  onClose,
  selectedDate,
  existingCheckins = [],
  onCheckinSaved,
}: MoodCheckinModalProps) {
  const { locale } = useI18n();
  const currentHour = new Date().getHours();
  const defaultPeriod = getDefaultCheckinPeriod(currentHour);

  const [period, setPeriod] = useState<CheckinPeriod>(defaultPeriod);
  const [moodScore, setMoodScore] = useState<number>(4);
  const [energyScore, setEnergyScore] = useState<number>(4);
  const [focusScore, setFocusScore] = useState<number>(4);
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [notes, setNotes] = useState<string>("");
  const [saving, setSaving] = useState<boolean>(false);
  const [autoContext, setAutoContext] = useState<{
    sleepHours?: number | null;
    caffeineMg?: number | null;
  }>({});

  // When period changes or existing checkins change, load existing entry if present
  useEffect(() => {
    const existing = existingCheckins.find((c) => c.period === period);
    if (existing) {
      setMoodScore(existing.mood_score);
      setEnergyScore(existing.energy_score);
      setFocusScore(existing.focus_score);
      setSelectedTags(existing.context_tags || []);
      setNotes(existing.notes || "");
    } else {
      setMoodScore(4);
      setEnergyScore(4);
      setFocusScore(4);
      setSelectedTags([]);
      setNotes("");
    }
  }, [period, existingCheckins]);

  // Load auto-detected context (sleep hours & caffeine) from existing logs
  useEffect(() => {
    if (!isOpen || !selectedDate) return;

    async function loadBiologicalContext() {
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) return;

        // Fetch sleep
        const { data: sleepData } = await supabase
          .from("sleep_logs")
          .select("duration_minutes")
          .eq("sleep_date", selectedDate)
          .is("deleted_at", null)
          .maybeSingle();

        // Fetch caffeine
        const { data: intakeData } = await supabase
          .from("intake_logs")
          .select("amount")
          .eq("type", "caffeine")
          .gte("logged_at", `${selectedDate}T00:00:00Z`)
          .lte("logged_at", `${selectedDate}T23:59:59Z`)
          .is("deleted_at", null);

        const totalCaffeine = (intakeData || []).reduce(
          (acc, cur) => acc + (cur.amount || 0),
          0
        );

        setAutoContext({
          sleepHours: sleepData?.duration_minutes
            ? Number((sleepData.duration_minutes / 60).toFixed(1))
            : null,
          caffeineMg: totalCaffeine > 0 ? totalCaffeine : null,
        });
      } catch (err) {
        console.warn("Could not load auto context:", err);
      }
    }

    loadBiologicalContext();
  }, [isOpen, selectedDate]);

  const toggleTag = (tag: string) => {
    setSelectedTags((prev) =>
      prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]
    );
  };

  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const handleSave = async () => {
    setSaving(true);
    setErrorMessage(null);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) throw new Error("Authentication required");

      const checkinPayload = {
        user_id: user.id,
        logged_date: selectedDate,
        period,
        mood_score: moodScore,
        energy_score: energyScore,
        focus_score: focusScore,
        context_tags: selectedTags,
        notes: notes.trim() || null,
        updated_at: new Date().toISOString(),
      };

      // Upsert: edit instead of duplicate per user, date, and period
      const { data, error } = await supabase
        .from("mind_checkins")
        .upsert(checkinPayload, {
          onConflict: "user_id,logged_date,period",
        })
        .select()
        .single();

      if (error) throw error;

      if (onCheckinSaved) onCheckinSaved(data as MindCheckin);
      onClose();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error("Save checkin failed:", msg);
      // FAKE SUCCESS BUG FIX: show real error banner to user, never emit fake local_ id or close modal
      setErrorMessage(`Failed to save check-in: ${msg}`);
    } finally {
      setSaving(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-surface-dim/80 backdrop-blur-md">
      <div className="w-full max-w-md bg-surface-container rounded-3xl border border-border-subtle shadow-2xl overflow-hidden flex flex-col max-h-[92vh]">
        {/* Header */}
        <div className="p-4 sm:p-5 border-b border-border-subtle flex items-center justify-between bg-surface-container-low">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-amber-core/10 border border-amber-core/30 flex items-center justify-center text-amber-core">
              <Heart className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base font-bold font-mono text-on-surface">
                {locale === "ar" ? "تسجيل الحالة والمزاج" : "Mood & Energy Check-in"}
              </h2>
              <p className="text-[11px] font-mono text-on-surface-variant">
                {locale === "ar" ? "معايرة نشاطك وحالتك النفسية" : "Daily state calibration"}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl text-text-muted hover:text-on-surface bg-surface-container-high border border-border-subtle cursor-pointer transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Content Body */}
        <div className="p-4 sm:p-5 flex-1 overflow-y-auto space-y-5">
          {/* Period Selector */}
          <div>
            <label className="text-[11px] font-mono uppercase tracking-wider text-text-muted mb-1.5 block text-start">
              {locale === "ar" ? "وقت التسجيل" : "Time Period"}
            </label>
            <div className="grid grid-cols-3 gap-2">
              {[
                { id: "morning", label: locale === "ar" ? "الصبح" : "Morning", icon: Sun },
                { id: "midday", label: locale === "ar" ? "الظهر" : "Midday", icon: Sunset },
                { id: "evening", label: locale === "ar" ? "بالليل" : "Evening", icon: Moon },
              ].map((p) => {
                const Icon = p.icon;
                const isSelected = period === p.id;
                return (
                  <button
                    key={p.id}
                    onClick={() => setPeriod(p.id as CheckinPeriod)}
                    className={`py-2 px-3 rounded-xl border flex items-center justify-center gap-1.5 font-mono text-xs cursor-pointer transition-all ${
                      isSelected
                        ? "bg-amber-core/15 border-amber-core/40 text-amber-core font-bold"
                        : "bg-surface-container-low border-border-subtle text-text-muted hover:text-on-surface"
                    }`}
                  >
                    <Icon className="w-3.5 h-3.5" />
                    <span>{p.label}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Biological State Auto-Detected Banner */}
          {(autoContext.sleepHours !== undefined || autoContext.caffeineMg !== undefined) && (
            <div className="p-3 rounded-2xl bg-surface-container-low border border-border-subtle flex items-center justify-between text-xs font-mono">
              <span className="text-text-muted">{locale === "ar" ? "بيانات تلقائية:" : "Auto-detected context:"}</span>
              <div className="flex items-center gap-2 text-primary-lime font-medium">
                {autoContext.sleepHours ? (
                  <span>{locale === "ar" ? `${autoContext.sleepHours} س نوم` : `${autoContext.sleepHours}h sleep`}</span>
                ) : null}
                {autoContext.caffeineMg ? (
                  <span>{locale === "ar" ? `${autoContext.caffeineMg} مجم كافيين` : `${autoContext.caffeineMg}mg caffeine`}</span>
                ) : null}
                {!autoContext.sleepHours && !autoContext.caffeineMg ? (
                  <span className="text-text-muted">
                    {locale === "ar" ? "مفيش بيانات اتسجلت للنهاردة لسه" : "No telemetry logged today"}
                  </span>
                ) : null}
              </div>
            </div>
          )}

          {/* Mood Rating */}
          <div className="space-y-1.5">
            <div className="flex items-center justify-between">
              <label className="text-xs font-mono text-on-surface">{locale === "ar" ? "المزاج" : "Mood"}</label>
              <span className="text-xs font-mono font-bold text-amber-core">
                {locale === "ar"
                  ? moodScore === 1 ? "منهك / متضايق" : moodScore === 2 ? "قليل" : moodScore === 3 ? "متوسط" : moodScore === 4 ? "كويس وتمام" : "ممتاز جداً"
                  : RATING_LABELS[moodScore]}
              </span>
            </div>
            <div className="grid grid-cols-5 gap-1.5">
              {[1, 2, 3, 4, 5].map((val) => (
                <button
                  key={val}
                  onClick={() => setMoodScore(val)}
                  className={`py-2 rounded-xl border font-mono text-xs font-bold cursor-pointer transition-all ${
                    moodScore === val
                      ? "bg-amber-core text-on-primary border-amber-core"
                      : "bg-surface-container-low border-border-subtle text-text-muted hover:text-on-surface"
                  }`}
                >
                  {val}
                </button>
              ))}
            </div>
          </div>

          {/* Energy Rating */}
          <div className="space-y-1.5">
            <div className="flex items-center justify-between">
              <label className="text-xs font-mono text-on-surface">{locale === "ar" ? "مستوى النشاط والطاقة" : "Energy Level"}</label>
              <span className="text-xs font-mono font-bold text-amber-core">
                {locale === "ar"
                  ? energyScore === 1 ? "طاقة منعدمة" : energyScore === 2 ? "كسلان" : energyScore === 3 ? "طاقة متوسطة" : energyScore === 4 ? "نشيط" : "طاقة خارقة"
                  : RATING_LABELS[energyScore]}
              </span>
            </div>
            <div className="grid grid-cols-5 gap-1.5">
              {[1, 2, 3, 4, 5].map((val) => (
                <button
                  key={val}
                  onClick={() => setEnergyScore(val)}
                  className={`py-2 rounded-xl border font-mono text-xs font-bold cursor-pointer transition-all ${
                    energyScore === val
                      ? "bg-amber-core text-on-primary border-amber-core"
                      : "bg-surface-container-low border-border-subtle text-text-muted hover:text-on-surface"
                  }`}
                >
                  {val}
                </button>
              ))}
            </div>
          </div>

          {/* Focus Rating */}
          <div className="space-y-1.5">
            <div className="flex items-center justify-between">
              <label className="text-xs font-mono text-on-surface">{locale === "ar" ? "التركيز الذهني" : "Cognitive Focus"}</label>
              <span className="text-xs font-mono font-bold text-amber-core">
                {locale === "ar"
                  ? focusScore === 1 ? "مشتت تمامًا" : focusScore === 2 ? "تركيز ضعيف" : focusScore === 3 ? "تركيز معقول" : focusScore === 4 ? "حاضر ومركز" : "تركيز فائق"
                  : RATING_LABELS[focusScore]}
              </span>
            </div>
            <div className="grid grid-cols-5 gap-1.5">
              {[1, 2, 3, 4, 5].map((val) => (
                <button
                  key={val}
                  onClick={() => setFocusScore(val)}
                  className={`py-2 rounded-xl border font-mono text-xs font-bold cursor-pointer transition-all ${
                    focusScore === val
                      ? "bg-amber-core text-on-primary border-amber-core"
                      : "bg-surface-container-low border-border-subtle text-text-muted hover:text-on-surface"
                  }`}
                >
                  {val}
                </button>
              ))}
            </div>
          </div>

          {/* External Context Tags */}
          <div>
            <label className="text-[11px] font-mono uppercase tracking-wider text-text-muted mb-1.5 block text-start">
              {locale === "ar" ? "عوامل وظروف إضافية (اختياري)" : "External Context (Non-Measurable)"}
            </label>
            <div className="flex flex-wrap gap-1.5">
              {EXTERNAL_CONTEXT_TAGS.map((tag) => {
                const arTagMap: Record<string, string> = {
                  "Poor Sleep": "نوم قليل ومتقطع",
                  "High Caffeine": "كافيين عالي",
                  "Workout Soreness": "وجع عضلات من التمرين",
                  "Academic Stress": "ضغط مذاكرة / امتحانات",
                  "Fasting": "صيام",
                  "Deep Work Win": "إنجاز شغل مهم",
                };
                const displayTag = locale === "ar" ? (arTagMap[tag] || tag) : tag;
                const isSelected = selectedTags.includes(tag);
                return (
                  <button
                    key={tag}
                    onClick={() => toggleTag(tag)}
                    className={`px-2.5 py-1.5 rounded-xl border text-[11px] font-mono cursor-pointer transition-all ${
                      isSelected
                        ? "bg-primary-lime/15 border-primary-lime/40 text-primary-lime font-medium"
                        : "bg-surface-container-low border-border-subtle text-text-muted hover:text-on-surface"
                    }`}
                  >
                    {displayTag}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Notes */}
          <div>
            <label className="text-[11px] font-mono uppercase tracking-wider text-text-muted mb-1.5 block text-start">
              {locale === "ar" ? "ملاحظات إضافية (اختياري)" : "Notes (Optional)"}
            </label>
            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder={locale === "ar" ? "اكتب أي تفاصيل سريعة عن يومك..." : "Brief context or thoughts..."}
              rows={2}
              className="w-full px-3.5 py-2.5 rounded-2xl bg-surface-container-low border border-border-subtle text-xs text-on-surface font-mono placeholder:text-text-muted focus:outline-none focus:border-primary-lime/50 transition-colors resize-none text-start"
            />
          </div>

          {/* Privacy Note */}
          <div className="p-3 rounded-2xl bg-surface-container-low border border-border-subtle flex items-start gap-2">
            <Lock className="w-3.5 h-3.5 text-text-muted mt-0.5 shrink-0" />
            <p className="text-[10px] text-text-muted font-mono leading-relaxed text-start">
              {locale === "ar"
                ? "بياناتك متخزنة بأمان وخاصة بيك بالكامل ومش بنشاركها مع أي طرف تالت."
                : PRIVACY_DISCLAIMER}
            </p>
          </div>

          {/* Error Banner */}
          {errorMessage && (
            <div className="p-3.5 rounded-2xl bg-crimson-alert/15 border border-crimson-alert/30 text-crimson-alert flex items-start gap-2.5 font-mono text-xs">
              <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
              <div className="flex-1 text-start">
                <span className="font-bold block">Save Error:</span>
                <span>{errorMessage}</span>
              </div>
            </div>
          )}

          {/* Save Button */}
          <button
            onClick={handleSave}
            disabled={saving}
            className="w-full py-3.5 rounded-2xl bg-primary-lime text-on-primary font-mono font-bold text-sm uppercase tracking-wider hover:bg-primary-lime-dim shadow-xs flex items-center justify-center gap-2 cursor-pointer transition-all disabled:bg-surface-container-high disabled:text-text-muted disabled:shadow-none disabled:cursor-not-allowed"
          >
            {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckCircle2 className="w-4 h-4" />}
            <span>{locale === "ar" ? "حفظ تسجيل الحالة" : "Save Check-in"}</span>
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  BookOpen,
  Plus,
  CheckCircle2,
  Clock,
  Sparkles,
  X,
  Loader2,
  Bookmark,
  ChevronRight,
} from "lucide-react";
import {
  ReadingBook,
  ReadingLog,
  calculateBookProgress,
  validateReadingLog,
} from "@/lib/reading";
import { supabase } from "@/lib/supabase/client";
import { useI18n } from "@/lib/i18n/I18nContext";

interface ReadingCardProps {
  selectedDate: string;
  onReadingUpdated?: () => void;
}

export function ReadingCard({ selectedDate, onReadingUpdated }: ReadingCardProps) {
  const { locale } = useI18n();
  const [books, setBooks] = useState<ReadingBook[]>([]);
  const [activeBook, setActiveBook] = useState<ReadingBook | null>(null);
  const [todayLogs, setTodayLogs] = useState<ReadingLog[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  // Modals
  const [isLogModalOpen, setIsLogModalOpen] = useState<boolean>(false);
  const [isNewBookModalOpen, setIsNewBookModalOpen] = useState<boolean>(false);

  // Form states
  const [logPages, setLogPages] = useState<string>("");
  const [logMinutes, setLogMinutes] = useState<string>("");
  const [logNotes, setLogNotes] = useState<string>("");
  const [submittingLog, setSubmittingLog] = useState<boolean>(false);
  const [logError, setLogError] = useState<string | null>(null);

  const [newTitle, setNewTitle] = useState<string>("");
  const [newAuthor, setNewAuthor] = useState<string>("");
  const [newTotalPages, setNewTotalPages] = useState<string>("");
  const [newStartPage, setNewStartPage] = useState<string>("0");
  const [submittingBook, setSubmittingBook] = useState<boolean>(false);

  // Load books & today's logs
  useEffect(() => {
    async function loadData() {
      if (!selectedDate) {
        setLoading(false);
        return;
      }
      setLoading(true);
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) return;

        // 1. Fetch user books
        const { data: booksData } = await supabase
          .from("reading_books")
          .select("*")
          .eq("user_id", user.id)
          .is("deleted_at", null)
          .order("created_at", { ascending: false });

        const userBooks = (booksData || []) as ReadingBook[];
        setBooks(userBooks);

        // Pick active reading book
        const reading = userBooks.find((b) => b.status === "reading") || userBooks[0] || null;
        setActiveBook(reading);

        // 2. Fetch logs for selectedDate
        const { data: logsData } = await supabase
          .from("reading_logs")
          .select("*")
          .eq("user_id", user.id)
          .eq("logged_date", selectedDate)
          .is("deleted_at", null)
          .order("created_at", { ascending: false });

        setTodayLogs((logsData || []) as ReadingLog[]);
      } catch (err) {
        console.warn("Reading data load error:", err);
      } finally {
        setLoading(false);
      }
    }

    loadData();
  }, [selectedDate]);

  // Submit reading session log
  const handleSaveLog = async () => {
    setLogError(null);
    const pages = Number(logPages);
    const mins = logMinutes.trim() ? Number(logMinutes) : null;

    const validation = validateReadingLog(pages, mins);
    if (!validation.valid) {
      setLogError(validation.error || "Invalid input");
      return;
    }

    setSubmittingLog(true);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return;

      const payload = {
        user_id: user.id,
        book_id: activeBook?.id || null,
        logged_date: selectedDate,
        pages_read: pages,
        duration_minutes: mins,
        notes: logNotes.trim() || null,
      };

      const { data, error } = await supabase
        .from("reading_logs")
        .insert([payload])
        .select()
        .single();

      if (error) throw error;

      // Update active book current_page
      if (activeBook) {
        const nextCurrent = activeBook.current_page + pages;
        const nextStatus =
          activeBook.total_pages && nextCurrent >= activeBook.total_pages
            ? "completed"
            : activeBook.status;

        await supabase
          .from("reading_books")
          .update({ current_page: nextCurrent, status: nextStatus })
          .eq("id", activeBook.id);

        setActiveBook({ ...activeBook, current_page: nextCurrent, status: nextStatus });
      }

      setTodayLogs([data as ReadingLog, ...todayLogs]);
      setIsLogModalOpen(false);
      setLogPages("");
      setLogMinutes("");
      setLogNotes("");
      if (onReadingUpdated) onReadingUpdated();
    } catch (err: any) {
      setLogError(err.message || "Failed to save reading session");
    } finally {
      setSubmittingLog(false);
    }
  };

  // Create new book
  const handleCreateBook = async () => {
    if (!newTitle.trim()) return;
    setSubmittingBook(true);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return;

      const payload = {
        user_id: user.id,
        title: newTitle.trim(),
        author: newAuthor.trim() || null,
        total_pages: newTotalPages.trim() ? Number(newTotalPages) : null,
        current_page: newStartPage.trim() ? Number(newStartPage) : 0,
        status: "reading",
      };

      const { data, error } = await supabase
        .from("reading_books")
        .insert([payload])
        .select()
        .single();

      if (error) throw error;

      const created = data as ReadingBook;
      setBooks([created, ...books]);
      setActiveBook(created);
      setIsNewBookModalOpen(false);
      setNewTitle("");
      setNewAuthor("");
      setNewTotalPages("");
      setNewStartPage("0");
      if (onReadingUpdated) onReadingUpdated();
    } catch (err) {
      console.warn("Failed to create book:", err);
    } finally {
      setSubmittingBook(false);
    }
  };

  const totalPagesToday = todayLogs.reduce((acc, l) => acc + l.pages_read, 0);
  const totalMinutesToday = todayLogs.reduce((acc, l) => acc + (l.duration_minutes || 0), 0);
  const progress = activeBook ? calculateBookProgress(activeBook) : null;

  return (
    <div className="p-5 rounded-3xl bg-surface-container border border-border-subtle space-y-4">
      {/* Top Header */}
      <div className="flex items-center justify-between pb-3 border-b border-border-subtle">
        <div className="flex items-center gap-2.5">
          <div className="w-8 h-8 rounded-xl bg-tertiary-purple/10 border border-tertiary-purple/30 flex items-center justify-center text-tertiary-purple">
            <BookOpen className="w-4 h-4" />
          </div>
          <div>
            <h3 className="text-sm font-bold font-mono text-on-surface">
              {locale === "ar" ? "القراءة والاطلاع" : "Mindful Reading"}
            </h3>
            <p className="text-[10px] font-mono text-on-surface-variant">
              {locale === "ar" ? "معدل الصفحات وتغذية العقل" : "Daily pages & focus velocity"}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {totalPagesToday > 0 ? (
            <span className="text-xs font-mono font-bold text-tertiary-purple px-2.5 py-1 rounded-full bg-tertiary-purple/10 border border-tertiary-purple/20">
              {locale === "ar" ? `${totalPagesToday} صفحة النهاردة` : `${totalPagesToday} pages today`}
            </span>
          ) : (
            <span className="text-xs font-mono text-text-muted px-2.5 py-1 rounded-full bg-surface-container-low border border-border-subtle">
              {locale === "ar" ? "مفيش قراءة النهاردة" : "No reading today"}
            </span>
          )}
          <button
            onClick={() => setIsLogModalOpen(true)}
            className="px-3 py-1.5 rounded-xl bg-tertiary-purple text-on-primary font-mono font-bold text-xs uppercase tracking-wider hover:brightness-110 cursor-pointer transition-all"
          >
            {locale === "ar" ? "سجل قراءة" : "Log Session"}
          </button>
        </div>
      </div>

      {/* Active Book Card */}
      {loading ? (
        <div className="py-6 flex items-center justify-center">
          <Loader2 className="w-5 h-5 animate-spin text-text-muted" />
        </div>
      ) : activeBook ? (
        <div className="p-4 rounded-2xl bg-surface-container-low border border-border-subtle space-y-3">
          <div className="flex items-start justify-between gap-3">
            <div>
              <h4 className="text-sm font-bold font-mono text-on-surface truncate">
                {activeBook.title}
              </h4>
              <p className="text-[11px] font-mono text-on-surface-variant">
                {activeBook.author
                  ? locale === "ar" ? `للكاتب: ${activeBook.author}` : `by ${activeBook.author}`
                  : locale === "ar" ? "كتاب قيد القراءة" : "Book in progress"}
              </p>
            </div>
            <button
              onClick={() => setIsNewBookModalOpen(true)}
              className="text-[10px] font-mono text-text-muted hover:text-on-surface flex items-center gap-1 cursor-pointer"
            >
              <span>{locale === "ar" ? "تغيير / إضافة" : "Switch / Add"}</span>
              <ChevronRight className="w-3 h-3" />
            </button>
          </div>

          {/* Progress Bar */}
          {progress && (
            <div className="space-y-1.5 font-mono">
              <div className="flex items-center justify-between text-xs">
                <span className="text-text-muted">
                  {locale === "ar"
                    ? `صفحة ${activeBook.current_page} من ${activeBook.total_pages}`
                    : progress.displayText}
                </span>
                <span className="text-tertiary-purple font-bold">
                  {progress.percentComplete}%
                </span>
              </div>
              <div className="w-full h-2 rounded-full bg-surface-container-high overflow-hidden">
                <div
                  className="h-full bg-tertiary-purple rounded-full transition-all duration-500"
                  style={{ width: `${progress.percentComplete}%` }}
                />
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="p-6 rounded-2xl bg-surface-container-low border border-dashed border-border-subtle text-center space-y-2">
          <p className="text-xs font-mono text-text-muted">
            {locale === "ar" ? "مفيش كتاب حالي في قائمة القراءة." : "No active book in reading list."}
          </p>
          <button
            onClick={() => setIsNewBookModalOpen(true)}
            className="px-4 py-2 rounded-xl bg-tertiary-purple/15 border border-tertiary-purple/30 text-tertiary-purple font-mono text-xs font-bold hover:bg-tertiary-purple/25 cursor-pointer transition-colors"
          >
            {locale === "ar" ? "+ أضف كتابك الأول" : "+ Add Your First Book"}
          </button>
        </div>
      )}

      {/* LOG READING SESSION MODAL */}
      {isLogModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-surface-dim/80 backdrop-blur-md">
          <div className="w-full max-w-md bg-surface-container rounded-3xl border border-border-subtle shadow-2xl p-6 space-y-5 font-mono text-xs">
            <div className="flex items-center justify-between pb-3 border-b border-border-subtle">
              <div className="flex items-center gap-2">
                <Bookmark className="w-4 h-4 text-tertiary-purple" />
                <h3 className="text-sm font-bold text-on-surface">
                  {locale === "ar" ? "تسجيل جلسة قراءة" : "Log Reading Session"}
                </h3>
              </div>
              <button
                onClick={() => setIsLogModalOpen(false)}
                className="p-1 rounded-lg text-text-muted hover:text-on-surface cursor-pointer"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {logError && (
              <div className="p-3 rounded-xl bg-[#F87171]/10 border border-[#F87171]/30 text-[#F87171] text-xs">
                {logError}
              </div>
            )}

            <div className="space-y-3">
              <div>
                <label className="text-text-muted uppercase text-[11px] block mb-1 text-start">
                  {locale === "ar" ? "عدد الصفحات المقروءة النهاردة" : "Pages Read Today"}
                </label>
                <input
                  type="number"
                  min={1}
                  max={2000}
                  value={logPages}
                  onChange={(e) => setLogPages(e.target.value)}
