  onSaved: () => void;
  mode: FocusMode;
  plannedMinutes: number;
  actualMinutes: number;
  pausedSeconds: number;
  status: SessionStatus;
  initialCategory?: string;
  initialTaskName?: string;
  initialSubjectId?: string | null;
