"use client";

import React, { useState } from "react";
import {
  X,
  Sparkles,
  Plus,
  Minus,
  Check,
  AlertCircle,
  HelpCircle,
  Loader2,
  Trash2,
  Edit2,
  Layers,
} from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { useOnlineGuard } from "@/hooks/useOnlineGuard";
import {
  ParsedFoodItem,
  MealType,
  rescaleItemNutrients,
  getLocalDateString,
  ConfidenceTier,
} from "@/lib/nutrition";
import { useI18n } from "@/lib/i18n/I18nContext";

interface ConfirmFoodModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLogged: () => void;
  userTimezone: string;
}

export function ConfirmFoodModal({
  isOpen,
  onClose,
  onLogged,
  userTimezone,
}: ConfirmFoodModalProps) {
  const { isOnline, guardAction } = useOnlineGuard();
  const { locale } = useI18n();

  const [query, setQuery] = useState("");
  const [mealType, setMealType] = useState<MealType>("lunch");
  const [parsing, setParsing] = useState(false);
  const [parseError, setParseError] = useState<string | null>(null);

  // Parsed items waiting for confirmation
  const [items, setItems] = useState<ParsedFoodItem[]>([]);
  const [saving, setSaving] = useState(false);

  if (!isOpen) return null;

  const handleParse = async () => {
    if (!query.trim()) return;
    setParsing(true);
    setParseError(null);

    try {
      const res = await fetch("/api/nutrition/parse", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: query.trim() }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to parse meal input");
      }

      setItems(data.items || []);
    } catch (err: any) {
      setParseError(err.message || "Parsing error");
    } finally {
      setParsing(false);
    }
  };

  const updateQuantity = (index: number, delta: number) => {
    setItems((prev) =>
      prev.map((item, i) => {
        if (i !== index) return item;
        const newQty = Math.max(0.25, Math.round((item.quantity + delta) * 100) / 100);
        const rescaled = rescaleItemNutrients(item, newQty);
        return {
          ...item,
          quantity: rescaled.quantity,
          calories: rescaled.calories,
          protein_g: rescaled.protein_g,
          carbs_g: rescaled.carbs_g,
          fats_g: rescaled.fats_g,
        };
      })
    );
  };

  const removeItem = (index: number) => {
    setItems((prev) => prev.filter((_, i) => i !== index));
  };

  const updateManualField = (
    index: number,
    field: "calories" | "protein_g" | "carbs_g" | "fats_g" | "food_name",
    value: any
  ) => {
    setItems((prev) =>
      prev.map((item, i) => {
        if (i !== index) return item;
        return { ...item, [field]: value };
      })
    );
  };

  // Confirm-first: Only save to database when user taps Confirm!
  const handleConfirmAndSave = async () => {
    if (items.length === 0) return;

    guardAction(async () => {
      setSaving(true);
      setParseError(null);

      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) {
          throw new Error(
            locale === "ar"
              ? "يجب تسجيل الدخول أولاً لحفظ الوجبة في حسابك."
              : "Authentication required. Please sign in to save meals."
          );
        }

        const now = new Date();
        const localDate = getLocalDateString(now, userTimezone);

        const rowsToInsert = items.map((it) => ({
          user_id: user.id,
          logged_date: localDate,
          meal_type: mealType,
          food_name: it.food_name,
          quantity: it.quantity,
          unit: it.unit,
          calories: it.calories,
          protein_g: it.protein_g || 0,
          carbs_g: it.carbs_g || 0,
          fats_g: it.fats_g || 0,
          source: it.source,
          confidence: it.confidence,
          raw_query: query.trim() || null,
          logged_at: now.toISOString(),
        }));

        const { error } = await supabase.from("meal_logs").insert(rowsToInsert);
        if (error) throw error;

        onLogged();
        onClose();
      } catch (err: any) {
        setParseError(err.message || "Failed to save meal log.");
      } finally {
        setSaving(false);
      }
    });
  };

  const totalMealCals = items.reduce((sum, it) => sum + (it.calories || 0), 0);
  const totalMealProt = items.reduce((sum, it) => sum + (it.protein_g || 0), 0);
  const totalMealCarbs = items.reduce((sum, it) => sum + (it.carbs_g || 0), 0);
  const totalMealFats = items.reduce((sum, it) => sum + (it.fats_g || 0), 0);

  const getConfidenceBadge = (c: ConfidenceTier) => {
    switch (c) {
      case "high":
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono bg-primary-lime/10 text-primary-lime border border-primary-lime/30">
            {locale === "ar" ? "دقة عالية" : "High Confidence"}
          </span>
        );
      case "medium":
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono bg-[#7DD3FC]/10 text-[#7DD3FC] border border-[#7DD3FC]/30">
            {locale === "ar" ? "تقديري" : "Estimated"}
          </span>
        );
      case "low":
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono bg-rank-gold/10 text-rank-gold border border-rank-gold/30">
            {locale === "ar" ? "دقة منخفضة" : "Low Confidence"}
          </span>
        );
      case "could_not_estimate":
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono bg-[#F87171]/10 text-[#F87171] border border-[#F87171]/30">
            {locale === "ar" ? "غير محدد" : "Could Not Estimate"}
          </span>
        );
    }
  };

  const MEAL_LABELS: Record<MealType, string> = {
    breakfast: locale === "ar" ? "فطار" : "breakfast",
    lunch: locale === "ar" ? "غدا" : "lunch",
    dinner: locale === "ar" ? "عشا" : "dinner",
    snack: locale === "ar" ? "سناك" : "snack",
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-charcoal-dark/80 backdrop-blur-md">
      <div className="relative w-full max-w-lg bg-surface-container border border-border-subtle rounded-3xl p-6 shadow-2xl max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between pb-4 border-b border-border-subtle">
          <div className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-secondary-cyan" />
            <h2 className="text-base font-bold font-mono text-on-surface">
              {locale === "ar" ? "تسجيل الوجبات الذكي" : "AI Natural Food Logger"}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-xl text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Meal Type Selector */}
        <div className="grid grid-cols-4 gap-1.5 my-4 p-1 bg-surface-container-lowest rounded-xl border border-border-subtle">
          {(["breakfast", "lunch", "dinner", "snack"] as MealType[]).map((m) => (
            <button
              key={m}
              onClick={() => setMealType(m)}
              className={`py-2 text-[11px] font-mono uppercase tracking-wider font-semibold rounded-lg transition-all capitalize cursor-pointer ${
                mealType === m
                  ? "bg-secondary-cyan text-on-primary shadow-sm font-bold"
                  : "text-text-muted hover:text-on-surface"
              }`}
            >
              {MEAL_LABELS[m]}
            </button>
          ))}
        </div>

        {/* Natural Language Input Box */}
        <div className="space-y-2">
          <label className="block text-xs font-mono text-text-muted">
            {locale === "ar"
              ? "اوصف أكلت إيه (عربي، مصري، إنجليزي، أو فرانكو)"
              : "Describe what you ate (English, Arabic, Franco-Arab)"}
          </label>
          <div className="relative">
            <textarea
              rows={3}
              maxLength={500}
              placeholder={
                locale === "ar"
                  ? "مثال: طبق كشري وكانز دايت، أو 3 بيضات ورغيف بلدي وقهوة"
                  : "e.g. 3 eggs, 2 sourdough slices, flat white OR طبق كشري و كانز دايت OR 2 ful, 3 ta3meya"
              }
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className="w-full p-3 rounded-2xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface placeholder:text-text-muted/60 focus:border-secondary-cyan focus:outline-none resize-none"
            />
            <div className="text-[10px] font-mono text-text-muted text-end mt-1">
              {query.length}/500 {locale === "ar" ? "حرف" : "chars"}
            </div>
          </div>

          <button
            onClick={handleParse}
            disabled={parsing || !query.trim()}
            className="w-full flex items-center justify-center gap-2 py-3 rounded-xl font-mono text-xs font-bold bg-primary-lime text-on-primary shadow-xs hover:brightness-110 active:scale-[0.98] transition-all disabled:bg-surface-container-high disabled:text-text-muted disabled:shadow-none disabled:cursor-not-allowed cursor-pointer"
          >
            {parsing ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                <span>{locale === "ar" ? "جاري التحليل بالذكاء الاصطناعي..." : "Parsing with Grounded AI..."}</span>
              </>
            ) : (
              <>
                <Sparkles className="w-4 h-4" />
                <span>{locale === "ar" ? "تحليل الوجبة" : "Parse Items"}</span>
              </>
            )}
          </button>
        </div>

        {parseError && (
          <div className="p-3 my-4 rounded-xl bg-[#F87171]/10 border border-[#F87171]/30 flex items-start gap-2.5 text-[#F87171] text-xs font-mono">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <span>{parseError}</span>
          </div>
        )}

        {/* Reviewed Items List (Confirm-First) */}
        {items.length > 0 && (
          <div className="mt-6 space-y-3">
            <div className="flex items-center justify-between text-xs font-mono">
              <span className="font-bold text-on-surface flex items-center gap-1.5">
                <Layers className="w-4 h-4 text-secondary-cyan" />
                {locale === "ar" ? `عناصر الوجبة المراجعة (${items.length})` : `Reviewed Meal Items (${items.length})`}
              </span>
              <span className="text-[11px] text-text-muted">
                {locale === "ar" ? "دوس تأكيد للحفظ" : "Tap Confirm to save"}
              </span>
            </div>

            <div className="space-y-2.5 max-h-64 overflow-y-auto pr-1">
              {items.map((it, idx) => (
                <div
                  key={idx}
                  className="p-3.5 rounded-2xl bg-surface-container-high border border-border-subtle space-y-2.5"
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="space-y-0.5">
                      <div className="font-mono text-sm font-bold text-on-surface">
                        {it.food_name}
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="px-1.5 py-0.5 rounded text-[9px] font-mono uppercase bg-surface-container-lowest text-text-muted border border-border-subtle">
                          {it.source}
                        </span>
                        {getConfidenceBadge(it.confidence)}
                      </div>
                    </div>

                    <button
                      onClick={() => removeItem(idx)}
                      className="p-1 rounded-lg text-text-muted hover:text-[#F87171] hover:bg-surface-container-lowest transition-colors cursor-pointer"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>

                  {/* Quantity and Portion Stepper */}
                  <div className="flex items-center justify-between pt-1">
                    <div className="flex items-center gap-2 bg-surface-container-lowest px-2 py-1 rounded-xl border border-border-subtle font-mono text-xs">
                      <button
                        onClick={() => updateQuantity(idx, -1)}
                        className="p-1 hover:text-secondary-cyan transition-colors"
                      >
                        <Minus className="w-3.5 h-3.5" />
                      </button>
                      <span className="font-bold text-on-surface px-1">
                        {it.quantity} {it.unit}
                      </span>
                      <button
                        onClick={() => updateQuantity(idx, 1)}
                        className="p-1 hover:text-secondary-cyan transition-colors"
                      >
                        <Plus className="w-3.5 h-3.5" />
                      </button>
                    </div>

                    {/* Macros Display or Manual Input if Could Not Estimate */}
                    {it.confidence === "could_not_estimate" || it.calories === null ? (
                      <div className="flex items-center gap-1.5">
                        <input
                          type="number"
                          placeholder="kcal"
                          value={it.calories ?? ""}
                          onChange={(e) =>
                            updateManualField(
                              idx,
                              "calories",
                              e.target.value ? parseInt(e.target.value) : null
                            )
                          }
                          className="w-16 px-2 py-1 rounded-lg bg-surface-container-lowest border border-[#F87171]/40 font-mono text-xs text-center text-on-surface focus:outline-none"
                        />
                        <span className="text-[10px] font-mono text-[#F87171]">
                          {locale === "ar" ? "أدخل السعرات" : "Enter kcal"}
                        </span>
                      </div>
                    ) : (
                      <div className="text-end font-mono text-xs">
                        <div className="font-bold text-on-surface">
                          {it.calories} {locale === "ar" ? "سعرة" : "kcal"}
                        </div>
                        <div className="text-[10px] text-text-muted">
                          {locale === "ar"
                            ? `ب: ${it.protein_g}جم | ك: ${it.carbs_g}جم | د: ${it.fats_g}جم`
                            : `P: ${it.protein_g}g | C: ${it.carbs_g}g | F: ${it.fats_g}g`}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {/* Total Meal Impact Summary */}
            <div className="p-3 rounded-2xl bg-surface-container-lowest border border-border-subtle flex items-center justify-between font-mono text-xs">
              <span className="text-text-muted">{locale === "ar" ? "إجمالي الوجبة:" : "Total Meal Impact:"}</span>
              <div className="flex items-center gap-3">
                <span className="font-bold text-on-surface">
                  {totalMealCals} {locale === "ar" ? "سعرة" : "kcal"}
                </span>
                <span className="text-primary-lime font-semibold">
                  {totalMealProt}{locale === "ar" ? "جم بروتين" : "g Prot"}
                </span>
                <span className="text-secondary-cyan">
                  {totalMealCarbs}{locale === "ar" ? "جم ك" : "g C"}
                </span>
                <span className="text-rank-gold">
                  {totalMealFats}{locale === "ar" ? "جم د" : "g F"}
                </span>
              </div>
            </div>

            {/* Error above confirm button */}
            {parseError && (
              <div className="p-3 rounded-xl bg-[#F87171]/10 border border-[#F87171]/30 flex items-start gap-2.5 text-[#F87171] text-xs font-mono">
                <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
                <span>{parseError}</span>
              </div>
            )}

            {/* Confirm & Save Button */}
            <div className="pt-2">
              <button
                onClick={handleConfirmAndSave}
                disabled={saving}
                className="w-full flex items-center justify-center gap-2 py-3 rounded-xl font-mono text-xs font-bold bg-secondary-cyan text-on-primary shadow-[0_0_15px_rgba(93,230,255,0.25)] hover:brightness-110 active:scale-[0.98] transition-all disabled:opacity-50 cursor-pointer"
              >
                {saving ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    <span>{locale === "ar" ? "جاري الحفظ..." : "Saving Meal..."}</span>
                  </>
                ) : (
                  <>
                    <Check className="w-4 h-4" />
                    <span>{locale === "ar" ? "تأكيد وحفظ الوجبة" : "Confirm & Save Meal"}</span>
                  </>
                )}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { Plus, Sparkles, Undo2, Check, Clock } from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { useOnlineGuard } from "@/hooks/useOnlineGuard";
import {
  FrequentFoodItem,
  normalizeFoodName,
  getLocalDateString,
  MealType,
} from "@/lib/nutrition";
import { useI18n } from "@/lib/i18n/I18nContext";

interface FrequentFoodsBarProps {
  onFoodLogged: () => void;
  userTimezone: string;
}

export function FrequentFoodsBar({
  onFoodLogged,
  userTimezone,
}: FrequentFoodsBarProps) {
  const { isOnline, guardAction } = useOnlineGuard();
  const { locale } = useI18n();

  const [frequentFoods, setFrequentFoods] = useState<FrequentFoodItem[]>([]);
  const [loading, setLoading] = useState(true);

  // Undo state for 1-tap logging
  const [loggedToast, setLoggedToast] = useState<{ id: string; name: string; calories: number } | null>(null);
  const [undoTimeout, setUndoTimeout] = useState<NodeJS.Timeout | null>(null);

  const fetchFrequentFoods = async () => {
    setLoading(true);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return;

      // Fetch meal_logs from the past 30 days
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
      const startDateStr = thirtyDaysAgo.toISOString().split("T")[0];

      const { data, error } = await supabase
        .from("meal_logs")
        .select("food_name, quantity, unit, calories, protein_g, carbs_g, fats_g, source")
        .eq("user_id", user.id)
        .gte("logged_date", startDateStr)
        .is("deleted_at", null);

      if (error || !data || data.length === 0) {
        setFrequentFoods([]);
        setLoading(false);
        return;
      }

      // Group and normalize (Item 7)
      const groups: Record<
        string,
        {
          display_name: string;
          count: number;
          quantities: number[];
          caloriesList: number[];
          proteins: number[];
          carbs: number[];
          fats: number[];
          unit: string;
          source: any;
        }
      > = {};

      for (const row of data) {
        const norm = normalizeFoodName(row.food_name);
        if (!groups[norm]) {
          groups[norm] = {
            display_name: row.food_name,
            count: 0,
            quantities: [],
            caloriesList: [],
            proteins: [],
            carbs: [],
            fats: [],
            unit: row.unit || "serving",
            source: row.source || "manual",
          };
        }
        groups[norm].count += 1;
        groups[norm].quantities.push(Number(row.quantity) || 1);
        if (row.calories !== null) groups[norm].caloriesList.push(Number(row.calories));
        groups[norm].proteins.push(Number(row.protein_g) || 0);
        groups[norm].carbs.push(Number(row.carbs_g) || 0);
        groups[norm].fats.push(Number(row.fats_g) || 0);
      }

      // Compute typical quantities and calories
      const result: FrequentFoodItem[] = Object.entries(groups)
        .map(([norm, g]) => {
          // Median quantity
          const sortedQty = [...g.quantities].sort((a, b) => a - b);
          const typicalQty = sortedQty[Math.floor(sortedQty.length / 2)] || 1;

          // Average calories
          const avgCal = g.caloriesList.length > 0
            ? Math.round(g.caloriesList.reduce((s, c) => s + c, 0) / g.caloriesList.length)
            : 0;

          const avgProt = g.proteins.length > 0
            ? Math.round((g.proteins.reduce((s, p) => s + p, 0) / g.proteins.length) * 10) / 10
            : 0;
          const avgCarb = g.carbs.length > 0
            ? Math.round((g.carbs.reduce((s, c) => s + c, 0) / g.carbs.length) * 10) / 10
            : 0;
          const avgFat = g.fats.length > 0
            ? Math.round((g.fats.reduce((s, f) => s + f, 0) / g.fats.length) * 10) / 10
            : 0;

          return {
            normalized_name: norm,
            display_name: g.display_name,
            frequency: g.count,
            typical_quantity: typicalQty,
            typical_unit: g.unit,
            typical_calories: avgCal,
            typical_protein_g: avgProt,
            typical_carbs_g: avgCarb,
            typical_fats_g: avgFat,
            source: g.source,
          };
        })
        .sort((a, b) => b.frequency - a.frequency)
        .slice(0, 8); // Top 8 frequent items

      setFrequentFoods(result);
    } catch (err) {
      console.error("Failed to load frequent foods:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchFrequentFoods();
  }, []);

  // 1-Tap Quick Logging with confirmation & undo (Item 7)
  const handleQuickLog = async (item: FrequentFoodItem) => {
    guardAction(async () => {
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) throw new Error("Auth required");

        const now = new Date();
        const localDate = getLocalDateString(now, userTimezone);

        // Determine likely meal type based on hour
        const hour = now.getHours();
        let mealType: MealType = "lunch";
        if (hour < 11) mealType = "breakfast";
        else if (hour >= 11 && hour < 16) mealType = "lunch";
        else if (hour >= 16 && hour < 21) mealType = "dinner";
        else mealType = "snack";

        const { data: inserted, error } = await supabase
          .from("meal_logs")
          .insert([
            {
              user_id: user.id,
              logged_date: localDate,
              meal_type: mealType,
              food_name: item.display_name,
              quantity: item.typical_quantity,
              unit: item.typical_unit,
              calories: item.typical_calories,
              protein_g: item.typical_protein_g,
              carbs_g: item.typical_carbs_g,
              fats_g: item.typical_fats_g,
              source: "manual",
              confidence: "high",
              raw_query: `1-Tap Frequent Food: ${item.display_name}`,
              logged_at: now.toISOString(),
            },
          ])
          .select("id")
          .single();

        if (error) throw error;

        // Show what was logged and offer undo toast (Item 7)
        if (inserted) {
          setLoggedToast({
            id: inserted.id,
            name: `${item.typical_quantity} ${item.typical_unit} ${item.display_name}`,
            calories: item.typical_calories,
          });

          if (undoTimeout) clearTimeout(undoTimeout);
          const t = setTimeout(() => setLoggedToast(null), 8000);
          setUndoTimeout(t);
        }

        onFoodLogged();
      } catch (err: any) {
        console.error("Quick log error:", err);
      }
    });
  };

  const handleUndoQuickLog = async () => {
    if (!loggedToast) return;
    guardAction(async () => {
      try {
        const { error } = await supabase
          .from("meal_logs")
          .update({ deleted_at: new Date().toISOString() })
          .eq("id", loggedToast.id);

        if (error) throw error;
        setLoggedToast(null);
        if (undoTimeout) clearTimeout(undoTimeout);
        onFoodLogged();
      } catch (err: any) {
        console.error("Failed to undo quick log:", err);
      }
    });
  };

  if (loading || frequentFoods.length === 0) {
    return null;
  }

  return (
    <div className="space-y-2">
      {/* Undo Toast */}
      {loggedToast && (
        <div className="p-3 rounded-2xl bg-surface-container-high border border-primary-lime/40 flex items-center justify-between text-xs font-mono text-on-surface animate-fade-in shadow-lg">
          <div className="flex items-center gap-2">
            <Check className="w-3.5 h-3.5 text-primary-lime" />
            <span>
              {locale === "ar"
                ? `اتسجل ${loggedToast.name} (${loggedToast.calories} سعرة)`
                : `Logged ${loggedToast.name} (${loggedToast.calories} kcal)`}
            </span>
          </div>
          <button
            onClick={handleUndoQuickLog}
            className="flex items-center gap-1.5 px-3 py-1 rounded-xl bg-primary-lime text-on-primary font-bold hover:brightness-110 active:scale-95 transition-all cursor-pointer"
          >
            <Undo2 className="w-3.5 h-3.5" />
            <span>{locale === "ar" ? "تراجع" : "Undo"}</span>
          </button>
        </div>
      )}

      {/* Horizontal Carousel */}
      <div className="flex items-center gap-2 overflow-x-auto pb-1 font-mono text-xs no-scrollbar">
        <span className="text-[10px] uppercase tracking-wider text-text-muted shrink-0 flex items-center gap-1">
          <Sparkles className="w-3 h-3 text-secondary-cyan" />
          {locale === "ar" ? "المتكرر:" : "Frequent:"}
        </span>

        {frequentFoods.map((item) => (
          <button
            key={item.normalized_name}
            onClick={() => handleQuickLog(item)}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-surface-container-high border border-border-subtle hover:border-secondary-cyan hover:bg-secondary-cyan/10 active:scale-95 transition-all shrink-0 cursor-pointer text-start"
            title={
              locale === "ar"
                ? `تسجيل بضغطة واحدة: ${item.typical_quantity} ${item.typical_unit} · ${item.typical_calories} سعرة`
                : `1-Tap Log: ${item.typical_quantity} ${item.typical_unit} · ${item.typical_calories} kcal`
            }
          >
            <Plus className="w-3 h-3 text-secondary-cyan shrink-0" />
            <span className="font-bold text-on-surface">{item.display_name}</span>
            <span className="text-[10px] text-text-muted">
              ({item.typical_quantity} {item.typical_unit} · {item.typical_calories} {locale === "ar" ? "سعرة" : "kcal"})
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import {
  Droplet,
  Coffee,
  Plus,
  AlertTriangle,
  Trash2,
  Undo2,
  Check,
  ShieldAlert,
} from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { useOnlineGuard } from "@/hooks/useOnlineGuard";
import {
  IntakeLogEntry,
  evaluateCaffeineCutoff,
} from "@/lib/nutrition";
import { useI18n } from "@/lib/i18n/I18nContext";

interface HydrationCardProps {
  waterToday: number;
  waterTarget: number | null;
  caffeineToday: number;
  intakeEntries: IntakeLogEntry[];
  targetBedtime?: string;
  caffeineCutoffHours?: number;
  userTimezone: string;
  onIntakeUpdated: () => void;
}

export function HydrationCard({
  waterToday,
  waterTarget,
  caffeineToday,
  intakeEntries,
  targetBedtime = "23:00",
  caffeineCutoffHours = 10,
  userTimezone,
  onIntakeUpdated,
}: HydrationCardProps) {
  const { isOnline, guardAction } = useOnlineGuard();
  const { locale } = useI18n();

  const [activeTab, setActiveTab] = useState<"water" | "caffeine">("water");
  const [customAmount, setCustomAmount] = useState("");
  const [showCustomInput, setShowCustomInput] = useState(false);
  const [logging, setLogging] = useState(false);
  const [deletedEntry, setDeletedEntry] = useState<{ id: string; type: string; amount: number } | null>(null);
  const [undoTimeout, setUndoTimeout] = useState<NodeJS.Timeout | null>(null);

  // Caffeine cutoff evaluation
  const cutoffEval = evaluateCaffeineCutoff(
    new Date().toISOString(),
    targetBedtime,
    caffeineCutoffHours,
    userTimezone
  );

  const waterPercent = waterTarget && waterTarget > 0 ? Math.min(100, Math.round((waterToday / waterTarget) * 100)) : 0;

  const handleQuickAdd = async (type: "water" | "caffeine", amount: number) => {
    guardAction(async () => {
      setLogging(true);
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) throw new Error("Auth required");

        const { error } = await supabase.from("intake_logs").insert([
          {
            user_id: user.id,
            type,
            amount,
            logged_at: new Date().toISOString(),
          },
        ]);

        if (error) throw error;
        onIntakeUpdated();
      } catch (err: any) {
        console.error("Failed to log intake:", err);
      } finally {
        setLogging(false);
      }
    });
  };

  const handleCustomSubmit = async () => {
    const amt = parseInt(customAmount);
    if (isNaN(amt) || amt <= 0) return;
    await handleQuickAdd(activeTab, amt);
    setCustomAmount("");
    setShowCustomInput(false);
  };

  const handleSoftDelete = async (entry: IntakeLogEntry) => {
    guardAction(async () => {
      try {
        const { error } = await supabase
          .from("intake_logs")
          .update({ deleted_at: new Date().toISOString() })
          .eq("id", entry.id);

        if (error) throw error;

        // Trigger undo toast
        setDeletedEntry({ id: entry.id, type: entry.type, amount: entry.amount });
        if (undoTimeout) clearTimeout(undoTimeout);
        const timer = setTimeout(() => {
          setDeletedEntry(null);
        }, 8000);
        setUndoTimeout(timer);

        onIntakeUpdated();
      } catch (err: any) {
        console.error("Failed to soft-delete intake:", err);
      }
    });
  };

  const handleUndo = async () => {
    if (!deletedEntry) return;
    guardAction(async () => {
      try {
        const { error } = await supabase
          .from("intake_logs")
          .update({ deleted_at: null })
          .eq("id", deletedEntry.id);

        if (error) throw error;
        setDeletedEntry(null);
        if (undoTimeout) clearTimeout(undoTimeout);
        onIntakeUpdated();
      } catch (err: any) {
        console.error("Failed to undo delete:", err);
      }
    });
  };

  return (
    <div className="bg-surface-container border border-border-subtle rounded-3xl p-5 space-y-4">
      {/* Undo Toast */}
      {deletedEntry && (
        <div className="p-3 rounded-2xl bg-surface-container-high border border-primary-lime/40 flex items-center justify-between text-xs font-mono text-on-surface animate-fade-in">
          <span>
            {locale === "ar"
              ? `اتمسح ${deletedEntry.amount} ${deletedEntry.type === "water" ? "مل ميه" : "مجم كافيين"}`
              : `Removed ${deletedEntry.amount} ${deletedEntry.type === "water" ? "ml water" : "mg caffeine"}`}
          </span>
          <button
            onClick={handleUndo}
            className="flex items-center gap-1.5 px-3 py-1 rounded-xl bg-primary-lime text-on-primary font-bold hover:brightness-110 active:scale-95 transition-all cursor-pointer"
          >
            <Undo2 className="w-3.5 h-3.5" />
            <span>{locale === "ar" ? "تراجع" : "Undo"}</span>
          </button>
        </div>
      )}

      {/* Tabs */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 p-1 bg-surface-container-lowest rounded-xl border border-border-subtle">
          <button
            onClick={() => setActiveTab("water")}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-mono font-semibold transition-all cursor-pointer ${
              activeTab === "water"
                ? "bg-secondary-cyan text-on-primary font-bold shadow-sm"
                : "text-text-muted hover:text-on-surface"
            }`}
          >
            <Droplet className="w-3.5 h-3.5" />
            <span>{locale === "ar" ? "شرب الميه" : "Water Intake"}</span>
          </button>
          <button
            onClick={() => setActiveTab("caffeine")}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-mono font-semibold transition-all cursor-pointer ${
              activeTab === "caffeine"
                ? "bg-rank-gold text-on-primary font-bold shadow-sm"
                : "text-text-muted hover:text-on-surface"
            }`}
          >
            <Coffee className="w-3.5 h-3.5" />
            <span>{locale === "ar" ? "متابعة الكافيين" : "Caffeine Telemetry"}</span>
          </button>
        </div>

        <button
          onClick={() => setShowCustomInput(!showCustomInput)}
          className="p-1.5 rounded-xl bg-surface-container-high text-text-muted hover:text-on-surface border border-border-subtle transition-colors cursor-pointer"
          title={locale === "ar" ? "كمية مخصصة" : "Custom Amount"}
        >
          <Plus className="w-4 h-4" />
        </button>
      </div>

      {/* Water Panel */}
      {activeTab === "water" && (
        <div className="space-y-3">
          <div className="flex items-baseline justify-between font-mono">
            <div>
              <span className="text-2xl font-bold text-secondary-cyan">{waterToday}</span>
              <span className="text-xs text-text-muted ml-1">{locale === "ar" ? "مل" : "ml"}</span>
            </div>
            <div className="text-xs text-text-muted">
              {waterTarget
                ? (locale === "ar" ? `الهدف: ${waterTarget} مل (${waterPercent}%)` : `Target: ${waterTarget} ml (${waterPercent}%)`)
                : (locale === "ar" ? "الهدف مش محدد" : "Target Unset")}
            </div>
          </div>

          {/* Linear Progress Bar */}
          <div className="w-full h-2.5 bg-surface-container-lowest rounded-full overflow-hidden border border-border-subtle">
            <div
              className="h-full bg-secondary-cyan rounded-full transition-all duration-500 shadow-[0_0_10px_rgba(93,230,255,0.4)]"
              style={{ width: `${waterPercent}%` }}
            />
          </div>

          {/* Quick-Add Chips */}
          <div className="grid grid-cols-3 gap-2 pt-1 font-mono text-xs">
            <button
              onClick={() => handleQuickAdd("water", 250)}
              disabled={logging}
              className="py-2 px-2.5 rounded-xl bg-surface-container-lowest border border-border-subtle text-on-surface hover:border-secondary-cyan hover:bg-secondary-cyan/10 active:scale-95 transition-all text-center cursor-pointer"
            >
              <div className="font-bold text-secondary-cyan">+250 {locale === "ar" ? "مل" : "ml"}</div>
              <div className="text-[10px] text-text-muted">{locale === "ar" ? "كوباية" : "Glass"}</div>
            </button>
            <button
              onClick={() => handleQuickAdd("water", 500)}
              disabled={logging}
              className="py-2 px-2.5 rounded-xl bg-surface-container-lowest border border-border-subtle text-on-surface hover:border-secondary-cyan hover:bg-secondary-cyan/10 active:scale-95 transition-all text-center cursor-pointer"
            >
              <div className="font-bold text-secondary-cyan">+500 {locale === "ar" ? "مل" : "ml"}</div>
              <div className="text-[10px] text-text-muted">{locale === "ar" ? "إزازة" : "Bottle"}</div>
            </button>
            <button
              onClick={() => handleQuickAdd("water", 750)}
              disabled={logging}
              className="py-2 px-2.5 rounded-xl bg-surface-container-lowest border border-border-subtle text-on-surface hover:border-secondary-cyan hover:bg-secondary-cyan/10 active:scale-95 transition-all text-center cursor-pointer"
            >
              <div className="font-bold text-secondary-cyan">+750 {locale === "ar" ? "مل" : "ml"}</div>
              <div className="text-[10px] text-text-muted">{locale === "ar" ? "شيكر" : "Shaker"}</div>
            </button>
          </div>
        </div>
      )}

      {/* Caffeine Panel */}
      {activeTab === "caffeine" && (
        <div className="space-y-3">
          <div className="flex items-baseline justify-between font-mono">
            <div>
              <span className="text-2xl font-bold text-rank-gold">{caffeineToday}</span>
              <span className="text-xs text-text-muted ml-1">
                {locale === "ar" ? "مجم كافيين" : "mg consumed"}
              </span>
            </div>
            <div className="text-xs text-text-muted">
              {locale === "ar" ? `الحد الأقصى: ${cutoffEval.cutoffTimeFormatted}` : `Cutoff: ${cutoffEval.cutoffTimeFormatted}`}
            </div>
          </div>

          {/* Cutoff Warning Banner if after cutoff */}
          {cutoffEval.isAfterCutoff && (
            <div className="p-3 rounded-2xl bg-rank-gold/10 border border-rank-gold/30 flex items-start gap-2.5 text-xs font-mono text-rank-gold">
              <ShieldAlert className="w-4 h-4 shrink-0 mt-0.5" />
              <div>
                <span className="font-bold">
                  {locale === "ar" ? "تجاوزت وقت الكافيين: " : "Caffeine Cutoff Exceeded: "}
                </span>
                {locale === "ar"
                  ? `آخر ميعاد كان ${cutoffEval.cutoffTimeFormatted} (${caffeineCutoffHours} ساعات قبل معاد النوم ${targetBedtime}). الشرب دلوقتي هيأثر مباشرة على جودة النوم العميق!`
                  : `Cutoff was ${cutoffEval.cutoffTimeFormatted} (${caffeineCutoffHours}h before ${targetBedtime} bedtime). Intake now directly degrades slow-wave sleep!`}
              </div>
            </div>
          )}

          {/* Caffeine Quick-Add Chips */}
          <div className="grid grid-cols-4 gap-1.5 pt-1 font-mono text-xs">
            <button
              onClick={() => handleQuickAdd("caffeine", 65)}
              disabled={logging}
              className="py-2 px-1 rounded-xl bg-surface-container-lowest border border-border-subtle text-on-surface hover:border-rank-gold hover:bg-rank-gold/10 active:scale-95 transition-all text-center cursor-pointer"
            >
              <div className="font-bold text-rank-gold">+65 {locale === "ar" ? "مجم" : "mg"}</div>
              <div className="text-[9px] text-text-muted">{locale === "ar" ? "إسبريسو" : "Single"}</div>
            </button>
            <button
              onClick={() => handleQuickAdd("caffeine", 130)}
              disabled={logging}
              className="py-2 px-1 rounded-xl bg-surface-container-lowest border border-border-subtle text-on-surface hover:border-rank-gold hover:bg-rank-gold/10 active:scale-95 transition-all text-center cursor-pointer"
            >
              <div className="font-bold text-rank-gold">+130 {locale === "ar" ? "مجم" : "mg"}</div>
              <div className="text-[9px] text-text-muted">{locale === "ar" ? "دبل" : "Double"}</div>
            </button>
            <button
              onClick={() => handleQuickAdd("caffeine", 95)}
              disabled={logging}
              className="py-2 px-1 rounded-xl bg-surface-container-lowest border border-border-subtle text-on-surface hover:border-rank-gold hover:bg-rank-gold/10 active:scale-95 transition-all text-center cursor-pointer"
            >
              <div className="font-bold text-rank-gold">+95 {locale === "ar" ? "مجم" : "mg"}</div>
              <div className="text-[9px] text-text-muted">{locale === "ar" ? "فلتر" : "Filter"}</div>
            </button>
            <button
              onClick={() => handleQuickAdd("caffeine", 40)}
              disabled={logging}
              className="py-2 px-1 rounded-xl bg-surface-container-lowest border border-border-subtle text-on-surface hover:border-rank-gold hover:bg-rank-gold/10 active:scale-95 transition-all text-center cursor-pointer"
            >
              <div className="font-bold text-rank-gold">+40 {locale === "ar" ? "مجم" : "mg"}</div>
              <div className="text-[9px] text-text-muted">{locale === "ar" ? "شاي" : "Tea/Soda"}</div>
            </button>
          </div>
        </div>
      )}

      {/* Custom Amount Drawer */}
      {showCustomInput && (
        <div className="flex items-center gap-2 pt-2 border-t border-border-subtle font-mono text-xs">
          <input
            type="number"
            placeholder={
              activeTab === "water"
                ? locale === "ar"
                  ? "الكمية (مل)"
                  : "Amount (ml)"
                : locale === "ar"
                ? "الكمية (مجم)"
                : "Amount (mg)"
            }
            value={customAmount}
            onChange={(e) => setCustomAmount(e.target.value)}
            className="flex-1 px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle text-on-surface focus:outline-none"
          />
          <button
            onClick={handleCustomSubmit}
            disabled={!customAmount || logging}
            className="px-4 py-2 rounded-xl bg-primary-lime text-on-primary font-bold hover:brightness-110 active:scale-95 transition-all disabled:bg-surface-container-high disabled:text-text-muted disabled:shadow-none disabled:cursor-not-allowed cursor-pointer"
          >
            {locale === "ar" ? "إضافة" : "Add"}
          </button>
        </div>
      )}

      {/* Recent Entries Timeline */}
      {intakeEntries.length > 0 && (
        <div className="pt-2 border-t border-border-subtle space-y-1.5">
          <div className="text-[10px] font-mono uppercase tracking-wider text-text-muted text-start">
            {locale === "ar"
              ? `سجل النهاردة (${intakeEntries.length})`
              : `Today's Logged Intakes (${intakeEntries.length})`}
          </div>
          <div className="space-y-1 max-h-32 overflow-y-auto pr-1">
            {intakeEntries.map((e) => {
              const timeStr = new Date(e.logged_at).toLocaleTimeString(locale === "ar" ? "ar-EG" : [], {
                hour: "numeric",
                minute: "2-digit",
                hour12: true,
              });
              return (
                <div
                  key={e.id}
                  className="flex items-center justify-between p-2 rounded-xl bg-surface-container-lowest text-xs font-mono"
                >
                  <div className="flex items-center gap-2">
                    {e.type === "water" ? (
                      <Droplet className="w-3.5 h-3.5 text-secondary-cyan" />
                    ) : (
                      <Coffee className="w-3.5 h-3.5 text-rank-gold" />
                    )}
                    <span className="font-bold text-on-surface">
                      {e.amount} {e.type === "water" ? (locale === "ar" ? "مل" : "ml") : (locale === "ar" ? "مجم" : "mg")}
                    </span>
                    <span className="text-[10px] text-text-muted">
                      {locale === "ar" ? `الساعة ${timeStr}` : `at ${timeStr}`}
                    </span>
                  </div>
                  <button
                    onClick={() => handleSoftDelete(e)}
                    className="p-1 rounded text-text-muted hover:text-[#F87171] transition-colors cursor-pointer"
                    title={locale === "ar" ? "مسح" : "Delete"}
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { X, Plus, Check, AlertCircle } from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { useOnlineGuard } from "@/hooks/useOnlineGuard";
import { MealType, getLocalDateString } from "@/lib/nutrition";
import { useI18n } from "@/lib/i18n/I18nContext";

interface ManualFoodModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLogged: () => void;
  userTimezone: string;
}

export function ManualFoodModal({
  isOpen,
  onClose,
  onLogged,
  userTimezone,
}: ManualFoodModalProps) {
  const { isOnline, guardAction } = useOnlineGuard();
  const { locale } = useI18n();

  const [mealType, setMealType] = useState<MealType>("lunch");
  const [foodName, setFoodName] = useState("");
  const [quantity, setQuantity] = useState("1");
  const [unit, setUnit] = useState("serving");
  const [calories, setCalories] = useState("");
  const [proteinG, setProteinG] = useState("");
  const [carbsG, setCarbsG] = useState("");
  const [fatsG, setFatsG] = useState("");

  const [saving, setSaving] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  if (!isOpen) return null;

  const handleSave = async () => {
    if (!foodName.trim()) {
      setErrorMsg("Food name is required");
      return;
    }
    const cal = calories.trim() ? parseInt(calories) : null;
    const qty = parseFloat(quantity) || 1;

    guardAction(async () => {
      setSaving(true);
      setErrorMsg(null);

      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) throw new Error("Authentication required");

        const now = new Date();
        const localDate = getLocalDateString(now, userTimezone);

        const { error } = await supabase.from("meal_logs").insert([
          {
            user_id: user.id,
            logged_date: localDate,
            meal_type: mealType,
            food_name: foodName.trim(),
            quantity: qty,
            unit: unit.trim() || "serving",
            calories: cal,
            protein_g: proteinG ? parseFloat(proteinG) : 0,
            carbs_g: carbsG ? parseFloat(carbsG) : 0,
            fats_g: fatsG ? parseFloat(fatsG) : 0,
            source: "manual",
            confidence: "high",
            logged_at: now.toISOString(),
          },
        ]);

        if (error) throw error;

        onLogged();
        onClose();
      } catch (err: any) {
        setErrorMsg(err.message || "Failed to save food log");
      } finally {
        setSaving(false);
      }
    });
  };

    const MEAL_LABELS: Record<MealType, string> = {
      breakfast: locale === "ar" ? "فطار" : "breakfast",
      lunch: locale === "ar" ? "غدا" : "lunch",
      dinner: locale === "ar" ? "عشا" : "dinner",
      snack: locale === "ar" ? "سناك" : "snack",
    };

    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-charcoal-dark/80 backdrop-blur-md">
        <div className="relative w-full max-w-md bg-surface-container border border-border-subtle rounded-3xl p-6 shadow-2xl">
          <div className="flex items-center justify-between pb-4 border-b border-border-subtle">
            <div className="flex items-center gap-2">
              <Plus className="w-5 h-5 text-primary-lime" />
              <h2 className="text-base font-bold font-mono text-on-surface">
                {locale === "ar" ? "تسجيل صنف يدوي" : "Manual Food Entry"}
              </h2>
            </div>
            <button
              onClick={onClose}
              className="p-1.5 rounded-xl text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Meal Type */}
          <div className="grid grid-cols-4 gap-1.5 my-4 p-1 bg-surface-container-lowest rounded-xl border border-border-subtle">
            {(["breakfast", "lunch", "dinner", "snack"] as MealType[]).map((m) => (
              <button
                key={m}
                onClick={() => setMealType(m)}
                className={`py-2 text-[11px] font-mono uppercase tracking-wider font-semibold rounded-lg transition-all capitalize cursor-pointer ${
                  mealType === m
                    ? "bg-primary-lime text-on-primary shadow-sm font-bold"
                    : "text-text-muted hover:text-on-surface"
                }`}
              >
                {MEAL_LABELS[m]}
              </button>
            ))}
          </div>

          {errorMsg && (
            <div className="p-3 mb-4 rounded-xl bg-[#F87171]/10 border border-[#F87171]/30 flex items-start gap-2.5 text-[#F87171] text-xs font-mono">
              <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
              <span>{errorMsg}</span>
            </div>
          )}

          <div className="space-y-3.5">
            <div>
              <label className="block text-[11px] font-mono text-text-muted mb-1">
                {locale === "ar" ? "اسم الأكلة أو الصنف *" : "Food Item Name *"}
              </label>
              <input
                type="text"
                placeholder={locale === "ar" ? "مثال: سلطة فراخ مشوية" : "e.g. Grilled Chicken Salad"}
                value={foodName}
                onChange={(e) => setFoodName(e.target.value)}
                className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-primary-lime focus:outline-none"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "الكمية *" : "Quantity *"}
                </label>
                <input
                  type="number"
                  step="0.1"
                  value={quantity}
                  onChange={(e) => setQuantity(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-primary-lime focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "الوحدة" : "Unit"}
                </label>
                <input
                  type="text"
                  placeholder={locale === "ar" ? "حصة / جرام / طبق" : "serving / grams"}
                  value={unit}
                  onChange={(e) => setUnit(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-primary-lime focus:outline-none"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "السعرات (سعرة)" : "Calories (kcal)"}
                </label>
                <input
                  type="number"
                  placeholder={locale === "ar" ? "مثال: 350" : "e.g. 350"}
                  value={calories}
                  onChange={(e) => setCalories(e.target.value)}
