"use client";

import React, { useState } from "react";
import { X, Check, Calculator, AlertTriangle, ShieldCheck } from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { useOnlineGuard } from "@/hooks/useOnlineGuard";
import {
  calculateNutritionalTargets,
  getCalorieFloor,
  GoalPhase,
  CaloriePacing,
} from "@/lib/nutrition";
import { useI18n } from "@/lib/i18n/I18nContext";

interface TargetSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentProfile: {
    weightKg: number | null;
    heightCm: number | null;
    birthYear: number | null;
    sex: "male" | "female" | null;
    goalType: GoalPhase | null;
    caloriePacing: CaloriePacing | null;
    targetCalories: number | null;
    targetProteinG: number | null;
    targetCarbsG: number | null;
    targetFatsG: number | null;
    waterTargetMl: number | null;
  };
  onSaved: () => void;
}

export function TargetSettingsModal({
  isOpen,
  onClose,
  currentProfile,
  onSaved,
}: TargetSettingsModalProps) {
  const { isOnline, guardAction } = useOnlineGuard();
  const { locale } = useI18n();

  const [mode, setMode] = useState<"calculate" | "manual">("calculate");

  // Anthropometrics state
  const [weightKg, setWeightKg] = useState<string>(
    currentProfile.weightKg ? String(currentProfile.weightKg) : ""
  );
  const [heightCm, setHeightCm] = useState<string>(
    currentProfile.heightCm ? String(currentProfile.heightCm) : ""
  );
  const [birthYear, setBirthYear] = useState<string>(
    currentProfile.birthYear ? String(currentProfile.birthYear) : ""
  );
  const [sex, setSex] = useState<"male" | "female" | "">(
    currentProfile.sex || ""
  );
  const [goalType, setGoalType] = useState<GoalPhase>(
    currentProfile.goalType || "cut"
  );
  const [caloriePacing, setCaloriePacing] = useState<CaloriePacing>(
    currentProfile.caloriePacing || "optimal"
  );

  // Manual targets state
  const [manualCalories, setManualCalories] = useState<string>(
    currentProfile.targetCalories ? String(currentProfile.targetCalories) : ""
  );
  const [manualProtein, setManualProtein] = useState<string>(
    currentProfile.targetProteinG ? String(currentProfile.targetProteinG) : ""
  );
  const [manualCarbs, setManualCarbs] = useState<string>(
    currentProfile.targetCarbsG ? String(currentProfile.targetCarbsG) : ""
  );
  const [manualFats, setManualFats] = useState<string>(
    currentProfile.targetFatsG ? String(currentProfile.targetFatsG) : ""
  );
  const [manualWater, setManualWater] = useState<string>(
    currentProfile.waterTargetMl ? String(currentProfile.waterTargetMl) : ""
  );

  const [saving, setSaving] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  if (!isOpen) return null;

  // Real-time calculation preview
  const preview = calculateNutritionalTargets({
    weightKg: weightKg ? parseFloat(weightKg) : null,
    heightCm: heightCm ? parseFloat(heightCm) : null,
    birthYear: birthYear ? parseInt(birthYear) : null,
    sex: sex === "male" || sex === "female" ? sex : null,
    goalType,
    caloriePacing,
  });

  const handleSave = async () => {
    guardAction(async () => {
      setSaving(true);
      setErrorMsg(null);

      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) throw new Error("Authentication required");

        let updateData: Record<string, any> = {
          goal_type: goalType,
          calorie_pacing: caloriePacing,
          sex: sex || null,
          birth_year: birthYear ? parseInt(birthYear) : null,
          height_cm: heightCm ? parseFloat(heightCm) : null,
        };

        if (weightKg) {
          updateData.current_weight_kg = parseFloat(weightKg);
        }

        if (mode === "calculate") {
          if (!preview.targets) {
            setErrorMsg(
              `Please fill in missing fields: ${preview.missingFields.join(", ")}`
            );
            setSaving(false);
            return;
          }
          updateData.target_calories = preview.targets.calories;
          updateData.target_protein_g = preview.targets.proteinGrams;
          updateData.target_carbs_g = preview.targets.carbsGrams;
          updateData.target_fats_g = preview.targets.fatsGrams;
          updateData.water_target_ml = preview.targets.waterTargetMl;
        } else {
          // Manual mode
          const cal = parseInt(manualCalories);
          const prot = parseInt(manualProtein);
          if (isNaN(cal) || cal <= 0 || isNaN(prot) || prot <= 0) {
            setErrorMsg("Calories and Protein are required in manual mode.");
            setSaving(false);
            return;
          }
          updateData.target_calories = cal;
          updateData.target_protein_g = prot;
          updateData.target_carbs_g = manualCarbs ? parseInt(manualCarbs) : 0;
          updateData.target_fats_g = manualFats ? parseInt(manualFats) : 0;
          updateData.water_target_ml = manualWater ? parseInt(manualWater) : 3000;
        }

        const { error } = await supabase
          .from("profiles")
          .update(updateData)
          .eq("id", user.id);

        if (error) throw error;

        onSaved();
        onClose();
      } catch (err: any) {
        setErrorMsg(err.message || "Failed to update profile targets.");
      } finally {
        setSaving(false);
      }
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-charcoal-dark/80 backdrop-blur-md">
      <div className="relative w-full max-w-lg bg-surface-container border border-border-subtle rounded-3xl p-6 shadow-2xl max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between pb-4 border-b border-border-subtle">
          <div className="flex items-center gap-2">
            <Calculator className="w-5 h-5 text-secondary-cyan" />
            <h2 className="text-base font-bold font-mono text-on-surface">
              {locale === "ar" ? "أهداف التغذية والماكروز" : "Nutrition & Macro Targets"}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-xl text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Mode Switcher */}
        <div className="grid grid-cols-2 gap-2 my-4 p-1 bg-surface-container-lowest rounded-xl border border-border-subtle">
          <button
            onClick={() => setMode("calculate")}
            className={`py-2 text-xs font-mono font-semibold rounded-lg transition-all cursor-pointer ${
              mode === "calculate"
                ? "bg-secondary-cyan text-on-primary shadow-sm font-bold"
                : "text-text-muted hover:text-on-surface"
            }`}
          >
            {locale === "ar" ? "حساب تلقائي من القياسات" : "Calculate from Stats"}
          </button>
          <button
            onClick={() => setMode("manual")}
            className={`py-2 text-xs font-mono font-semibold rounded-lg transition-all cursor-pointer ${
              mode === "manual"
                ? "bg-secondary-cyan text-on-primary shadow-sm font-bold"
                : "text-text-muted hover:text-on-surface"
            }`}
          >
            {locale === "ar" ? "أهداف مخصصة يدويًا" : "Custom Manual Targets"}
          </button>
        </div>

        {errorMsg && (
          <div className="p-3 mb-4 rounded-xl bg-[#F87171]/10 border border-[#F87171]/30 flex items-start gap-2.5 text-[#F87171] text-xs font-mono">
            <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
            <span>{errorMsg}</span>
          </div>
        )}

        {mode === "calculate" ? (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "وزن الجسم (كجم) *" : "Bodyweight (kg) *"}
                </label>
                <input
                  type="number"
                  step="0.1"
                  placeholder="e.g. 78.5"
                  value={weightKg}
                  onChange={(e) => setWeightKg(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "الطول (سم) *" : "Height (cm) *"}
                </label>
                <input
                  type="number"
                  placeholder="e.g. 180"
                  value={heightCm}
                  onChange={(e) => setHeightCm(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "سنة الميلاد *" : "Birth Year *"}
                </label>
                <input
                  type="number"
                  placeholder="e.g. 2002"
                  value={birthYear}
                  onChange={(e) => setBirthYear(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "النوع البيولوجي (اختياري)" : "Biological Sex (optional)"}
                </label>
                <select
                  value={sex}
                  onChange={(e) => setSex(e.target.value as any)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                >
                  <option value="">{locale === "ar" ? "محايد (متوسط)" : "Neutral (Averaged)"}</option>
                  <option value="male">{locale === "ar" ? "ذكر" : "Male"}</option>
                  <option value="female">{locale === "ar" ? "أنثى" : "Female"}</option>
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "مرحلة الهدف" : "Goal Phase"}
                </label>
                <select
                  value={goalType}
                  onChange={(e) => setGoalType(e.target.value as GoalPhase)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                >
                  <option value="cut">
                    {locale === "ar" ? "تنشيف (خسارة دهون - 2.2 جم بروتين/كجم)" : "Cut (Fat Loss - 2.2g/kg Prot)"}
                  </option>
                  <option value="bulk">
                    {locale === "ar" ? "تضخيم (بناء عضلي - 2.0 جم بروتين/كجم)" : "Bulk (Hypertrophy - 2.0g/kg Prot)"}
                  </option>
                  <option value="recomp">
                    {locale === "ar" ? "إعادة تشكيل (تثبيت - 2.0 جم بروتين/كجم)" : "Recomp (Maintain - 2.0g/kg Prot)"}
                  </option>
                </select>
              </div>
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "معدل التغيير الأسبوعي" : "Pacing Rate"}
                </label>
                <select
                  value={caloriePacing}
                  onChange={(e) => setCaloriePacing(e.target.value as CaloriePacing)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                >
                  <option value="conservative">
                    {locale === "ar" ? "هادي (0.25 كجم/أسبوع | ±275 سعرة)" : "Conservative (0.25 kg/wk | ±275 kcal)"}
                  </option>
                  <option value="optimal">
                    {locale === "ar" ? "مثالي (0.50 كجم/أسبوع | ±550 سعرة)" : "Optimal (0.50 kg/wk | ±550 kcal)"}
                  </option>
                  <option value="aggressive">
                    {locale === "ar" ? "سريع (0.75 كجم/أسبوع | ±825 سعرة)" : "Aggressive (0.75 kg/wk | ±825 kcal)"}
                  </option>
                </select>
              </div>
            </div>

            {/* Live Calculation Preview Card */}
            {preview.targets ? (
              <div className="p-4 rounded-2xl bg-surface-container-high border border-secondary-cyan/30 space-y-2">
                <div className="flex items-center justify-between text-xs font-mono">
                  <span className="text-secondary-cyan font-bold flex items-center gap-1.5">
                    <ShieldCheck className="w-4 h-4" />
                    {locale === "ar" ? "معاينة الأهداف المحسوبة" : "Estimated Target Preview"}
                  </span>
                  {preview.targets.calorieFloorApplied && (
                    <span className="px-2 py-0.5 rounded text-[10px] bg-[#F87171]/20 text-[#F87171] border border-[#F87171]/30">
                      {locale === "ar"
                        ? `تم تطبيق الحد الأدنى الأمان (${getCalorieFloor(sex || null)} سعرة)`
                        : `Floor Applied (${getCalorieFloor(sex || null)} kcal min)`}
                    </span>
                  )}
                </div>

                <div className="grid grid-cols-4 gap-2 pt-2 text-center font-mono">
                  <div className="p-2 rounded-xl bg-surface-container-lowest">
                    <div className="text-[10px] text-text-muted">{locale === "ar" ? "السعرات" : "Calories"}</div>
                    <div className="text-sm font-bold text-on-surface">
                      {preview.targets.calories}
                    </div>
                  </div>
                  <div className="p-2 rounded-xl bg-surface-container-lowest">
                    <div className="text-[10px] text-text-muted">{locale === "ar" ? "البروتين" : "Protein"}</div>
                    <div className="text-sm font-bold text-primary-lime">
                      {preview.targets.proteinGrams}{locale === "ar" ? " جم" : "g"}
                    </div>
                  </div>
                  <div className="p-2 rounded-xl bg-surface-container-lowest">
                    <div className="text-[10px] text-text-muted">{locale === "ar" ? "الكارب" : "Carbs"}</div>
                    <div className="text-sm font-bold text-secondary-cyan">
                      {preview.targets.carbsGrams}{locale === "ar" ? " جم" : "g"}
                    </div>
                  </div>
                  <div className="p-2 rounded-xl bg-surface-container-lowest">
                    <div className="text-[10px] text-text-muted">{locale === "ar" ? "الدهون" : "Fats"}</div>
                    <div className="text-sm font-bold text-rank-gold">
                      {preview.targets.fatsGrams}{locale === "ar" ? " جم" : "g"}
                    </div>
                  </div>
                </div>

                <div className="text-[11px] font-mono text-text-muted flex justify-between pt-1">
                  <span>
                    {locale === "ar"
                      ? `هدف المية: ${preview.targets.waterTargetMl} مل`
                      : `Water Target: ${preview.targets.waterTargetMl} ml`}
                  </span>
                  <span>
                    {locale === "ar"
                      ? `معدل البروتين: ${goalType === "cut" ? "2.2 جم/كجم" : "2.0 جم/كجم"}`
                      : `Protein Rule: ${goalType === "cut" ? "2.2 g/kg" : "2.0 g/kg"}`}
                  </span>
                </div>
              </div>
            ) : (
              <div className="p-3 rounded-xl bg-surface-container-lowest border border-border-subtle text-xs font-mono text-text-muted text-center">
                {locale === "ar"
                  ? "دخل وزنك وطولك وسنة ميلادك لحساب الأهداف المقدرة."
                  : "Enter weight, height, and birth year to calculate estimated targets."}
              </div>
            )}
          </div>
        ) : (
          /* Manual Mode */
          <div className="space-y-4">
            <p className="text-xs font-mono text-text-muted">
              {locale === "ar"
                ? "حدد أهدافك اليومية بدقة. الأرقام دي مش هتتغير تلقائيًا مع تحديثات الوزن."
                : "Specify your exact daily nutrition targets. These will not be overwritten by anthropometrics."}
            </p>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "السعرات اليومية (سعرة) *" : "Daily Calories (kcal) *"}
                </label>
                <input
                  type="number"
                  placeholder="e.g. 2400"
                  value={manualCalories}
                  onChange={(e) => setManualCalories(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "البروتين اليومي (جم) *" : "Daily Protein (g) *"}
                </label>
                <input
                  type="number"
                  placeholder="e.g. 165"
                  value={manualProtein}
                  onChange={(e) => setManualProtein(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                />
              </div>
            </div>

            <div className="grid grid-cols-3 gap-3">
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "الكارب (جم)" : "Carbs (g)"}
                </label>
                <input
                  type="number"
                  placeholder="e.g. 260"
                  value={manualCarbs}
                  onChange={(e) => setManualCarbs(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "الدهون (جم)" : "Fats (g)"}
                </label>
                <input
                  type="number"
                  placeholder="e.g. 65"
                  value={manualFats}
                  onChange={(e) => setManualFats(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-[11px] font-mono text-text-muted mb-1">
                  {locale === "ar" ? "المية (مل)" : "Water (ml)"}
                </label>
                <input
                  type="number"
                  placeholder="e.g. 3000"
                  value={manualWater}
                  onChange={(e) => setManualWater(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-lowest border border-border-subtle font-mono text-sm text-on-surface focus:border-secondary-cyan focus:outline-none"
                />
              </div>
            </div>
          </div>
        )}

        <div className="flex items-center justify-end gap-3 mt-6 pt-4 border-t border-border-subtle">
          <button
            onClick={onClose}
            className="px-4 py-2.5 rounded-xl font-mono text-xs text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors cursor-pointer"
          >
            {locale === "ar" ? "إلغاء" : "Cancel"}
          </button>
          <button
            onClick={handleSave}
            disabled={saving}
            className="flex items-center gap-2 px-5 py-2.5 rounded-xl font-mono text-xs font-bold bg-secondary-cyan text-on-primary shadow-[0_0_15px_rgba(93,230,255,0.25)] hover:brightness-110 active:scale-[0.98] transition-all disabled:opacity-50 cursor-pointer"
          >
            <Check className="w-4 h-4" />
            <span>
              {saving
                ? locale === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : locale === "ar"
                ? "تطبيق وحفظ الأهداف"
                : "Apply & Save Targets"}
            </span>
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import {
  BarChart3,
  TrendingDown,
  TrendingUp,
  Scale,
  Calendar,
  Eye,
  EyeOff,
  CheckCircle2,
  AlertCircle,
  HelpCircle,
  Sparkles,
  Info,
} from "lucide-react";
import {
  calculateWeeklyNutritionAnalytics,
  MacroTargets,
} from "@/lib/nutrition";
import { supabase } from "@/lib/supabase/client";

import { useI18n } from "@/lib/i18n/I18nContext";

interface DayNutritionData {
  date: string;
  calories: number;
  proteinG: number;
  carbsG: number;
  fatsG: number;
  mealCount: number;
  isMarkedComplete?: boolean;
}

interface WeeklyAnalyticsCardProps {
  daysData: DayNutritionData[];
  targets: MacroTargets | null;
  realWeightTrendKgPerWk: number | null;
  hideAdherenceScoresDefault?: boolean;
  onOpenTargetSettings?: () => void;
}

export function WeeklyAnalyticsCard({
  daysData,
  targets,
  realWeightTrendKgPerWk,
  hideAdherenceScoresDefault = false,
  onOpenTargetSettings,
}: WeeklyAnalyticsCardProps) {
  const { locale } = useI18n();
  const [hideScores, setHideScores] = useState(hideAdherenceScoresDefault);
  const [isUpdatingPref, setIsUpdatingPref] = useState(false);

  // Compute analytics using pure library engine
  const analytics = calculateWeeklyNutritionAnalytics(
    daysData,
    targets,
    realWeightTrendKgPerWk
  );

  const toggleHideScores = async () => {
    const nextVal = !hideScores;
    setHideScores(nextVal);
    setIsUpdatingPref(true);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (user) {
        await supabase
          .from("profiles")
          .update({ hide_adherence_scores: nextVal })
          .eq("id", user.id);
      }
    } catch (e) {
      console.warn("Failed to persist hide_adherence_scores pref:", e);
    } finally {
      setIsUpdatingPref(false);
    }
  };

  // If targets are unconfigured
  if (!analytics.hasTargets) {
    return (
      <div className="p-6 rounded-3xl bg-surface-container border border-border-subtle space-y-4">
        <div className="flex items-center justify-between pb-3 border-b border-border-subtle font-mono">
          <div className="flex items-center gap-2">
            <BarChart3 className="w-4 h-4 text-secondary-cyan" />
            <span className="text-xs font-bold uppercase tracking-wider text-on-surface">
              {locale === "ar" ? "تحليلات التغذية الأسبوعية" : "Weekly Nutrition Analytics"}
            </span>
          </div>
        </div>
        <div className="p-6 rounded-2xl bg-surface-container-lowest border border-border-subtle text-center space-y-3 font-mono">
          <AlertCircle className="w-8 h-8 mx-auto text-secondary-cyan/70" />
          <div className="text-sm font-bold text-on-surface">
            {locale === "ar" ? "حدد أهدافك الغذائية" : "Set Your Targets"}
          </div>
          <p className="text-xs text-text-muted max-w-sm mx-auto">
            {locale === "ar"
              ? "حساب الالتزام الأسبوعي وتوقعات عجز السعرات محتاجة تحديد أهدافك اليومية الأول."
              : "Weekly adherence and caloric deficit projections require configured nutritional targets."}
          </p>
          {onOpenTargetSettings && (
            <button
              onClick={onOpenTargetSettings}
              className="px-4 py-2 rounded-xl text-xs font-bold bg-secondary-cyan text-on-primary hover:brightness-110 active:scale-95 transition-all cursor-pointer"
            >
              {locale === "ar" ? "ضبط الأهداف" : "Configure Targets"}
            </button>
          )}
        </div>
      </div>
    );
  }

  const targetCals = targets?.calories || 2000;
  const maxBarCals = Math.max(targetCals * 1.3, ...daysData.map((d) => d.calories), 1000);

  return (
    <div className="p-5 md:p-6 rounded-3xl bg-surface-container border border-border-subtle space-y-5">
      {/* Header & Score Visibility Toggle */}
      <div className="flex items-center justify-between pb-3 border-b border-border-subtle font-mono">
        <div className="flex items-center gap-2">
          <BarChart3 className="w-4 h-4 text-secondary-cyan" />
          <span className="text-xs font-bold uppercase tracking-wider text-on-surface">
            {locale === "ar" ? "تحليلات التغذية الأسبوعية" : "Weekly Nutrition Analytics"}
          </span>
        </div>

        <button
          onClick={toggleHideScores}
          disabled={isUpdatingPref}
          className="flex items-center gap-1.5 px-2.5 py-1 rounded-xl bg-surface-container-high border border-border-subtle text-[11px] text-text-muted hover:text-on-surface transition-colors cursor-pointer"
          title={locale === "ar" ? "تبديل إظهار الدرجات الرقمية" : "Toggle numerical adherence score visibility"}
        >
          {hideScores ? (
            <>
              <EyeOff className="w-3.5 h-3.5 text-text-muted" />
              <span>{locale === "ar" ? "الدرجات مخفية" : "Scores Hidden"}</span>
            </>
          ) : (
            <>
              <Eye className="w-3.5 h-3.5 text-secondary-cyan" />
              <span>{locale === "ar" ? "إظهار الدرجات" : "Show Scores"}</span>
            </>
          )}
        </button>
      </div>

      {/* Item 3: Headline Trend - Real Weight Trend Takes Precedence Beside Caloric Estimate */}
      <div className="p-4 rounded-2xl bg-surface-container-lowest border border-border-subtle space-y-2 font-mono">
        <div className="flex items-center justify-between text-[11px] uppercase tracking-wider text-text-muted">
          <span>{locale === "ar" ? "المسار الأسبوعي" : "Weekly Trajectory"}</span>
          <span className="flex items-center gap-1">
            <Scale className="w-3.5 h-3.5 text-secondary-cyan" />
            {analytics.headlineTrend.source === "weigh_in"
              ? locale === "ar"
                ? "معدل الميزان الحقيقي (الأساسي)"
                : "Real Scale Trend (Primary)"
              : locale === "ar"
              ? "تقدير السعرات المتناولة"
              : "Caloric Intake Estimate"}
          </span>
        </div>

        <div className="flex flex-wrap items-baseline gap-3">
          <div className="text-2xl font-extrabold text-on-surface">
            {analytics.headlineTrend.valueFormatted}
          </div>

          {/* Show caloric estimate beside the real trend if both exist */}
          {analytics.headlineTrend.source === "weigh_in" &&
            analytics.projectedWeightChangeKgPerWk !== null && (
              <div className="text-xs text-text-muted bg-surface-container-high px-2.5 py-1 rounded-lg border border-border-subtle">
                {locale === "ar" ? "تقدير استهلاك السعرات: " : "Caloric intake estimate: "}
                <span className="font-semibold text-on-surface">
                  {analytics.projectedWeightChangeKgPerWk > 0 ? "+" : ""}
                  {analytics.projectedWeightChangeKgPerWk.toFixed(2)} {locale === "ar" ? "كجم/أسبوع" : "kg/wk"}
                </span>
              </div>
            )}
        </div>

        <p className="text-[11px] text-text-muted leading-relaxed">
          {analytics.headlineTrend.description}
        </p>
      </div>

      {/* Adherence Score & Qualifying Days Status */}
      {!analytics.hasEnoughDays ? (
        /* Honest Insufficient Logged Days State (Item 2) */
        <div className="p-4 rounded-2xl bg-surface-container-high/60 border border-border-subtle space-y-2 font-mono text-center">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-xl bg-surface-container border border-border-subtle text-xs font-bold text-text-muted">
            <AlertCircle className="w-3.5 h-3.5 text-rank-gold" />
            <span>{locale === "ar" ? "أيام التسجيل مش كافية" : "Not enough logged days"}</span>
          </div>
          <p className="text-xs text-text-muted">
            {locale === "ar" ? (
              <>
                بناءً على <span className="text-on-surface font-bold">{analytics.qualifyingDaysCount} من 7 أيام متسجلة</span>.
                <br />
                محتاج 4 أيام مؤهلة على الأقل (أكتر من 40% من الهدف أو 3+ وجبات) لحساب الالتزام الأسبوعي بدقة.
              </>
            ) : (
              <>
                Based on <span className="text-on-surface font-bold">{analytics.qualifyingDaysCount} of 7 logged days</span>.
                <br />
                Minimum 4 qualifying days (&ge; 40% target or 3+ meals) required to compute weekly adherence.
              </>
            )}
          </p>
        </div>
      ) : (
        /* Configured & Qualifying Adherence Telemetry */
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 font-mono">
          {/* Adherence Score Box */}
          <div className="p-4 rounded-2xl bg-surface-container-lowest border border-border-subtle space-y-2">
            <div className="flex items-center justify-between text-xs">
              <span className="text-text-muted uppercase tracking-wider text-[11px]">
                {locale === "ar" ? "الالتزام بالعناصر" : "Macro Adherence"}
              </span>
              <span className="text-[11px] font-semibold text-primary-lime">
                {analytics.adherenceLabel}
              </span>
            </div>

            <div className="flex items-baseline gap-2">
              {hideScores ? (
                <div className="text-xl font-bold text-on-surface">
                  {analytics.adherenceLabel}
                </div>
              ) : (
                <>
                  <span className="text-3xl font-extrabold text-on-surface">
                    {analytics.adherenceScore}%
                  </span>
                  <span className="text-xs text-text-muted">{locale === "ar" ? "التزام" : "adherence"}</span>
                </>
              )}
            </div>

            <div className="text-[11px] text-text-muted">
              {locale === "ar" ? (
                <>
                  بناءً على{" "}
                  <span className="text-on-surface font-semibold">
                    {analytics.qualifyingDaysCount} من 7 أيام متسجلة
                  </span>
                </>
              ) : (
                <>
                  Based on{" "}
                  <span className="text-on-surface font-semibold">
                    {analytics.qualifyingDaysCount} of 7 logged days
                  </span>
                </>
              )}
            </div>
          </div>

          {/* Average Intake Box */}
          <div className="p-4 rounded-2xl bg-surface-container-lowest border border-border-subtle space-y-2">
            <div className="text-xs text-text-muted uppercase tracking-wider text-[11px]">
              {locale === "ar" ? "المتوسط اليومي (للأيام المؤهلة)" : "Daily Averages (Qualifying)"}
            </div>
            <div className="text-xl font-bold text-on-surface">
              {analytics.averageCalories} {locale === "ar" ? "سعرة" : "kcal"}
            </div>
            <div className="flex items-center gap-3 text-[11px] text-text-muted">
              <span className="text-primary-lime">
                {analytics.averageProteinG}{locale === "ar" ? " جم ب" : "g P"}
              </span>
              <span className="text-secondary-cyan">
                {analytics.averageCarbsG}{locale === "ar" ? " جم ك" : "g C"}
              </span>
              <span className="text-rank-gold">
                {analytics.averageFatsG}{locale === "ar" ? " جم د" : "g F"}
              </span>
            </div>
          </div>
        </div>
      )}

      {/* 7-Day Intake Bar Chart vs Target Baseline */}
      <div className="space-y-3 font-mono">
        <div className="flex items-center justify-between text-xs text-text-muted">
          <span>{locale === "ar" ? "استهلاك السعرات لآخر 7 أيام" : "7-Day Daily Caloric Intake"}</span>
          <span className="text-[11px]">
            {locale === "ar" ? "الهدف: " : "Target: "}
            <span className="text-secondary-cyan font-bold">
              {targetCals} {locale === "ar" ? "سعرة" : "kcal"}
            </span>
          </span>
        </div>

        <div className="grid grid-cols-7 gap-1.5 md:gap-2 pt-4 pb-2 items-end min-h-[140px] bg-surface-container-lowest p-3 rounded-2xl border border-border-subtle">
          {daysData.map((d, idx) => {
            const dayScoreObj = analytics.dailyScores.find((s) => s.date === d.date);
            const isQualifying = dayScoreObj?.qualifying ?? false;
            const heightPercent = Math.min(100, Math.round((d.calories / maxBarCals) * 100));
            const dayName = new Date(d.date + "T12:00:00Z").toLocaleDateString(locale === "ar" ? "ar-EG" : undefined, {
              weekday: "narrow",
            });

            return (
              <div key={d.date} className="flex flex-col items-center gap-1.5 h-full justify-end">
                {/* Bar Value Tooltip */}
                <span className="text-[9px] text-text-muted text-center font-bold">
                  {d.calories > 0 ? `${Math.round(d.calories / 100) * 100}` : "0"}
                </span>

                {/* Bar Container */}
                <div className="w-full max-w-[28px] h-20 bg-surface-container rounded-lg overflow-hidden flex flex-col justify-end relative">
                  {/* Target reference indicator */}
                  <div
                    className="absolute w-full border-b border-dashed border-secondary-cyan/40 z-10"
                    style={{ bottom: `${Math.round((targetCals / maxBarCals) * 100)}%` }}
                    title={locale === "ar" ? `الهدف: ${targetCals} سعرة` : `Target: ${targetCals} kcal`}
                  />

                  {/* Filled bar */}
                  <div
                    className={`w-full rounded-b-lg transition-all duration-300 ${
                      isQualifying
                        ? d.calories > targetCals * 1.15
                          ? "bg-rank-gold"
                          : "bg-secondary-cyan"
                        : "bg-surface-container-highest"
                    }`}
                    style={{ height: `${heightPercent}%` }}
                  />
                </div>

                {/* Day Label & Qualifying Indicator */}
                <div className="flex flex-col items-center">
                  <span className="text-[10px] font-bold text-on-surface uppercase">
                    {dayName}
                  </span>
                  <div
                    className={`w-1.5 h-1.5 rounded-full mt-0.5 ${
                      isQualifying ? "bg-primary-lime" : "bg-text-muted/30"
                    }`}
                    title={
                      isQualifying
                        ? locale === "ar" ? "يوم مؤهل ومكتمل" : "Qualifying day"
                        : locale === "ar" ? "تسجيل جزئي / غير مكتمل" : "Partial / Unlogged day"
                    }
                  />
                </div>
              </div>
            );
          })}
        </div>

        {/* Legend */}
        <div className="flex items-center justify-between text-[10px] text-text-muted pt-1">
          <div className="flex items-center gap-3">
            <span className="flex items-center gap-1">
              <span className="w-2 h-2 rounded-full bg-primary-lime" />
              <span>{locale === "ar" ? "يوم مكتمل" : "Qualifying day"}</span>
            </span>
            <span className="flex items-center gap-1">
              <span className="w-2 h-2 rounded-full bg-text-muted/30" />
              <span>{locale === "ar" ? "تسجيل جزئي" : "Partial / Non-qualifying"}</span>
            </span>
          </div>
          <span className="italic">{locale === "ar" ? "محتاج 4 أيام مؤهلة على الأقل" : "Min 4 qualifying days needed"}</span>
        </div>
      </div>
    </div>
  );
}

