"use client";

import React, { useState, useEffect } from "react";
import {
  GradeItem,
  SubjectItem,
  GradeType,
  validateGradeInput,
} from "@/lib/school";
import { useI18n } from "@/lib/i18n/I18nContext";
import { X, Loader2, AlertCircle, Award } from "lucide-react";

interface GradeModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (grade: {
    subject_id: string;
    type: GradeType;
    title: string;
    mark_achieved: number;
    mark_total: number;
    weight_pct: number | null;
    entry_date: string;
    note: string | null;
  }) => Promise<void>;
  subjects: SubjectItem[];
  preselectedSubjectId?: string;
  initialGrade?: GradeItem | null;
  isBlocked?: boolean;
}

export function GradeModal({
  isOpen,
  onClose,
  onSave,
  subjects,
  preselectedSubjectId,
  initialGrade,
  isBlocked = false,
}: GradeModalProps) {
  const { locale } = useI18n();
  const [subjectId, setSubjectId] = useState("");
  const [type, setType] = useState<GradeType>("quiz");
  const [title, setTitle] = useState("");
  const [markAchieved, setMarkAchieved] = useState("");
  const [markTotal, setMarkTotal] = useState("100");
  const [weightPct, setWeightPct] = useState("");
  const [entryDate, setEntryDate] = useState("");
  const [note, setNote] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Helper to get local date in YYYY-MM-DD
  const getTodayLocalDateStr = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, "0");
    const day = String(now.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  };

  useEffect(() => {
    if (initialGrade) {
      setSubjectId(initialGrade.subject_id);
      setType(initialGrade.type);
      setTitle(initialGrade.title);
      setMarkAchieved(String(initialGrade.mark_achieved));
      setMarkTotal(String(initialGrade.mark_total));
      setWeightPct(
        initialGrade.weight_pct !== null && initialGrade.weight_pct !== undefined
          ? String(initialGrade.weight_pct)
          : ""
      );
      setEntryDate(initialGrade.entry_date || getTodayLocalDateStr());
      setNote(initialGrade.note || "");
    } else {
      setSubjectId(
        preselectedSubjectId ||
          (subjects.length > 0 ? subjects[0].id : "")
      );
      setType("quiz");
      setTitle("");
      setMarkAchieved("");
      setMarkTotal("100");
      setWeightPct("");
      setEntryDate(getTodayLocalDateStr());
      setNote("");
    }
    setError(null);
  }, [initialGrade, preselectedSubjectId, subjects, isOpen]);

  if (!isOpen) return null;

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);

    if (isBlocked) {
      setError("Offline: saving disabled to protect sync integrity.");
      return;
    }

    if (!subjectId) {
      setError("Please select a subject.");
      return;
    }

    const numAchieved = parseFloat(markAchieved);
    const numTotal = parseFloat(markTotal);
    const parsedWeight =
      weightPct.trim() !== "" ? parseFloat(weightPct) : null;

    if (isNaN(numAchieved) || isNaN(numTotal)) {
      setError("Please enter valid numeric marks.");
      return;
    }

    const validation = validateGradeInput({
      type,
      title: title.trim(),
      mark_achieved: numAchieved,
      mark_total: numTotal,
      weight_pct: parsedWeight,
    });

    if (!validation.valid) {
      setError(validation.error || "Invalid grade values.");
      return;
    }

    if (!entryDate) {
      setError("Entry date is required.");
      return;
    }

    try {
      setSaving(true);
      await onSave({
        subject_id: subjectId,
        type,
        title: title.trim(),
        mark_achieved: numAchieved,
        mark_total: numTotal,
        weight_pct: parsedWeight,
        entry_date: entryDate,
        note: note.trim() || null,
      });
      onClose();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to record grade";
      setError(msg);
    } finally {
      setSaving(false);
    }
  }

  const computedPct =
    !isNaN(parseFloat(markAchieved)) &&
    !isNaN(parseFloat(markTotal)) &&
    parseFloat(markTotal) > 0
      ? Math.round(
          (parseFloat(markAchieved) / parseFloat(markTotal)) * 1000
        ) / 10
      : null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-bg-darkest/80 backdrop-blur-md">
      <div
        className="w-full max-w-md bg-surface-container border border-border-subtle rounded-2xl p-6 shadow-2xl space-y-4 max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between pb-3 border-b border-border-subtle">
          <div className="flex items-center gap-2">
            <Award className="w-5 h-5 text-amber-400" />
            <h3 className="text-base font-bold font-mono text-on-surface">
              {locale === "ar"
                ? initialGrade ? "تعديل الدرجة" : "تسجيل درجة جديدة"
                : initialGrade ? "Edit Grade Entry" : "Record Grade"}
            </h3>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-lg text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {error && (
          <div className="p-3 bg-crimson-alert/10 border border-crimson-alert/30 rounded-xl flex items-center gap-2 text-crimson-alert text-xs font-mono">
            <AlertCircle className="w-4 h-4 shrink-0" />
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Subject Selector */}
          <div className="space-y-1.5">
            <label className="text-xs font-mono text-on-surface-variant">
              {locale === "ar" ? "المادة *" : "Subject *"}
            </label>
            <select
              value={subjectId}
              onChange={(e) => setSubjectId(e.target.value)}
              required
              className="w-full px-3.5 py-2.5 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface focus:outline-none focus:border-amber-400 transition-colors"
            >
              <option value="" disabled>
                {locale === "ar" ? "اختر المادة" : "Select subject"}
              </option>
              {subjects.map((sub) => (
                <option key={sub.id} value={sub.id}>
                  {sub.name} {sub.code ? `(${sub.code})` : ""}
                </option>
              ))}
            </select>
          </div>

          {/* Grade Type: Strictly 'quiz' vs 'big_exam' */}
          <div className="space-y-1.5">
            <label className="text-xs font-mono text-on-surface-variant">
              {locale === "ar" ? "نوع التقييم * (كويز أو امتحان رئيسي)" : "Assessment Type * (2 Types Only)"}
            </label>
            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => setType("quiz")}
                className={`py-2 px-3 rounded-xl border text-xs font-mono flex items-center justify-center gap-2 transition-all ${
                  type === "quiz"
                    ? "border-amber-400 bg-amber-400/10 text-amber-300 font-semibold shadow-sm"
                    : "border-border-subtle bg-surface-container-low text-text-muted hover:border-border-medium"
                }`}
              >
                <span className="w-2.5 h-2.5 rounded-full bg-amber-400 inline-block" />
                <span>{locale === "ar" ? "كويز (دائرة)" : "Quiz (Circle)"}</span>
              </button>
              <button
                type="button"
                onClick={() => setType("big_exam")}
                className={`py-2 px-3 rounded-xl border text-xs font-mono flex items-center justify-center gap-2 transition-all ${
                  type === "big_exam"
                    ? "border-indigo-400 bg-indigo-400/10 text-indigo-300 font-semibold shadow-sm"
                    : "border-border-subtle bg-surface-container-low text-text-muted hover:border-border-medium"
                }`}
              >
                <span className="w-2.5 h-2.5 rotate-45 bg-indigo-400 inline-block" />
                <span>{locale === "ar" ? "امتحان رئيسي (معين)" : "Big Exam (Diamond)"}</span>
              </button>
            </div>
          </div>

          {/* Title Input with dir="auto" */}
          <div className="space-y-1.5">
            <label className="text-xs font-mono text-on-surface-variant">
              {locale === "ar" ? "عنوان التقييم *" : "Assessment Title *"}
            </label>
            <input
              type="text"
              dir="auto"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={locale === "ar" ? "مثال: كويز ميكانيكا 1، امتحان نص الترم" : "e.g. Thermodynamics Quiz 1, Midterm Exam, كويز 1"}
              required
              className="w-full px-3.5 py-2.5 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface focus:outline-none focus:border-amber-400 placeholder:text-text-muted transition-colors font-sans"
            />
          </div>

          {/* Mark Achieved & Mark Total */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <label className="text-xs font-mono text-on-surface-variant">
                {locale === "ar" ? "الدرجة المحققة *" : "Mark Achieved *"}
              </label>
              <input
                type="number"
                min="0"
                step="any"
                value={markAchieved}
                onChange={(e) => setMarkAchieved(e.target.value)}
                placeholder="e.g. 18.5"
                required
                className="w-full px-3.5 py-2.5 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface font-mono focus:outline-none focus:border-amber-400 placeholder:text-text-muted transition-colors"
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-mono text-on-surface-variant">
                {locale === "ar" ? "الدرجة النهائية * (> 0)" : "Total Mark * (> 0)"}
              </label>
              <input
                type="number"
                min="0.01"
                step="any"
                value={markTotal}
                onChange={(e) => setMarkTotal(e.target.value)}
                placeholder="e.g. 20"
                required
                className="w-full px-3.5 py-2.5 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface font-mono focus:outline-none focus:border-amber-400 placeholder:text-text-muted transition-colors"
              />
            </div>
          </div>

          {/* Computed Percentage Preview */}
          {computedPct !== null && (
            <div className="px-3.5 py-2 rounded-xl bg-surface-container-low border border-border-subtle flex items-center justify-between text-xs font-mono">
              <span className="text-text-muted">
                {locale === "ar" ? "النسبة المئوية:" : "Score Percentage:"}
              </span>
              <span
                className={`font-bold ${
                  computedPct >= 80
                    ? "text-emerald-400"
                    : computedPct >= 60
                    ? "text-amber-400"
                    : "text-crimson-alert"
                }`}
              >
                {computedPct}%
              </span>
            </div>
          )}

          {/* Coursework Weight % & Entry Date */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <label className="text-xs font-mono text-on-surface-variant flex items-center justify-between">
                <span>{locale === "ar" ? "الوزن النسبي %" : "Weight %"}</span>
                <span className="text-[10px] text-text-muted">
                  {locale === "ar" ? "اختياري" : "Optional"}
                </span>
              </label>
              <input
                type="number"
                min="0"
                max="100"
                step="any"
                value={weightPct}
                onChange={(e) => setWeightPct(e.target.value)}
                placeholder="e.g. 15"
                className="w-full px-3.5 py-2.5 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface font-mono focus:outline-none focus:border-amber-400 placeholder:text-text-muted transition-colors"
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-mono text-on-surface-variant">
                {locale === "ar" ? "تاريخ التقييم *" : "Entry Date *"}
              </label>
              <input
                type="date"
                value={entryDate}
                onChange={(e) => setEntryDate(e.target.value)}
                required
                className="w-full px-3.5 py-2.5 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface font-mono focus:outline-none focus:border-amber-400 transition-colors"
              />
            </div>
          </div>

          {/* Notes (Optional) */}
          <div className="space-y-1.5">
            <label className="text-xs font-mono text-on-surface-variant">
              {locale === "ar" ? "ملاحظات (اختياري)" : "Notes (Optional)"}
            </label>
            <textarea
              dir="auto"
              value={note}
              onChange={(e) => setNote(e.target.value)}
              placeholder={locale === "ar" ? "مثال: نقصت في الاستنتاج؛ محتاج مراجعة على الشابتر التالت" : "e.g. Lost marks on derivation; revision needed on chapter 3"}
              rows={2}
              className="w-full px-3.5 py-2 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface focus:outline-none focus:border-amber-400 placeholder:text-text-muted transition-colors font-sans resize-none"
            />
          </div>

          {/* Modal Actions */}
          <div className="flex items-center justify-end gap-3 pt-3 border-t border-border-subtle">
            <button
              type="button"
              onClick={onClose}
              disabled={saving}
              className="px-4 py-2 rounded-xl text-xs font-mono text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
            >
              {locale === "ar" ? "إلغاء" : "Cancel"}
            </button>
            <button
              type="submit"
              disabled={saving || isBlocked}
              className="flex items-center gap-2 px-5 py-2 rounded-xl bg-amber-500 text-on-primary text-xs font-mono font-semibold uppercase tracking-wider hover:bg-amber-400 disabled:opacity-50 shadow-[0_0_16px_rgba(245,158,11,0.25)] transition-all cursor-pointer"
            >
              {saving ? (
                <>
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  <span>{locale === "ar" ? "جاري الحفظ..." : "Saving..."}</span>
                </>
              ) : (
                <span>
                  {locale === "ar"
                    ? initialGrade ? "تحديث الدرجة" : "حفظ الدرجة"
                    : initialGrade ? "Update Grade" : "Save Grade"}
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import React, { useState } from "react";
import { GradeItem, calculateGradePercentage, round1 } from "@/lib/school";
import { useI18n } from "@/lib/i18n/I18nContext";

interface GradeTrendChartProps {
  grades: GradeItem[];
  targetGrade?: number | null;
  subjectColor?: string;
}

type RangeOption = "30D" | "90D" | "ALL";

export function GradeTrendChart({
  grades,
  targetGrade,
  subjectColor = "#F59E0B",
}: GradeTrendChartProps) {
  const { locale } = useI18n();
  const [range, setRange] = useState<RangeOption>("ALL");
  const [hoveredGrade, setHoveredGrade] = useState<{
    grade: GradeItem;
    x: number;
    y: number;
    pct: number;
  } | null>(null);

  const filteredGrades = React.useMemo(() => {
    const active = [...grades]
      .filter((g) => !g.deleted_at && g.mark_total > 0 && g.mark_achieved >= 0)
      .sort(
        (a, b) =>
          new Date(a.entry_date).getTime() - new Date(b.entry_date).getTime()
      );

    if (range === "ALL") return active;

    const days = range === "30D" ? 30 : 90;
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - days);
    const cutoffStr = cutoff.toISOString().split("T")[0];

    return active.filter((g) => g.entry_date >= cutoffStr);
  }, [grades, range]);

  const activeGrades = filteredGrades;

  if (activeGrades.length === 0) {
    return (
      <div className="h-44 flex flex-col items-center justify-center bg-surface-container/50 rounded-xl border border-border-subtle p-4 text-center">
        <p className="text-xs font-mono text-on-surface-variant">
          {locale === "ar" ? "لا توجد درجات مسجلة بعد" : "No grade entries yet"}
        </p>
        <p className="text-[11px] text-text-muted mt-0.5">
          {locale === "ar"
            ? "سجل الكويزات والامتحانات لمتابعة تطور درجاتك"
            : "Log quizzes and big exams to visualize score progression"}
        </p>
      </div>
    );
  }

  // SVG dimensions
  const width = 500;
  const height = 180;
  const padLeft = 35;
  const padRight = 20;
  const padTop = 20;
  const padBottom = 30;

  const chartWidth = width - padLeft - padRight;
  const chartHeight = height - padTop - padBottom;

  // Y-axis bounds: min 0, max 100
  const minY = 0;
  const maxY = 100;

  function getY(pct: number) {
    const clamped = Math.max(minY, Math.min(maxY, pct));
    return padTop + chartHeight - ((clamped - minY) / (maxY - minY)) * chartHeight;
  }

  function getX(index: number, total: number) {
    if (total <= 1) return padLeft + chartWidth / 2;
    return padLeft + (index / (total - 1)) * chartWidth;
  }

  // Calculate points
  const points = activeGrades.map((g, idx) => {
    const pct = calculateGradePercentage(g.mark_achieved, g.mark_total);
    const x = getX(idx, activeGrades.length);
    const y = getY(pct);
    return { grade: g, pct, x, y };
  });

  // Polyline path
  const linePath =
    points.length > 1
      ? points.map((p, idx) => `${idx === 0 ? "M" : "L"} ${p.x} ${p.y}`).join(" ")
      : "";

  const targetY =
    targetGrade !== null && targetGrade !== undefined
      ? getY(targetGrade)
      : null;

  return (
    <div className="space-y-2">
      {/* Legend & Target Note */}
      <div className="flex flex-wrap items-center justify-between text-[11px] font-mono text-on-surface-variant px-1 gap-2">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-amber-400 inline-block" />
            <span>{locale === "ar" ? "كويز (دائرة)" : "Quiz (Circle)"}</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rotate-45 bg-indigo-400 inline-block" />
            <span>{locale === "ar" ? "امتحان رئيسي (معين)" : "Big Exam (Diamond)"}</span>
          </div>
          {targetY !== null && (
            <div className="flex items-center gap-1.5">
              <span className="w-3 border-b-2 border-dashed border-emerald-400 inline-block" />
              <span>{locale === "ar" ? `المستهدف (${targetGrade}%)` : `Target (${targetGrade}%)`}</span>
            </div>
          )}
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center bg-surface-container-highest p-0.5 rounded-lg border border-border-subtle font-mono text-[10px]">
            {(["30D", "90D", "ALL"] as RangeOption[]).map((r) => {
              const rangeLabels: Record<RangeOption, string> = {
                "30D": locale === "ar" ? "30 يوم" : "30D",
                "90D": locale === "ar" ? "90 يوم" : "90D",
                ALL: locale === "ar" ? "الكل" : "ALL",
              };
              return (
                <button
                  key={r}
                  type="button"
                  onClick={() => setRange(r)}
                  className={`px-2 py-0.5 rounded-md font-semibold transition-all cursor-pointer ${
                    range === r
                      ? "bg-amber-400 text-on-primary shadow-sm"
                      : "text-text-muted hover:text-on-surface"
                  }`}
                >
                  {rangeLabels[r]}
                </button>
              );
            })}
          </div>
          <span className="text-[10px] text-text-muted">
            {locale === "ar"
              ? `${activeGrades.length} تقييم`
              : `${activeGrades.length} ${activeGrades.length === 1 ? "entry" : "entries"}`}
          </span>
        </div>
      </div>

      {/* SVG Canvas */}
      <div className="relative w-full overflow-hidden rounded-xl bg-surface-container/60 border border-border-subtle p-2">
        <svg
          viewBox={`0 0 ${width} ${height}`}
          className="w-full h-auto max-h-48 overflow-visible select-none"
        >
          {/* Grid lines (0%, 25%, 50%, 75%, 100%) */}
          {[0, 25, 50, 75, 100].map((val) => {
            const y = getY(val);
            return (
              <g key={val}>
                <line
                  x1={padLeft}
                  y1={y}
                  x2={width - padRight}
                  y2={y}
                  stroke="rgba(255, 255, 255, 0.07)"
                  strokeWidth="1"
                />
                <text
                  x={padLeft - 6}
                  y={y + 3}
                  textAnchor="end"
                  className="fill-text-muted text-[9px] font-mono"
                >
                  {val}%
                </text>
              </g>
            );
          })}

          {/* Target Grade Reference Line */}
          {targetY !== null && (
            <line
              x1={padLeft}
              y1={targetY}
              x2={width - padRight}
              y2={targetY}
              stroke="#10B981"
              strokeWidth="1.5"
              strokeDasharray="4 4"
              opacity="0.8"
            />
          )}

          {/* Connection Line */}
          {linePath && (
            <path
              d={linePath}
              fill="none"
              stroke={subjectColor || "#F59E0B"}
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              opacity="0.85"
            />
          )}

          {/* Points (Circles for Quizzes, Diamonds for Big Exams) */}
          {points.map((pt, idx) => {
            const isQuiz = pt.grade.type === "quiz";
            const isHovered = hoveredGrade?.grade.id === pt.grade.id;

            return (
              <g
                key={pt.grade.id || idx}
                className="cursor-pointer"
                onMouseEnter={() => setHoveredGrade(pt)}
                onMouseLeave={() => setHoveredGrade(null)}
                onClick={() => setHoveredGrade(pt)}
              >
                {/* Hit area */}
                <circle cx={pt.x} cy={pt.y} r="14" fill="transparent" />

                {isQuiz ? (
                  // Quiz = Circle
                  <circle
                    cx={pt.x}
                    cy={pt.y}
                    r={isHovered ? 6 : 4.5}
                    fill="#F59E0B"
                    stroke="#18181B"
                    strokeWidth="1.5"
                    className="transition-all duration-150"
                  />
                ) : (
                  // Big Exam = Diamond (Polygon)
                  <polygon
                    points={`
                      ${pt.x},${pt.y - (isHovered ? 7 : 5.5)} 
                      ${pt.x + (isHovered ? 7 : 5.5)},${pt.y} 
                      ${pt.x},${pt.y + (isHovered ? 7 : 5.5)} 
                      ${pt.x - (isHovered ? 7 : 5.5)},${pt.y}
                    `}
                    fill="#818CF8"
                    stroke="#18181B"
                    strokeWidth="1.5"
                    className="transition-all duration-150"
                  />
                )}
              </g>
            );
          })}
        </svg>

        {/* Hover / Tap Tooltip */}
        {hoveredGrade && (
          <div
            className="absolute z-20 pointer-events-none bg-surface-container-high border border-border-medium rounded-lg p-2 shadow-xl text-left font-mono"
            style={{
              left: `${Math.min(75, Math.max(10, (hoveredGrade.x / width) * 100))}%`,
              top: `${Math.max(10, (hoveredGrade.y / height) * 70)}%`,
            }}
          >
            <div className="flex items-center gap-1.5">
              <span
                className={`text-[9px] px-1.5 py-0.5 rounded font-semibold uppercase ${
                  hoveredGrade.grade.type === "quiz"
                    ? "bg-amber-400/20 text-amber-300"
                    : "bg-indigo-400/20 text-indigo-300"
                }`}
              >
                {hoveredGrade.grade.type === "quiz"
                  ? locale === "ar"
                    ? "كويز"
                    : "Quiz"
                  : locale === "ar"
                  ? "امتحان رئيسي"
                  : "Big Exam"}
              </span>
              <span className="text-[10px] text-text-muted">
                {hoveredGrade.grade.entry_date}
              </span>
            </div>
            <div className="text-xs font-bold text-on-surface mt-1 truncate max-w-[180px]">
              {hoveredGrade.grade.title}
            </div>
            <div className="text-xs text-amber-400 font-semibold mt-0.5">
              {hoveredGrade.pct}%{" "}
              <span className="text-[10px] text-on-surface-variant font-normal">
                ({hoveredGrade.grade.mark_achieved} / {hoveredGrade.grade.mark_total})
              </span>
            </div>
            {hoveredGrade.grade.weight_pct !== null &&
              hoveredGrade.grade.weight_pct !== undefined && (
                <div className="text-[10px] text-text-muted mt-0.5">
                  {locale === "ar" ? "الوزن:" : "Weight:"} {hoveredGrade.grade.weight_pct}%
                </div>
              )}
          </div>
        )}
      </div>
    </div>
  );
}

