"use client";

import React, { useState, useEffect, useMemo } from "react";
import {
  ScheduleItem,
  SubjectItem,
  SessionType,
  checkSessionOverlap,
  parseTimeToMinutes,
  normalizeTimeString,
} from "@/lib/school";
import { formatTimeRange12h } from "@/lib/time";
import { useI18n } from "@/lib/i18n/I18nContext";

interface SessionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (session: {
    subject_id: string;
    day_of_week: number;
    start_time: string;
    end_time: string;
    location?: string | null;
    session_type: SessionType;
  }) => Promise<void>;
  subjects: SubjectItem[];
  existingSessions: ScheduleItem[];
  initialData?: ScheduleItem | null;
  initialDayOfWeek?: number;
}

const SESSION_TYPES: { type: SessionType; labelEn: string; labelAr: string; tokenClass: string }[] = [
  { type: "lecture", labelEn: "Lecture", labelAr: "محاضرة", tokenClass: "session-lecture" },
  { type: "lab", labelEn: "Lab", labelAr: "معمل", tokenClass: "session-lab" },
  { type: "section", labelEn: "Section", labelAr: "سكشن", tokenClass: "session-section" },
  { type: "seminar", labelEn: "Seminar", labelAr: "سيمنار", tokenClass: "session-seminar" },
];

const DAYS_OF_WEEK_EN = [
  { value: 0, label: "Sunday" },
  { value: 1, label: "Monday" },
  { value: 2, label: "Tuesday" },
  { value: 3, label: "Wednesday" },
  { value: 4, label: "Thursday" },
  { value: 5, label: "Friday" },
  { value: 6, label: "Saturday" },
];

const DAYS_OF_WEEK_AR = [
  { value: 0, label: "الأحد" },
  { value: 1, label: "الإثنين" },
  { value: 2, label: "الثلاثاء" },
  { value: 3, label: "الأربعاء" },
  { value: 4, label: "الخميس" },
  { value: 5, label: "الجمعة" },
  { value: 6, label: "السبت" },
];

export function SessionModal({
  isOpen,
  onClose,
  onSave,
  subjects,
  existingSessions,
  initialData,
  initialDayOfWeek = 0,
}: SessionModalProps) {
  const { locale } = useI18n();
  const activeSubjects = useMemo(
    () => subjects.filter((s) => !s.deleted_at && !s.archived),
    [subjects]
  );

  const [subjectId, setSubjectId] = useState<string>("");
  const [dayOfWeek, setDayOfWeek] = useState<number>(initialDayOfWeek);
  const [startTime, setStartTime] = useState<string>("09:00");
  const [endTime, setEndTime] = useState<string>("10:30");
  const [location, setLocation] = useState<string>("");
  const [sessionType, setSessionType] = useState<SessionType>("lecture");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const daysList = locale === "ar" ? DAYS_OF_WEEK_AR : DAYS_OF_WEEK_EN;

  useEffect(() => {
    if (initialData) {
      setSubjectId(initialData.subject_id);
      setDayOfWeek(initialData.day_of_week);
      setStartTime(normalizeTimeString(initialData.start_time));
      setEndTime(normalizeTimeString(initialData.end_time));
      setLocation(initialData.location || "");
      setSessionType(initialData.session_type);
    } else {
      setSubjectId(activeSubjects[0]?.id || "");
      setDayOfWeek(initialDayOfWeek);
      setStartTime("09:00");
      setEndTime("10:30");
      setLocation("");
      setSessionType("lecture");
    }
    setError(null);
  }, [initialData, initialDayOfWeek, activeSubjects, isOpen]);

  // Pure advisory collision check
  const advisoryConflict = useMemo(() => {
    if (!startTime || !endTime) return null;
    const currentCandidate = {
      day_of_week: dayOfWeek,
      start_time: startTime,
      end_time: endTime,
    };

    const conflictingSession = existingSessions.find((sess) => {
      if (sess.deleted_at) return false;
      if (initialData && sess.id === initialData.id) return false; // ignore self
      // Exclude archived subjects
      const sub = subjects.find((s) => s.id === sess.subject_id);
      if (!sub || sub.archived || sub.deleted_at) return false;

      return checkSessionOverlap(currentCandidate, {
        day_of_week: sess.day_of_week,
        start_time: sess.start_time,
        end_time: sess.end_time,
      });
    });

    if (conflictingSession) {
      const sub = subjects.find((s) => s.id === conflictingSession.subject_id);
      return {
        subjectName: sub?.name || (locale === "ar" ? "حصة حالية" : "Existing Class"),
        start: normalizeTimeString(conflictingSession.start_time),
        end: normalizeTimeString(conflictingSession.end_time),
      };
    }
    return null;
  }, [dayOfWeek, startTime, endTime, existingSessions, initialData, subjects, locale]);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!subjectId) {
      setError(locale === "ar" ? "من فضلك اختار المادة الدراسية." : "Please select a subject.");
      return;
    }

    const startMins = parseTimeToMinutes(startTime);
    const endMins = parseTimeToMinutes(endTime);

    if (endMins <= startMins) {
      setError(
        locale === "ar"
          ? "وقت الانتهاء لازم يكون بعد وقت البدء."
          : "End time must be strictly after start time."
      );
      return;
    }

    const durationMins = endMins - startMins;
    if (durationMins < 15) {
      setError(
        locale === "ar"
          ? "مدة الحصة لازم تكون 15 دقيقة على الأقل."
          : "Session duration must be at least 15 minutes."
      );
      return;
    }
    if (durationMins > 720) {
      setError(
        locale === "ar"
          ? "مدة الحصة لا يمكن تتجاوز 12 ساعة."
          : "Session duration cannot exceed 12 hours."
      );
      return;
    }

    if (location.trim().length > 100) {
      setError(
        locale === "ar"
          ? "المكان لا يمكن يتجاوز 100 حرف."
          : "Location cannot exceed 100 characters."
      );
      return;
    }

    setSaving(true);
    try {
      await onSave({
        subject_id: subjectId,
        day_of_week: dayOfWeek,
        start_time: normalizeTimeString(startTime),
        end_time: normalizeTimeString(endTime),
        location: location.trim() || null,
        session_type: sessionType,
      });
      onClose();
    } catch (err: any) {
      setError(
        err?.message ||
          (locale === "ar" ? "حصل خطأ أثناء حفظ الحصة في الجدول." : "Failed to save schedule session.")
      );
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-fade-in">
      <div
        className="bg-surface-container w-full max-w-md rounded-2xl border border-border-subtle p-5 shadow-2xl space-y-4"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between pb-3 border-b border-border-subtle/50">
          <h2 className="text-base font-bold text-on-surface">
            {initialData
              ? locale === "ar"
                ? "تعديل موعد الحصة / المحاضرة"
                : "Edit Class Session"
              : locale === "ar"
              ? "إضافة حصة دراسية للجدول"
              : "Add Class Session"}
          </h2>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4 font-mono text-xs">
          {/* Subject Picker */}
          <div>
            <label className="block text-xs font-medium text-text-muted mb-1.5">
              {locale === "ar" ? "المادة الدراسية" : "Subject"}
            </label>
            <select
              value={subjectId}
              onChange={(e) => setSubjectId(e.target.value)}
              className="w-full px-3 py-2 bg-surface-container-high rounded-xl border border-border-subtle text-xs text-on-surface focus:outline-none focus:border-amber-400"
            >
              {activeSubjects.map((sub) => (
                <option key={sub.id} value={sub.id}>
                  {sub.name}
                </option>
              ))}
            </select>
          </div>

          {/* Day of Week */}
          <div>
            <label className="block text-xs font-medium text-text-muted mb-1.5">
              {locale === "ar" ? "يوم الأسبوع" : "Day of Week"}
            </label>
            <select
              value={dayOfWeek}
              onChange={(e) => setDayOfWeek(parseInt(e.target.value, 10))}
              className="w-full px-3 py-2 bg-surface-container-high rounded-xl border border-border-subtle text-xs text-on-surface focus:outline-none focus:border-amber-400"
            >
              {daysList.map((d) => (
                <option key={d.value} value={d.value}>
                  {d.label}
                </option>
              ))}
            </select>
          </div>

          {/* Time pickers */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-text-muted mb-1.5">
                {locale === "ar" ? "وقت البدء" : "Start Time"}
              </label>
              <input
                type="time"
                value={startTime}
                onChange={(e) => setStartTime(e.target.value)}
                className="w-full px-3 py-2 bg-surface-container-high rounded-xl border border-border-subtle text-xs text-on-surface focus:outline-none focus:border-amber-400 font-mono"
                required
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-text-muted mb-1.5">
                {locale === "ar" ? "وقت الانتهاء" : "End Time"}
              </label>
              <input
                type="time"
                value={endTime}
                onChange={(e) => setEndTime(e.target.value)}
                className="w-full px-3 py-2 bg-surface-container-high rounded-xl border border-border-subtle text-xs text-on-surface focus:outline-none focus:border-amber-400 font-mono"
                required
              />
            </div>
          </div>

          {/* Advisory Collision Warning */}
          {advisoryConflict && (
            <div className="p-2.5 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-300 text-xs flex items-start gap-2">
              <span className="text-base leading-none">⚠️</span>
              <div>
                <span className="font-semibold">
                  {locale === "ar" ? "تنبيه تعارض مواعيد:" : "Advisory Overlap:"}
                </span>{" "}
                {locale === "ar" ? (
                  <>
                    في تعارض مع <span className="font-medium text-amber-200">{advisoryConflict.subjectName}</span> (
                    {formatTimeRange12h(advisoryConflict.start, advisoryConflict.end, { locale })}). تقدر تكمل الحفظ لو ده مقصود.
                  </>
                ) : (
                  <>
                    Overlaps with{" "}
                    <span className="font-medium text-amber-200">{advisoryConflict.subjectName}</span> (
                    {formatTimeRange12h(advisoryConflict.start, advisoryConflict.end, { locale })}). You can still save if intentional.
                  </>
                )}
              </div>
            </div>
          )}

          {/* Session Type Pills */}
          <div>
            <label className="block text-xs font-medium text-text-muted mb-1.5">
              {locale === "ar" ? "نوع الحصة" : "Session Type"}
            </label>
            <div className="grid grid-cols-4 gap-2">
              {SESSION_TYPES.map(({ type, labelEn, labelAr, tokenClass }) => {
                const isSelected = sessionType === type;
                return (
                  <button
                    key={type}
                    type="button"
                    onClick={() => setSessionType(type)}
                    className={`py-2 px-1 text-center rounded-xl text-xs font-semibold border transition-all cursor-pointer ${
                      isSelected
                        ? `${tokenClass} ring-2 ring-amber-400/40 shadow-sm font-bold`
                        : "bg-surface-container-high/60 border-border-subtle text-text-muted hover:text-on-surface"
                    }`}
                  >
                    {locale === "ar" ? labelAr : labelEn}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Location with dir="auto" */}
          <div>
            <label className="block text-xs font-medium text-text-muted mb-1.5">
              {locale === "ar" ? "المكان / القاعة أو المدرج" : "Location / Room"}{" "}
              <span className="text-[11px] text-text-muted">
                {locale === "ar" ? "(يدعم العربية)" : "(Supports Arabic)"}
              </span>
            </label>
            <input
              type="text"
              dir="auto"
              maxLength={100}
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              placeholder={locale === "ar" ? "مثلاً: مدرج 302، مبنى هندسة" : "e.g. Hall 302, مبنى الهندسة"}
              className="w-full px-3 py-2 bg-surface-container-high rounded-xl border border-border-subtle text-xs text-on-surface focus:outline-none focus:border-amber-400 text-start"
            />
          </div>

          {error && <p className="text-xs text-status-negative">{error}</p>}

          <div className="flex items-center justify-end gap-2 pt-2 border-t border-border-subtle/40">
            <button
              type="button"
              onClick={onClose}
              disabled={saving}
              className="px-4 py-2 rounded-xl text-xs font-medium text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors cursor-pointer"
            >
              {locale === "ar" ? "إلغاء" : "Cancel"}
            </button>
            <button
              type="submit"
              disabled={saving}
              className="px-5 py-2 rounded-xl text-xs font-semibold bg-amber-500 hover:bg-amber-400 text-on-primary transition-colors disabled:opacity-50 cursor-pointer"
            >
              {saving
                ? locale === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : initialData
                ? locale === "ar"
                  ? "حفظ التعديلات"
                  : "Save Changes"
                : locale === "ar"
                ? "إضافة إلى الجدول"
                : "Add to Timetable"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import {
  SubjectItem,
  GradeItem,
  DeadlineItem,
  calculateSubjectGradeAverage,
  calculateTargetNeeded,
  calculateQuizVsExamAverage,
  calculateGradePercentage,
  classifyDeadline,
} from "@/lib/school";
import { GradeTrendChart } from "./GradeTrendChart";
import {
  X,
  Plus,
  Edit2,
  Trash2,
  Archive,
  RotateCcw,
  Clock,
  Award,
  CalendarClock,
  Sparkles,
  AlertTriangle,
  Play,
  CheckCircle2,
} from "lucide-react";
import { useI18n } from "@/lib/i18n/I18nContext";

interface SubjectDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  subject: SubjectItem;
  grades: GradeItem[];
  deadlines: DeadlineItem[];
  onOpenAddGrade: (subjectId: string) => void;
  onOpenEditGrade: (grade: GradeItem) => void;
  onDeleteGrade: (gradeId: string) => void;
  onOpenEditSubject: (subject: SubjectItem) => void;
  onArchiveSubject: (subjectId: string, archive: boolean) => Promise<void>;
  onDeleteSubject: (subjectId: string, hasGrades: boolean) => Promise<void>;
  onOpenStudySession: (subject: SubjectItem) => void;
  onToggleDeadlineComplete: (deadlineId: string, completed: boolean) => Promise<void>;
}

export function SubjectDetailModal({
  isOpen,
  onClose,
  subject,
  grades,
  deadlines,
  onOpenAddGrade,
  onOpenEditGrade,
  onDeleteGrade,
  onOpenEditSubject,
  onArchiveSubject,
  onDeleteSubject,
  onOpenStudySession,
  onToggleDeadlineComplete,
}: SubjectDetailModalProps) {
  const { locale } = useI18n();
  const [deleteSafeguardModal, setDeleteSafeguardModal] = useState(false);
  const [confirmingArchive, setConfirmingArchive] = useState(false);

  if (!isOpen) return null;

  const subjectGrades = grades
    .filter((g) => g.subject_id === subject.id && !g.deleted_at)
    .sort(
      (a, b) =>
        new Date(b.entry_date).getTime() - new Date(a.entry_date).getTime()
    );

  const subjectDeadlines = deadlines
    .filter((d) => d.subject_id === subject.id && !d.deleted_at)
    .sort(
      (a, b) =>
        new Date(a.due_date).getTime() - new Date(b.due_date).getTime()
    );

  const averageStats = calculateSubjectGradeAverage(subjectGrades);
  const targetStats = calculateTargetNeeded(
    subjectGrades,
    subject.target_grade
  );
  const quizVsExamStats = calculateQuizVsExamAverage(subjectGrades);

  async function handleDeleteClick() {
    if (subjectGrades.length > 0) {
      // Trigger safeguard modal prompting to archive instead
      setDeleteSafeguardModal(true);
    } else {
      await onDeleteSubject(subject.id, false);
      onClose();
    }
  }

  async function handleConfirmSafeguardArchive() {
    await onDeleteSubject(subject.id, true);
    setDeleteSafeguardModal(false);
    onClose();
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-bg-darkest/80 backdrop-blur-md">
      <div
        className="w-full max-w-2xl bg-surface-container border border-border-subtle rounded-2xl shadow-2xl max-h-[92vh] flex flex-col overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header Banner */}
        <div className="p-4 sm:p-5 border-b border-border-subtle flex items-start justify-between gap-3 bg-surface-container-high/40">
          <div className="flex items-center gap-3 min-w-0">
            <span
              className="w-4 h-4 rounded-full shrink-0 shadow-md"
              style={{ backgroundColor: subject.color || "#F59E0B" }}
            />
            <div className="min-w-0">
              <div className="flex items-center gap-2">
                <h2 dir="auto" className="text-lg font-bold font-mono text-on-surface truncate">
                  {subject.name}
                </h2>
                {subject.code && (
                  <span className="text-xs font-mono px-2 py-0.5 rounded bg-surface-container border border-border-subtle text-text-muted">
                    {subject.code}
                  </span>
                )}
                {subject.archived && (
                  <span className="text-[10px] font-mono px-2 py-0.5 rounded bg-surface-container-highest text-text-muted">
                    {locale === "ar" ? "مؤرشفة" : "Archived"}
                  </span>
                )}
              </div>
              <p className="text-xs text-on-surface-variant font-mono mt-0.5">
                {locale === "ar"
                  ? `${subjectGrades.length} تقييم مسجل`
                  : `${subjectGrades.length} ${
                      subjectGrades.length === 1 ? "grade recorded" : "grades recorded"
                    }`}
                {subject.target_grade !== null &&
                  subject.target_grade !== undefined && (
                    <span className="text-emerald-400 ml-2">
                      • {locale === "ar" ? "المستهدف:" : "Target:"} {subject.target_grade}%
                    </span>
                  )}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-1.5 shrink-0">
            {/* Study with Focus Timer Button */}
            <button
              onClick={() => onOpenStudySession(subject)}
              title={locale === "ar" ? "بدء جلسة مذاكرة (مؤقت التركيز)" : "Start Study Session (Focus Timer)"}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-300 text-xs font-mono font-medium hover:bg-amber-500/20 transition-all cursor-pointer"
            >
              <Play className="w-3.5 h-3.5 fill-amber-300" />
              <span className="hidden sm:inline">{locale === "ar" ? "مذاكرة" : "Study"}</span>
            </button>

            <button
              onClick={() => onOpenEditSubject(subject)}
              title={locale === "ar" ? "تعديل المادة" : "Edit Subject"}
              className="p-1.5 rounded-lg text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
            >
              <Edit2 className="w-4 h-4" />
            </button>
            <button
              onClick={onClose}
              className="p-1.5 rounded-lg text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Scrollable Content Body */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-5">
          {/* Top Performance Stats Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {/* Main Subject Average Card */}
            <div className="p-4 rounded-xl bg-surface-container-high/60 border border-border-subtle space-y-1.5">
              <span className="text-[11px] font-mono text-on-surface-variant block uppercase tracking-wider">
                {locale === "ar" ? "المعدل التراكمي للمادة" : averageStats.label}
              </span>
              <div className="flex items-baseline gap-2">
                <span className="text-2xl font-bold font-mono text-on-surface">
                  {averageStats.averagePct !== null
                    ? `${averageStats.averagePct}%`
                    : "—"}
                </span>
                {averageStats.isWeighted && (
                  <span className="text-[11px] font-mono text-amber-400">
                    {locale === "ar" ? "موزون بالأوزان" : "Weighted"}
                  </span>
                )}
              </div>
              <p className="text-[11px] text-text-muted">
                {averageStats.hasGrades
                  ? locale === "ar"
                    ? `محسوب عبر ${averageStats.totalGrades} تقييم مسجل`
                    : `Computed across ${averageStats.totalGrades} assessments`
                  : locale === "ar"
                  ? "لا توجد تقييمات مسجلة بعد"
                  : "No evaluations logged yet"}
              </p>
            </div>

            {/* Target Projection Card */}
            <div className="p-4 rounded-xl bg-surface-container-high/60 border border-border-subtle space-y-1.5">
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-mono text-on-surface-variant uppercase tracking-wider">
                  {locale === "ar" ? "توقعات تحقيق الهدف" : "Target Projection"}
                </span>
                {subject.target_grade && (
                  <span className="text-[11px] font-mono text-emerald-400">
                    {locale === "ar" ? "المستهدف:" : "Goal:"} {subject.target_grade}%
                  </span>
                )}
              </div>
              <div className="text-sm font-mono text-on-surface font-semibold pt-0.5">
                {targetStats.message}
              </div>
              <p className="text-[11px] text-text-muted">
                {targetStats.available
                  ? locale === "ar"
                    ? `الوزن النسبي المتبقي من أعمال السنة: ${targetStats.remainingWeightPct}%`
                    : `Remaining coursework weight: ${targetStats.remainingWeightPct}%`
                  : locale === "ar"
                  ? "حدد النسبة المستهدفة وأوزان التقييمات للتفعيل"
                  : "Set a target grade and course weights to activate"}
              </p>
            </div>
          </div>

          {/* Comparative Quiz vs Big Exam Breakdown (ONLY with >= 2 of each) */}
          {quizVsExamStats.hasSufficientData && (
            <div className="p-4 rounded-xl bg-surface-container-high/40 border border-border-subtle space-y-2.5">
              <div className="flex items-center justify-between text-xs font-mono">
                <span className="text-on-surface font-semibold">
                  {locale === "ar"
                    ? "مقارنة الأداء (الكويزات ضد الامتحانات الرئيسية)"
                    : "Assessment Split (Quiz vs Big Exam)"}
                </span>
                <span className="text-text-muted text-[10px]">
                  {locale === "ar" ? "يتطلب تقييمين على الأقل من كل نوع" : "Requires ≥ 2 of each"}
                </span>
              </div>
              <div className="grid grid-cols-2 gap-3 pt-1">
                <div className="p-3 rounded-lg bg-surface-container border border-border-subtle">
                  <div className="flex items-center gap-1.5 text-xs font-mono text-amber-400">
                    <span className="w-2.5 h-2.5 rounded-full bg-amber-400" />
                    <span>
                      {locale === "ar"
                        ? `كويزات (${quizVsExamStats.quizCount})`
                        : `Quizzes (${quizVsExamStats.quizCount})`}
                    </span>
                  </div>
                  <div className="text-lg font-bold font-mono text-on-surface mt-1">
                    {quizVsExamStats.quizAveragePct}%
                  </div>
                </div>
                <div className="p-3 rounded-lg bg-surface-container border border-border-subtle">
                  <div className="flex items-center gap-1.5 text-xs font-mono text-indigo-400">
                    <span className="w-2.5 h-2.5 rotate-45 bg-indigo-400" />
                    <span>
                      {locale === "ar"
                        ? `امتحانات رئيسية (${quizVsExamStats.bigExamCount})`
                        : `Big Exams (${quizVsExamStats.bigExamCount})`}
                    </span>
                  </div>
                  <div className="text-lg font-bold font-mono text-on-surface mt-1">
                    {quizVsExamStats.bigExamAveragePct}%
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Visual Trend Chart */}
          <div className="space-y-2">
            <h3 className="text-xs font-mono uppercase tracking-wider text-on-surface-variant">
              {locale === "ar" ? "التطور الزمني للدرجات" : "Chronological Trend"}
            </h3>
            <GradeTrendChart
              grades={subjectGrades}
              targetGrade={subject.target_grade}
              subjectColor={subject.color}
            />
          </div>

          {/* Upcoming Subject Deadlines Section */}
          <div className="space-y-2.5">
            <div className="flex items-center justify-between text-xs font-mono">
              <span className="text-on-surface-variant uppercase tracking-wider">
                {locale === "ar" ? "المواعيد والمهام القادمة للمادة" : "Upcoming Subject Deadlines"}
              </span>
              <span className="text-text-muted text-[10px]">
                {subjectDeadlines.filter((d) => !d.completed).length}{" "}
                {locale === "ar" ? "متبقي" : "Pending"}
              </span>
            </div>

            {subjectDeadlines.length === 0 ? (
              <div className="p-3.5 rounded-xl bg-surface-container/40 border border-border-subtle text-center text-xs font-mono text-text-muted">
                {locale === "ar"
                  ? "لا توجد مواعيد تسليم مسجلة لهذه المادة"
                  : "No deadlines registered for this subject"}
              </div>
            ) : (
              <div className="space-y-2">
                {subjectDeadlines.slice(0, 4).map((dl) => {
                  const classification = classifyDeadline(dl.due_date);
                  return (
                    <div
                      key={dl.id}
                      className="p-3 rounded-xl bg-surface-container-high/40 border border-border-subtle flex items-center justify-between gap-3 text-xs font-mono"
                    >
                      <div className="flex items-center gap-2.5 min-w-0">
                        <button
                          onClick={() =>
                            onToggleDeadlineComplete(dl.id, !dl.completed)
                          }
                          className="text-text-muted hover:text-amber-400 transition-colors"
                        >
                          <CheckCircle2
                            className={`w-4 h-4 ${
                              dl.completed
                                ? "text-emerald-400 fill-emerald-400/20"
                                : "text-text-muted"
                            }`}
                          />
                        </button>
                        <span
                          className={`truncate ${
                            dl.completed
                              ? "line-through text-text-muted"
                              : "text-on-surface font-medium"
                          }`}
                        >
                          {dl.title}
                        </span>
                        <span className="text-[10px] px-1.5 py-0.5 rounded bg-surface-container border border-border-subtle text-text-muted capitalize">
                          {dl.type}
                        </span>
                      </div>
                      <span
                        className={`text-[10px] px-2 py-0.5 rounded border shrink-0 ${classification.badgeClass}`}
                      >
                        {classification.label}
                      </span>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Assessment History with Edit and Soft-Delete Undo */}
          <div className="space-y-3">
            <div className="flex items-center justify-between text-xs font-mono">
              <span className="text-on-surface-variant uppercase tracking-wider">
                {locale === "ar" ? "سجل التقييمات والدرجات" : "Assessment History"}
              </span>
              <button
                onClick={() => onOpenAddGrade(subject.id)}
                className="flex items-center gap-1.5 px-3 py-1 rounded-lg bg-amber-500/10 text-amber-300 border border-amber-500/20 text-xs font-mono hover:bg-amber-500/20 transition-all cursor-pointer"
              >
                <Plus className="w-3.5 h-3.5" />
                <span>{locale === "ar" ? "إضافة درجة" : "Add Grade"}</span>
              </button>
            </div>

            {subjectGrades.length === 0 ? (
              <div className="p-6 rounded-xl bg-surface-container/40 border border-border-subtle text-center space-y-2">
                <Award className="w-8 h-8 text-amber-400/40 mx-auto" />
                <p className="text-xs font-mono text-on-surface-variant">
                  {locale === "ar"
                    ? `لا توجد تقييمات مسجلة لمادة ${subject.name}`
                    : `No assessments logged for ${subject.name}`}
                </p>
                <button
                  onClick={() => onOpenAddGrade(subject.id)}
                  className="inline-flex items-center gap-1.5 text-xs font-mono text-amber-400 hover:underline pt-1"
                >
                  <Plus className="w-3.5 h-3.5" />
                  <span>
                    {locale === "ar"
                      ? "سجل أول كويز أو امتحان رئيسي"
                      : "Record your first quiz or big exam"}
                  </span>
                </button>
              </div>
            ) : (
              <div className="space-y-2">
                {subjectGrades.map((g) => {
                  const pct = calculateGradePercentage(
                    g.mark_achieved,
                    g.mark_total
                  );
                  const isQuiz = g.type === "quiz";

                  return (
                    <div
                      key={g.id}
                      className="p-3.5 rounded-xl bg-surface-container-high/40 border border-border-subtle hover:border-border-medium transition-all flex items-center justify-between gap-3"
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        {isQuiz ? (
                          <span
                            className="w-3 h-3 rounded-full bg-amber-400 shrink-0"
                            title={locale === "ar" ? "كويز" : "Quiz"}
                          />
                        ) : (
                          <span
                            className="w-3 h-3 rotate-45 bg-indigo-400 shrink-0"
                            title={locale === "ar" ? "امتحان رئيسي" : "Big Exam"}
                          />
                        )}
                        <div className="min-w-0">
                          <div className="flex items-center gap-2">
                            <h4 className="text-xs font-semibold text-on-surface truncate">
                              {g.title}
                            </h4>
                            <span
                              className={`text-[9px] font-mono px-1.5 py-0.2 rounded uppercase ${
                                isQuiz
                                  ? "bg-amber-400/10 text-amber-300"
                                  : "bg-indigo-400/10 text-indigo-300"
                              }`}
                            >
                              {isQuiz
                                ? locale === "ar"
                                  ? "كويز"
                                  : "Quiz"
                                : locale === "ar"
                                ? "امتحان رئيسي"
                                : "Big Exam"}
                            </span>
                          </div>
                          <div className="flex items-center gap-2 text-[11px] font-mono text-text-muted mt-0.5">
                            <span>{g.entry_date}</span>
                            {g.weight_pct !== null &&
                              g.weight_pct !== undefined && (
                                <span>
                                  • {locale === "ar" ? "الوزن:" : "Weight:"} {g.weight_pct}%
                                </span>
                              )}
                            {g.note && (
                              <span className="truncate max-w-[150px] italic">
                                • &ldquo;{g.note}&rdquo;
                              </span>
                            )}
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center gap-3 shrink-0">
                        <div className="text-end">
                          <div className="text-sm font-bold font-mono text-on-surface">
                            {pct}%
                          </div>
                          <div className="text-[10px] font-mono text-text-muted">
                            {g.mark_achieved} / {g.mark_total}
                          </div>
                        </div>
                        <div className="flex items-center gap-1 border-l border-border-subtle pl-2 rtl:border-l-0 rtl:border-r rtl:pl-0 rtl:pr-2">
                          <button
                            onClick={() => onOpenEditGrade(g)}
                            className="p-1 rounded text-text-muted hover:text-on-surface hover:bg-surface-container transition-colors"
                          >
