"use client";

import React, { useState, useEffect } from "react";
import {
  SubjectItem,
  SUBJECT_PALETTE,
  PROHIBITED_COLOR,
  validateSubjectInput,
} from "@/lib/school";
import { useI18n } from "@/lib/i18n/I18nContext";
import { X, Loader2, AlertCircle, Bookmark } from "lucide-react";

interface SubjectModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (subject: {
    name: string;
    code: string | null;
    color: string;
    target_grade: number | null;
  }) => Promise<void>;
  initialSubject?: SubjectItem | null;
  existingNames?: string[];
  isBlocked?: boolean;
}

export function SubjectModal({
  isOpen,
  onClose,
  onSave,
  initialSubject,
  existingNames = [],
  isBlocked = false,
}: SubjectModalProps) {
  const { locale } = useI18n();
  const [name, setName] = useState("");
  const [code, setCode] = useState("");
  const [color, setColor] = useState(SUBJECT_PALETTE[0].value);
  const [targetGrade, setTargetGrade] = useState<string>("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (initialSubject) {
      setName(initialSubject.name || "");
      setCode(initialSubject.code || "");
      setColor(
        initialSubject.color?.toLowerCase() === PROHIBITED_COLOR
          ? SUBJECT_PALETTE[0].value
          : initialSubject.color || SUBJECT_PALETTE[0].value
      );
      setTargetGrade(
        initialSubject.target_grade !== null &&
          initialSubject.target_grade !== undefined
          ? String(initialSubject.target_grade)
          : ""
      );
    } else {
      setName("");
      setCode("");
      setColor(SUBJECT_PALETTE[0].value);
      setTargetGrade("");
    }
    setError(null);
  }, [initialSubject, isOpen]);

  if (!isOpen) return null;

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);

    if (isBlocked) {
      setError("Offline: saving disabled to protect sync integrity.");
      return;
    }

    const trimmedName = name.trim();
    if (!trimmedName) {
      setError("Subject name is required.");
      return;
    }

    // Check case-insensitive uniqueness among other subjects
    const lowerName = trimmedName.toLowerCase();
    const isDuplicate = existingNames.some(
      (n) =>
        n.toLowerCase() === lowerName &&
        (!initialSubject || initialSubject.name.toLowerCase() !== lowerName)
    );

    if (isDuplicate) {
      setError(`A subject named "${trimmedName}" already exists.`);
      return;
    }

    const parsedTarget =
      targetGrade.trim() !== "" ? parseFloat(targetGrade) : null;

    const validation = validateSubjectInput({
      name: trimmedName,
      color,
      target_grade: parsedTarget,
    });

    if (!validation.valid) {
      setError(validation.error || "Invalid subject input.");
      return;
    }

    try {
      setSaving(true);
      await onSave({
        name: trimmedName,
        code: code.trim() || null,
        color,
        target_grade: parsedTarget,
      });
      onClose();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to save subject";
      setError(msg);
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-bg-darkest/80 backdrop-blur-md">
      <div
        className="w-full max-w-md bg-surface-container border border-border-subtle rounded-2xl p-6 shadow-2xl space-y-4"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between pb-3 border-b border-border-subtle">
          <div className="flex items-center gap-2">
            <Bookmark className="w-5 h-5 text-amber-400" />
            <h3 className="text-base font-bold font-mono text-on-surface">
              {locale === "ar"
                ? initialSubject ? "تعديل بيانات المادة" : "إضافة مادة جديدة"
                : initialSubject ? "Edit Subject" : "New Subject"}
            </h3>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-lg text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {error && (
          <div className="p-3 bg-crimson-alert/10 border border-crimson-alert/30 rounded-xl flex items-center gap-2 text-crimson-alert text-xs font-mono">
            <AlertCircle className="w-4 h-4 shrink-0" />
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Name Input with dir="auto" for Arabic support */}
          <div className="space-y-1.5">
            <label className="text-xs font-mono text-on-surface-variant flex items-center justify-between">
              <span>{locale === "ar" ? "اسم المادة *" : "Subject Name *"}</span>
              <span className="text-[10px] text-text-muted">
                {locale === "ar" ? "فريد" : "Unique"}
              </span>
            </label>
            <input
              type="text"
              dir="auto"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder={locale === "ar" ? "مثال: فيزياء، تفاضل وتكامل، تاريخ" : "e.g. Physics, Advanced Math, تاريخ"}
              required
              className="w-full px-3.5 py-2.5 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface focus:outline-none focus:border-amber-400 placeholder:text-text-muted transition-colors font-sans"
            />
          </div>

          {/* Code Input (Optional) */}
          <div className="space-y-1.5">
            <label className="text-xs font-mono text-on-surface-variant">
              {locale === "ar" ? "كود المادة (اختياري)" : "Course Code (Optional)"}
            </label>
            <input
              type="text"
              value={code}
              onChange={(e) => setCode(e.target.value.toUpperCase())}
              placeholder="e.g. PHYS-101, MATH-202"
              className="w-full px-3.5 py-2.5 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface font-mono uppercase focus:outline-none focus:border-amber-400 placeholder:text-text-muted transition-colors"
            />
          </div>

          {/* Target Grade (%) */}
          <div className="space-y-1.5">
            <label className="text-xs font-mono text-on-surface-variant flex items-center justify-between">
              <span>{locale === "ar" ? "النسبة المستهدفة % (اختياري)" : "Target Grade % (Optional)"}</span>
              <span className="text-[10px] text-text-muted">0 – 100%</span>
            </label>
            <input
              type="number"
              min="0"
              max="100"
              step="any"
              value={targetGrade}
              onChange={(e) => setTargetGrade(e.target.value)}
              placeholder="e.g. 90"
              className="w-full px-3.5 py-2.5 rounded-xl bg-surface-container-high border border-border-medium text-sm text-on-surface font-mono focus:outline-none focus:border-amber-400 placeholder:text-text-muted transition-colors"
            />
          </div>

          {/* Color Palette Picker (Never Lime #C6FF3D) */}
          <div className="space-y-2">
            <label className="text-xs font-mono text-on-surface-variant">
              {locale === "ar" ? "لون المادة المميز" : "Subject Color Palette"}
            </label>
            <div className="grid grid-cols-4 gap-2.5">
              {SUBJECT_PALETTE.map((opt) => (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => setColor(opt.value)}
                  className={`flex items-center gap-2 p-2 rounded-xl border text-xs font-mono transition-all ${
                    color === opt.value
                      ? "border-amber-400 bg-surface-container-high shadow-md"
                      : "border-border-subtle bg-surface-container-low hover:border-border-medium"
                  }`}
                >
                  <span
                    className="w-3.5 h-3.5 rounded-full shrink-0 shadow-sm"
                    style={{ backgroundColor: opt.value }}
                  />
                  <span className="truncate text-[11px] text-on-surface">
                    {opt.label.split(" ")[0]}
                  </span>
                </button>
              ))}
            </div>
          </div>

          {/* Modal Actions */}
          <div className="flex items-center justify-end gap-3 pt-3 border-t border-border-subtle">
            <button
              type="button"
              onClick={onClose}
              disabled={saving}
              className="px-4 py-2 rounded-xl text-xs font-mono text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
            >
              {locale === "ar" ? "إلغاء" : "Cancel"}
            </button>
            <button
              type="submit"
              disabled={saving || isBlocked}
              className="flex items-center gap-2 px-5 py-2 rounded-xl bg-amber-500 text-on-primary text-xs font-mono font-semibold uppercase tracking-wider hover:bg-amber-400 disabled:opacity-50 shadow-[0_0_16px_rgba(245,158,11,0.25)] transition-all cursor-pointer"
            >
              {saving ? (
                <>
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  <span>{locale === "ar" ? "جاري الحفظ..." : "Saving..."}</span>
                </>
              ) : (
                <span>
                  {locale === "ar"
                    ? initialSubject ? "تحديث المادة" : "إنشاء المادة"
                    : initialSubject ? "Update Subject" : "Create Subject"}
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useMemo } from "react";
import {
  ScheduleItem,
  SubjectItem,
  getNextClassToday,
  normalizeTimeString,
} from "@/lib/school";
import { formatTimeRange12h } from "@/lib/time";
import { SessionModal } from "./SessionModal";
import { useI18n } from "@/lib/i18n/I18nContext";

interface TimetableGridProps {
  schedule: ScheduleItem[];
  subjects: SubjectItem[];
  onAddSession: (session: any) => Promise<void>;
  onEditSession: (id: string, session: any) => Promise<void>;
  onDeleteSession: (id: string) => void;
  userTimeZone?: string;
}

const DAYS_EN = [
  { value: 0, label: "Sunday", short: "Sun" },
  { value: 1, label: "Monday", short: "Mon" },
  { value: 2, label: "Tuesday", short: "Tue" },
  { value: 3, label: "Wednesday", short: "Wed" },
  { value: 4, label: "Thursday", short: "Thu" },
  { value: 5, label: "Friday", short: "Fri" },
  { value: 6, label: "Saturday", short: "Sat" },
];

const DAYS_AR = [
  { value: 0, label: "الأحد", short: "أحد" },
  { value: 1, label: "الإثنين", short: "إثنين" },
  { value: 2, label: "الثلاثاء", short: "ثلاثاء" },
  { value: 3, label: "الأربعاء", short: "أربعاء" },
  { value: 4, label: "الخميس", short: "خميس" },
  { value: 5, label: "الجمعة", short: "جمعة" },
  { value: 6, label: "السبت", short: "سبت" },
];

const SESSION_TYPE_LABELS: Record<string, { en: string; ar: string }> = {
  lecture: { en: "Lecture", ar: "محاضرة" },
  lab: { en: "Lab", ar: "معمل" },
  section: { en: "Section", ar: "سكشن" },
  seminar: { en: "Seminar", ar: "سيمنار" },
};

export function TimetableGrid({
  schedule,
  subjects,
  onAddSession,
  onEditSession,
  onDeleteSession,
  userTimeZone = "Africa/Cairo",
}: TimetableGridProps) {
  const { locale } = useI18n();
  const [selectedDay, setSelectedDay] = useState<number>(() => new Date().getDay());
  const [modalOpen, setModalOpen] = useState(false);
  const [editingSession, setEditingSession] = useState<ScheduleItem | null>(null);

  const daysList = locale === "ar" ? DAYS_AR : DAYS_EN;
  const currentDayObj = daysList.find((d) => d.value === selectedDay) || daysList[0];

  const activeSubjectsMap = useMemo(
    () => new Map(subjects.filter((s) => !s.deleted_at).map((s) => [s.id, s])),
    [subjects]
  );

  const activeSchedule = useMemo(
    () =>
      schedule.filter((item) => {
        if (item.deleted_at) return false;
        const sub = activeSubjectsMap.get(item.subject_id);
        return sub && !sub.archived;
      }),
    [schedule, activeSubjectsMap]
  );

  const nextClassInfo = useMemo(
    () => getNextClassToday(schedule, subjects, new Date(), userTimeZone),
    [schedule, subjects, userTimeZone]
  );

  const daySessions = useMemo(() => {
    return activeSchedule
      .filter((item) => item.day_of_week === selectedDay)
      .sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [activeSchedule, selectedDay]);

  const handleOpenAdd = (day: number) => {
    setSelectedDay(day);
    setEditingSession(null);
    setModalOpen(true);
  };

  const handleOpenEdit = (session: ScheduleItem) => {
    setEditingSession(session);
    setModalOpen(true);
  };

  const handleSaveModal = async (payload: any) => {
    if (editingSession) {
      await onEditSession(editingSession.id, payload);
    } else {
      await onAddSession(payload);
    }
  };

  return (
    <div className="space-y-4">
      {/* Next Class Today Banner */}
      {nextClassInfo && (
        <div className="p-4 rounded-2xl bg-surface-container border border-border-subtle flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-amber-500/15 border border-amber-500/30 flex items-center justify-center text-amber-300 font-bold text-sm">
              ⏳
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span className="text-xs font-semibold text-amber-400 uppercase tracking-wider">
                  {locale === "ar" ? "المحاضرة / الحصة القادمة النهاردة" : "Next Class Today"}
                </span>
                <span className="text-[11px] text-text-muted">
                  {locale === "ar"
                    ? `خلال ${Math.floor(nextClassInfo.startsInMinutes / 60)}س و${nextClassInfo.startsInMinutes % 60}د`
                    : `in ${Math.floor(nextClassInfo.startsInMinutes / 60)}h ${nextClassInfo.startsInMinutes % 60}m`}
                </span>
              </div>
              <h4 className="text-sm font-bold text-on-surface">
                {nextClassInfo.subject.name}
              </h4>
              <p className="text-xs text-text-muted">
                {formatTimeRange12h(nextClassInfo.nextClass.start_time, nextClassInfo.nextClass.end_time, { locale })}
                {nextClassInfo.nextClass.location && (
                  <span dir="auto" className="ml-1.5 text-on-surface-variant font-medium">
                    • {nextClassInfo.nextClass.location}
                  </span>
                )}
              </p>
            </div>
          </div>
          <span className={`text-[11px] font-semibold px-2.5 py-1 rounded-lg border session-${nextClassInfo.nextClass.session_type}`}>
            {SESSION_TYPE_LABELS[nextClassInfo.nextClass.session_type]?.[locale] || nextClassInfo.nextClass.session_type}
          </span>
        </div>
      )}

      {/* Header controls & Add Button */}
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-base font-bold text-on-surface">
          {locale === "ar" ? "الجدول الدراسي الأسبوعي" : "Weekly Timetable"}
        </h3>
        <button
          onClick={() => handleOpenAdd(selectedDay)}
          className="px-3 py-1.5 rounded-xl bg-amber-500 hover:bg-amber-400 text-on-primary text-xs font-semibold flex items-center gap-1.5 transition-colors cursor-pointer"
        >
          <span>+</span>
          <span>{locale === "ar" ? "إضافة حصة / محاضرة" : "Add Class"}</span>
        </button>
      </div>

      {/* Mobile Day Switcher (Scrollable Pills) */}
      <div className="flex items-center gap-1.5 overflow-x-auto pb-1 scrollbar-none">
        {daysList.map((d) => {
          const isSelected = selectedDay === d.value;
          const count = activeSchedule.filter((s) => s.day_of_week === d.value).length;
          return (
            <button
              key={d.value}
              onClick={() => setSelectedDay(d.value)}
              className={`flex-1 min-w-[56px] py-2 px-1 rounded-xl text-center border transition-all cursor-pointer ${
                isSelected
                  ? "bg-amber-500/20 border-amber-500/60 text-amber-300 font-bold shadow-sm"
                  : "bg-surface-container border-border-subtle/50 text-text-muted hover:text-on-surface"
              }`}
            >
              <div className="text-[11px] font-medium leading-none">{d.short}</div>
              <div className="text-[10px] mt-1 text-text-muted">
                {count > 0 ? `${count}` : "—"}
              </div>
            </button>
          );
        })}
      </div>

      {/* Day Schedule Cards */}
      <div className="space-y-2.5">
        {daySessions.length === 0 ? (
          <div className="p-8 rounded-2xl bg-surface-container/60 border border-border-subtle text-center space-y-2">
            <p className="text-sm text-text-muted">
              {locale === "ar"
                ? `مفيش حصص أو محاضرات مجدولة يوم ${currentDayObj.label}`
                : `No classes scheduled for ${currentDayObj.label}`}
            </p>
            <button
              onClick={() => handleOpenAdd(selectedDay)}
              className="text-xs text-amber-400 hover:underline font-medium cursor-pointer"
            >
              {locale === "ar"
                ? `+ إضافة حصة ليوم ${currentDayObj.label}`
                : `+ Add a session for ${currentDayObj.label}`}
            </button>
          </div>
        ) : (
          daySessions.map((item) => {
            const sub = activeSubjectsMap.get(item.subject_id);
            return (
              <div
                key={item.id}
                className="p-3.5 rounded-2xl bg-surface-container border border-border-subtle hover:border-border-medium transition-all flex items-center justify-between gap-3 group"
              >
                <div className="flex items-start gap-3 min-w-0">
                  <div
                    className="w-2.5 self-stretch rounded-full flex-shrink-0"
                    style={{ backgroundColor: sub?.color || "#F59E0B" }}
                  />
                  <div className="min-w-0 space-y-0.5">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-mono font-bold text-on-surface" dir="auto">
                        {formatTimeRange12h(item.start_time, item.end_time, { locale })}
                      </span>
                      <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-md border session-${item.session_type}`}>
                        {SESSION_TYPE_LABELS[item.session_type]?.[locale] || item.session_type}
                      </span>
                    </div>
                    <h4 className="text-sm font-semibold text-on-surface truncate">
                      {sub?.name || (locale === "ar" ? "مادة غير معروفة" : "Unknown Subject")}
                    </h4>
                    {item.location && (
                      <p dir="auto" className="text-xs text-text-muted truncate">
                        📍 {item.location}
                      </p>
                    )}
                  </div>
                </div>

                <div className="flex items-center gap-1 opacity-90 sm:opacity-0 group-hover:opacity-100 transition-opacity">
                  <button
                    onClick={() => handleOpenEdit(item)}
                    className="p-1.5 text-text-muted hover:text-amber-300 hover:bg-surface-container-high rounded-lg transition-colors cursor-pointer"
                    title={locale === "ar" ? "تعديل الحصة" : "Edit Session"}
                  >
                    ✏️
                  </button>
                  <button
                    onClick={() => onDeleteSession(item.id)}
                    className="p-1.5 text-text-muted hover:text-status-negative hover:bg-surface-container-high rounded-lg transition-colors cursor-pointer"
                    title={locale === "ar" ? "حذف الحصة" : "Delete Session"}
                  >
                    🗑️
                  </button>
                </div>
              </div>
            );
          })
        )}
      </div>

      <SessionModal
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        onSave={handleSaveModal}
        subjects={subjects}
        existingSessions={schedule}
        initialData={editingSession}
        initialDayOfWeek={selectedDay}
      />
    </div>
  );
}

