          >
            <Plus className="w-3.5 h-3.5 stroke-[2.5]" />
            <span>{locale === "ar" ? "إضافة مفهوم" : "Add Topic"}</span>
          </button>
        </div>
      </div>

      {/* Topics List */}
      {filteredTopics.length === 0 ? (
