                  {t.notes && (
                    <p
                      dir="auto"
                      className="text-xs font-sans text-on-surface-variant line-clamp-2 leading-relaxed"
                    >
                      {t.notes}
                    </p>
                  )}
                </div>

                {/* Bottom Row: 1-5 Stars Rating + Actions */}
                <div className="pt-2 border-t border-border-subtle/50 flex items-center justify-between gap-2 font-mono text-xs">
                  <div className="flex items-center gap-1">
                    <span className="text-[10px] text-text-muted mr-1">
                      {locale === "ar" ? "مستوى الفهم:" : "Confidence:"}
                    </span>
                    {[1, 2, 3, 4, 5].map((lvl) => (
                      <button
                        key={lvl}
                        disabled={isBusy}
                        onClick={() => handleRate(t.id, lvl)}
                        className={`p-1 rounded transition-all cursor-pointer disabled:opacity-40 hover:scale-110 ${
                          lvl <= t.confidence ? "text-amber-400" : "text-text-muted/30"
                        }`}
                        title={`Rate confidence ${lvl}/5`}
                      >
                        <Star
                          className={`w-3.5 h-3.5 ${
                            lvl <= t.confidence ? "fill-amber-400" : ""
                          }`}
                        />
                      </button>
                    ))}
                  </div>

                  <div className="flex items-center gap-1.5">
                    <button
                      onClick={() => onOpenEditModal(t)}
                      className="p-1.5 rounded-lg text-text-muted hover:text-on-surface hover:bg-surface-container-high transition-colors"
                      title={locale === "ar" ? "تعديل المفهوم" : "Edit Topic"}
                    >
                      <Edit2 className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={() => onDeleteTopic(t.id)}
                      className="p-1.5 rounded-lg text-text-muted hover:text-crimson-alert hover:bg-crimson-alert/10 transition-colors"
                      title={locale === "ar" ? "حذف (تراجع 8 ث)" : "Delete (8s Undo)"}
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { calculateWeeklyStudyProgress } from "@/lib/school";
import { useI18n } from "@/lib/i18n/I18nContext";

interface WeeklyTargetCardProps {
  weeklyTargetMinutes: number | null;
  completedMinutes: number;
  onUpdateTarget: (minutes: number | null) => Promise<void>;
}

export function WeeklyTargetCard({
  weeklyTargetMinutes,
  completedMinutes,
  onUpdateTarget,
}: WeeklyTargetCardProps) {
  const { locale } = useI18n();
  const [isEditing, setIsEditing] = useState(false);
  const [targetHoursInput, setTargetHoursInput] = useState<string>(
    weeklyTargetMinutes ? (weeklyTargetMinutes / 60).toString() : ""
  );
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const progress = calculateWeeklyStudyProgress(weeklyTargetMinutes, [
    {
      id: "summary",
      actual_minutes: completedMinutes,
      status: "completed",
      started_at: new Date().toISOString(),
    },
  ]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSaving(true);
    try {
      if (!targetHoursInput.trim()) {
        await onUpdateTarget(null);
        setIsEditing(false);
        return;
      }

      const hours = parseFloat(targetHoursInput);
      if (isNaN(hours) || hours <= 0) {
        setError(
          locale === "ar"
            ? "المستهدف لازم يكون رقم موجب أكبر من الصفر."
            : "Target must be a positive number."
        );
        setSaving(false);
        return;
      }

      const minutes = Math.round(hours * 60);
      if (minutes < 30 || minutes > 10080) {
        setError(
          locale === "ar"
            ? "المستهدف لازم يكون بين نصف ساعة (30 دقيقة) و 168 ساعة."
            : "Target must be between 0.5 hours (30m) and 168 hours."
        );
        setSaving(false);
        return;
      }

      await onUpdateTarget(minutes);
      setIsEditing(false);
    } catch (err: any) {
      setError(
        err?.message ||
          (locale === "ar" ? "حصل خطأ أثناء تحديث المستهدف" : "Failed to update target")
      );
    } finally {
      setSaving(false);
    }
  };

  const handleClear = async () => {
    setSaving(true);
    try {
      await onUpdateTarget(null);
      setTargetHoursInput("");
      setIsEditing(false);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="bg-surface-container rounded-2xl p-5 border border-border-subtle shadow-sm">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-amber-500/10 border border-amber-500/20 flex items-center justify-center text-amber-400">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div>
            <h3 className="text-sm font-semibold text-on-surface">
              {locale === "ar" ? "المستهدف الأسبوعي للمذاكرة" : "Weekly Study Target"}
            </h3>
            <p className="text-xs text-text-muted">
              {locale === "ar"
                ? "إجمالي ساعات التركيز العميق لكل المواد الدراسية"
                : "Total deep work focus across all subjects"}
            </p>
          </div>
        </div>

        {!isEditing && (
          <button
            onClick={() => {
              setTargetHoursInput(weeklyTargetMinutes ? (weeklyTargetMinutes / 60).toString() : "");
              setIsEditing(true);
            }}
            className="text-xs font-medium text-amber-400 hover:text-amber-300 transition-colors px-2.5 py-1 rounded-lg hover:bg-amber-500/10 cursor-pointer"
          >
            {weeklyTargetMinutes
              ? locale === "ar"
                ? "تعديل"
                : "Edit"
              : locale === "ar"
              ? "تحديد مستهدف"
              : "Set Target"}
          </button>
        )}
      </div>

      {isEditing ? (
        <form onSubmit={handleSave} className="mt-3 pt-3 border-t border-border-subtle/40">
          <label className="block text-xs font-medium text-text-muted mb-1.5">
            {locale === "ar" ? "ساعات المذاكرة المستهدفة في الأسبوع" : "Target Study Hours per Week"}
          </label>
          <div className="flex items-center gap-2">
            <input
              type="number"
              step="0.5"
              min="0.5"
              max="168"
              value={targetHoursInput}
              onChange={(e) => setTargetHoursInput(e.target.value)}
              placeholder="e.g. 15"
              autoFocus
              className="flex-1 px-3 py-2 bg-surface-container-high rounded-xl border border-border-subtle text-sm text-on-surface focus:outline-none focus:border-amber-400 text-start"
            />
            <span className="text-xs text-text-muted">
              {locale === "ar" ? "ساعة/أسبوع" : "hrs/week"}
            </span>
          </div>

          {error && <p className="text-xs text-status-negative mt-1.5">{error}</p>}

          <div className="flex items-center justify-end gap-2 mt-3">
            {weeklyTargetMinutes && (
              <button
                type="button"
                onClick={handleClear}
                disabled={saving}
                className="text-xs text-status-negative hover:underline px-2 py-1 mr-auto rtl:mr-0 rtl:ml-auto cursor-pointer"
              >
                {locale === "ar" ? "مسح المستهدف" : "Clear Target"}
              </button>
            )}
            <button
              type="button"
              onClick={() => setIsEditing(false)}
              disabled={saving}
              className="px-3 py-1.5 rounded-lg text-xs font-medium text-text-muted hover:text-on-surface hover:bg-surface-container-high cursor-pointer"
            >
              {locale === "ar" ? "إلغاء" : "Cancel"}
            </button>
            <button
              type="submit"
              disabled={saving}
              className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-amber-500 hover:bg-amber-400 text-on-primary transition-colors disabled:opacity-50 cursor-pointer"
            >
              {saving
                ? locale === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : locale === "ar"
                ? "حفظ المستهدف"
                : "Save Target"}
            </button>
          </div>
        </form>
      ) : weeklyTargetMinutes === null ? (
        <div className="mt-2 py-3 px-3.5 bg-surface-container-low rounded-xl border border-border-subtle/50 flex items-center justify-between">
          <div className="text-xs text-text-muted">
            <span className="text-on-surface font-medium">{progress.completedHoursFormatted}</span>{" "}
            {locale === "ar" ? "تمت مذاكرتها الأسبوع ده" : "studied this week"}
          </div>
          <span className="text-xs text-text-muted italic">
            {locale === "ar" ? "لم يُحدد مستهدف" : "No target defined"}
          </span>
        </div>
      ) : (
        <div className="mt-2 space-y-2">
          <div className="flex items-baseline justify-between text-xs">
            <div>
              <span className="text-base font-bold text-on-surface">{progress.completedHoursFormatted}</span>
              <span className="text-text-muted"> / {progress.targetHoursFormatted}</span>
            </div>
            <div className="font-semibold text-amber-400">
              {progress.isCompleted
                ? locale === "ar"
                  ? "حققت الهدف بالكامل! 🎉"
                  : "Goal Reached! 🎉"
                : `${progress.progressPct}%`}
            </div>
          </div>

          <div className="w-full h-2 rounded-full bg-surface-container-high overflow-hidden">
            <div
              className={`h-full rounded-full transition-all duration-500 ${
                progress.isCompleted ? "bg-amber-400" : "bg-amber-500"
              }`}
              style={{ width: `${Math.min(100, progress.progressPct)}%` }}
            />
          </div>

          <div className="flex items-center justify-between text-[11px] text-text-muted pt-0.5">
            <span>
              {progress.isCompleted
                ? progress.isOverTarget
                  ? locale === "ar"
                    ? `متجاوز المستهدف بـ ${(progress.completedMinutes / 60 - progress.targetMinutes! / 60).toFixed(1)}ساعة`
                    : `Over target by ${(progress.completedMinutes / 60 - progress.targetMinutes! / 60).toFixed(1)}h`
                  : locale === "ar"
                  ? "الهدف مكتمل"
                  : "Target fulfilled"
                : locale === "ar"
                ? `متبقي ${progress.remainingHoursFormatted}`
                : `${progress.remainingHoursFormatted} remaining`}
            </span>
            <span>{locale === "ar" ? "الأسبوع الحالي" : "Week active"}</span>
          </div>
        </div>
      )}
    </div>
  );
}

