"use client";

import React, { useState } from "react";
import {
  Timer,
  Zap,
  Activity,
  CheckCircle2,
  BookOpen,
  Smartphone,
  GraduationCap,
  Sparkles,
  Layers,
  AlertCircle,
  Loader2,
  Check,
  Dumbbell,
  Utensils,
  Moon,
  Scale,
} from "lucide-react";
import {
  ModuleKey,
  ALL_MODULE_KEYS,
  MODULE_DEFINITIONS,
} from "@/lib/modules";
import { useUserModules } from "@/lib/modules/UserModulesContext";
import { useI18n } from "@/lib/i18n/I18nContext";

const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
  Dumbbell,
  Utensils,
  Moon,
  Scale,
  Timer,
  Zap,
  Activity,
  CheckCircle2,
  BookOpen,
  Smartphone,
  GraduationCap,
};

export function ModulesTab() {
  const { modules, isModuleActive, toggleModule, saveOnboarding } = useUserModules();
  const { locale } = useI18n();
  const isAr = locale === "ar";

  const [togglingKey, setTogglingKey] = useState<ModuleKey | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const handleToggle = async (key: ModuleKey) => {
    setErrorMsg(null);
    setSuccessMsg(null);
    setTogglingKey(key);

    const currentValue = isModuleActive(key);
    const targetValue = !currentValue;

    // Safety guard: if disabling, ensure at least one remains enabled
    if (!targetValue) {
      const activeCount = ALL_MODULE_KEYS.filter((k) =>
        k === key ? false : isModuleActive(k)
      ).length;

      if (activeCount === 0) {
        setErrorMsg(
          isAr
            ? "لازم يفضل قسم واحد على الأقل مفعّل."
            : "At least one module must remain enabled."
        );
        setTogglingKey(null);
        return;
      }
    }

    const res = await toggleModule(key, targetValue);
    setTogglingKey(null);

    if (!res.success) {
      setErrorMsg(res.error || "Failed to update module");
    } else {
      setSuccessMsg(
        isAr
          ? targetValue
            ? `تم تشغيل ${MODULE_DEFINITIONS[key].labelAr}`
            : `تم إيقاف ${MODULE_DEFINITIONS[key].labelAr}`
          : targetValue
          ? `Enabled ${MODULE_DEFINITIONS[key].labelEn}`
          : `Disabled ${MODULE_DEFINITIONS[key].labelEn}`
      );
      setTimeout(() => setSuccessMsg(null), 3000);
    }
  };

  const handleEnableAll = async () => {
    setErrorMsg(null);
    const res = await saveOnboarding(ALL_MODULE_KEYS);
    if (!res.success) {
      setErrorMsg(res.error || "Failed to enable all modules");
    } else {
      setSuccessMsg(isAr ? "تم تشغيل جميع الأقسام بنجاح" : "All modules enabled");
      setTimeout(() => setSuccessMsg(null), 3000);
    }
  };

  const bodyKeys: ModuleKey[] = [
    "module_workouts",
    "module_nutrition",
    "module_sleep",
    "module_weight",
  ];

  const mindKeys: ModuleKey[] = [
    "module_focus",
    "module_math",
    "module_checkins",
    "module_discipline",
    "module_reading",
    "module_screentime",
  ];

  const schoolKeys: ModuleKey[] = [
    "module_school",
  ];

  const renderModuleRow = (key: ModuleKey) => {
    const def = MODULE_DEFINITIONS[key];
    const active = isModuleActive(key);
    const isUpdating = togglingKey === key;
    const Icon = ICON_MAP[def.icon] || Sparkles;

    return (
      <div
        key={key}
        id={`settings-module-row-${key}`}
        className="p-4 rounded-2xl bg-surface-container/60 border border-border-subtle hover:border-border-medium transition-all flex items-center justify-between gap-4"
      >
        <div className="flex items-start gap-3.5 min-w-0">
          <div
            className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 transition-colors ${
              active
                ? "bg-primary-lime/10 text-primary-lime border border-primary-lime/30"
                : "bg-surface-container-high text-on-surface-variant border border-border-subtle"
            }`}
          >
            <Icon className="w-5 h-5" />
          </div>

          <div className="min-w-0">
            <div className="flex items-center gap-2">
              <h4 className="text-sm font-semibold tracking-tight text-on-surface">
                {isAr ? def.labelAr : def.labelEn}
              </h4>
              <span
                className={`text-[10px] font-mono px-2 py-0.5 rounded-full uppercase tracking-wider ${
                  active
                    ? "bg-primary-lime/20 text-primary-lime border border-primary-lime/30"
                    : "bg-surface-container-highest text-text-muted border border-border-subtle"
                }`}
              >
                {active
                  ? isAr
                    ? "مفعّل"
                    : "Active"
                  : isAr
                  ? "متوقف"
                  : "Disabled"}
              </span>
            </div>
            <p className="text-xs text-on-surface-variant mt-0.5 leading-relaxed">
              {isAr ? def.descriptionAr : def.descriptionEn}
            </p>
          </div>
        </div>

        {/* Toggle Switch */}
        <button
          type="button"
          role="switch"
          id={`settings-toggle-${key}`}
          aria-checked={active}
          disabled={isUpdating}
          onClick={() => handleToggle(key)}
          className={`relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-primary-lime/40 disabled:opacity-50 ${
            active ? "bg-primary-lime" : "bg-surface-container-highest"
          }`}
        >
          {isUpdating ? (
            <span className="absolute inset-0 flex items-center justify-center">
              <Loader2 className="w-3.5 h-3.5 animate-spin text-surface" />
            </span>
          ) : (
            <span
              aria-hidden="true"
              className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-surface shadow-lg ring-0 transition duration-200 ease-in-out ${
                active ? "translate-x-5" : "translate-x-0"
              }`}
            />
          )}
        </button>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Overview Card */}
      <div className="p-6 rounded-2xl bg-surface-container border border-border-subtle relative overflow-hidden">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <Layers className="w-5 h-5 text-primary-lime" />
              <h3 className="text-base font-bold font-mono text-on-surface">
                {isAr ? "تخصيص أقسام التطبيق" : "Module Customization"}
              </h3>
            </div>
            <p className="text-xs text-on-surface-variant leading-relaxed max-w-xl">
              {isAr
                ? "تقدر تظهر أو تخفي أي قسم من أقسام الجسد والعقل والدراسة في أي وقت. إيقاف أي قسم بيخفي واجهته بس، لكن كل بياناتك وسجلاتك بتفضل محفوظة بالكامل."
                : "Customize which modular features are active across Body, Mind, and School. Turning a module off hides its views and Today entries, but never deletes any of your data."}
            </p>
          </div>

          <button
            type="button"
            id="settings-enable-all-btn"
            onClick={handleEnableAll}
            className="px-3.5 py-2 rounded-xl text-xs font-mono font-medium bg-surface-container-high hover:bg-surface-container-highest text-on-surface border border-border-subtle transition-colors shrink-0 cursor-pointer"
          >
            {isAr ? "تشغيل الكل" : "Enable All"}
          </button>
        </div>

        {/* Feedback Alerts */}
        {errorMsg && (
          <div className="mt-4 p-3 rounded-xl bg-error/10 border border-error/30 text-error text-xs flex items-center gap-2 animate-in fade-in">
            <AlertCircle className="w-4 h-4 shrink-0" />
            <span>{errorMsg}</span>
          </div>
        )}

        {successMsg && (
          <div className="mt-4 p-3 rounded-xl bg-primary-lime/10 border border-primary-lime/30 text-primary-lime text-xs flex items-center gap-2 animate-in fade-in">
            <Check className="w-4 h-4 shrink-0" />
            <span>{successMsg}</span>
          </div>
        )}
      </div>

      {/* Body Modules */}
      <div className="space-y-3">
        <div className="flex items-center gap-2 text-xs font-mono font-bold tracking-wider text-on-surface-variant uppercase px-1">
          <Dumbbell className="w-4 h-4 text-primary-lime" />
          <span>{isAr ? "أقسام الجسد والصحة" : "Body & Health Modules"}</span>
        </div>
        <div className="space-y-2.5">{bodyKeys.map(renderModuleRow)}</div>
      </div>

      {/* Mind Modules */}
      <div className="space-y-3">
        <div className="flex items-center gap-2 text-xs font-mono font-bold tracking-wider text-on-surface-variant uppercase px-1">
          <Timer className="w-4 h-4 text-primary-lime" />
          <span>{isAr ? "أقسام العقل والتركيز" : "Mind & Focus Modules"}</span>
        </div>
        <div className="space-y-2.5">{mindKeys.map(renderModuleRow)}</div>
      </div>

      {/* School Modules */}
      <div className="space-y-3">
        <div className="flex items-center gap-2 text-xs font-mono font-bold tracking-wider text-on-surface-variant uppercase px-1">
          <GraduationCap className="w-4 h-4 text-primary-lime" />
          <span>{isAr ? "أقسام الدراسة والمذاكرة" : "School & Academic Modules"}</span>
        </div>
        <div className="space-y-2.5">{schoolKeys.map(renderModuleRow)}</div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import {
  Sliders,
  Globe,
  Languages,
  Volume2,
  Vibrate,
  Clock,
  CheckCircle2,
  AlertTriangle,
} from "lucide-react";
import {
  UserProfile,
  UserSettings,
  WeightUnit,
  AppLocale,
  FocusMode,
  TIMEZONE_OPTIONS,
  TIMEZONE_WARNING,
  saveUserProfileRow,
  saveUserSettingsRow,
} from "@/lib/settings";
import { supabase } from "@/lib/supabase/client";
import { useI18n } from "@/lib/i18n/I18nContext";

interface PreferencesTabProps {
  initialProfile: UserProfile | null;
  initialSettings: UserSettings | null;
  onRefresh: () => void;
}

export function PreferencesTab({
  initialProfile,
  initialSettings,
  onRefresh,
}: PreferencesTabProps) {
  const { locale: i18nLocale, setLocale: setI18nLocale, dict } = useI18n();

  // Profiles preferences
  const [weightUnit, setWeightUnit] = useState<WeightUnit>(
    initialProfile?.weight_unit ?? "kg"
  );
  const [timezone, setTimezone] = useState<string>(
    initialProfile?.timezone ?? "UTC"
  );
  const [locale, setLocale] = useState<AppLocale>(
    (i18nLocale as AppLocale) || initialProfile?.locale || "en"
  );

  // UserSettings preferences
  const [focusMode, setFocusMode] = useState<FocusMode>(
    initialSettings?.default_focus_mode ?? "sprint_50"
  );
  const [chimeEnabled, setChimeEnabled] = useState<boolean>(
    initialSettings?.sound_chime_enabled ?? true
  );
  const [volume, setVolume] = useState<number>(
    initialSettings?.sound_volume ?? 80
  );
  const [vibrationEnabled, setVibrationEnabled] = useState<boolean>(
    initialSettings?.vibration_enabled ?? true
  );
  const [hideAdherence, setHideAdherence] = useState<boolean>(
    initialSettings?.hide_adherence_scores ?? false
  );

  const [saving, setSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  // Web Audio synth chime test
  const playTestChime = () => {
    try {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = "sine";
      osc.frequency.setValueAtTime(528, ctx.currentTime); // Solfeggio 528 Hz DNA repair / clarity chime
      gain.gain.setValueAtTime((volume / 100) * 0.3, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 1.2);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 1.2);
    } catch {}
  };

  const testVibration = () => {
    if (typeof navigator !== "undefined" && "vibrate" in navigator) {
      navigator.vibrate([100, 50, 100]);
    }
  };

  const handleSavePreferences = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!initialProfile?.id) return;

    setSaving(true);
    setSaveError(null);
    setSaveSuccess(false);

    try {
      // 1. Save to profiles
      await saveUserProfileRow(supabase, initialProfile.id, {
        weight_unit: weightUnit,
        timezone: timezone,
        locale: locale,
      });

      // 2. Save to user_settings
      await saveUserSettingsRow(supabase, initialProfile.id, {
        default_focus_mode: focusMode,
        sound_chime_enabled: chimeEnabled,
        sound_volume: volume,
        vibration_enabled: vibrationEnabled,
        hide_adherence_scores: hideAdherence,
      });

      setSaveSuccess(true);
      onRefresh();
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err: any) {
      setSaveError(err.message || "Failed to save preferences.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSavePreferences} className="space-y-6">
      {/* Units & Localization */}
      <div className="p-5 bg-surface-container rounded-2xl border border-border-subtle space-y-4">
        <div className="flex items-center gap-2 pb-3 border-b border-border-subtle">
          <Globe className="w-4 h-4 text-primary-lime" />
          <h3 className="text-sm font-bold font-mono text-on-surface">Units & Localization</h3>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">Weight Display Unit</label>
            <div className="flex items-center gap-2 mt-1">
              <button
                type="button"
                onClick={() => setWeightUnit("kg")}
                className={`flex-1 py-2 rounded-xl text-xs font-mono font-bold transition-all cursor-pointer ${
                  weightUnit === "kg"
                    ? "bg-primary-lime text-on-primary shadow-xs"
                    : "bg-surface-container-low border border-border-subtle text-on-surface"
                }`}
              >
                kg (Metric)
              </button>
              <button
                type="button"
                onClick={() => setWeightUnit("lbs")}
                className={`flex-1 py-2 rounded-xl text-xs font-mono font-bold transition-all cursor-pointer ${
                  weightUnit === "lbs"
                    ? "bg-primary-lime text-on-primary shadow-xs"
                    : "bg-surface-container-low border border-border-subtle text-on-surface"
                }`}
              >
                lbs (Imperial)
              </button>
            </div>
            <p className="text-[10px] text-text-muted mt-1.5">
              Converted on every screen (Weight, Lift Rank, Workouts, Nutrition).
            </p>
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">Timezone (IANA)</label>
            <select
              value={timezone}
              onChange={(e) => setTimezone(e.target.value)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            >
              {TIMEZONE_OPTIONS.map((tz) => (
                <option key={tz} value={tz}>
                  {tz}
                </option>
              ))}
            </select>
            <p className="text-[10px] text-text-muted mt-1.5">
              Controls your daily 00:00 midnight calendar grouping.
            </p>
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {dict.settings.language}
            </label>
            <select
              value={locale}
              onChange={(e) => {
                const next = e.target.value as AppLocale;
                setLocale(next);
                setI18nLocale(next);
              }}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface cursor-pointer"
            >
              <option value="en">English (LTR)</option>
              <option value="ar">العربية - اللهجة المصرية الفصحى (Arabic - RTL)</option>
            </select>
            <p className="text-[10px] text-text-muted mt-1.5">
              {dict.settings.languageHelp}
            </p>
          </div>
        </div>

        {/* Timezone Regrouping Warning Banner */}
        <div className="p-3 bg-amber-core/10 border border-amber-core/20 rounded-xl flex items-start gap-2.5 text-xs font-mono text-amber-core">
          <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
          <div className="leading-relaxed">{TIMEZONE_WARNING}</div>
        </div>
      </div>

      {/* Focus Timer & Feedback Preferences */}
      <div className="p-5 bg-surface-container rounded-2xl border border-border-subtle space-y-4">
        <div className="flex items-center gap-2 pb-3 border-b border-border-subtle">
          <Sliders className="w-4 h-4 text-tertiary-purple" />
          <h3 className="text-sm font-bold font-mono text-on-surface">Feedback & Timer Presets</h3>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              Default Focus Mode Preset
            </label>
            <select
              value={focusMode}
              onChange={(e) => setFocusMode(e.target.value as FocusMode)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            >
              <option value="sprint_50">Sprint 50/10 (50m Work, 10m Break)</option>
              <option value="ultradian_90">Ultradian 90/20 (90m Work, 20m Break)</option>
              <option value="pomodoro_25">Classic Pomodoro 25/5 (25m Work, 5m Break)</option>
              <option value="custom">Custom Duration</option>
            </select>
          </div>

          <div>
            <div className="flex items-center justify-between">
              <label className="text-[11px] font-mono text-text-muted uppercase">
                Harmonic Audio Chime
              </label>
              <button
                type="button"
                onClick={playTestChime}
                className="text-[11px] font-mono text-primary-lime hover:underline cursor-pointer"
              >
                Play Test Chime
              </button>
            </div>
            <div className="flex items-center gap-3 mt-2">
              <input
                type="checkbox"
                id="chimeToggle"
                checked={chimeEnabled}
                onChange={(e) => setChimeEnabled(e.target.checked)}
                className="w-4 h-4 rounded accent-primary-lime cursor-pointer"
              />
              <label htmlFor="chimeToggle" className="text-xs font-mono text-on-surface cursor-pointer">
                Play soft chime on interval complete
              </label>
            </div>
            {chimeEnabled && (
              <div className="mt-2.5 flex items-center gap-3">
                <Volume2 className="w-4 h-4 text-text-muted shrink-0" />
                <input
                  type="range"
                  min="0"
                  max="100"
                  value={volume}
                  onChange={(e) => setVolume(parseInt(e.target.value, 10))}
                  className="w-full accent-primary-lime"
                />
                <span className="text-xs font-mono text-text-muted w-8 text-right">{volume}%</span>
              </div>
            )}
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2">
          <div>
            <div className="flex items-center justify-between">
              <label className="text-[11px] font-mono text-text-muted uppercase">
                Haptic Vibration
              </label>
              <button
                type="button"
                onClick={testVibration}
                className="text-[11px] font-mono text-tertiary-purple hover:underline cursor-pointer"
              >
                Test Vibration
              </button>
            </div>
            <div className="flex items-center gap-3 mt-2">
              <input
                type="checkbox"
                id="vibToggle"
                checked={vibrationEnabled}
                onChange={(e) => setVibrationEnabled(e.target.checked)}
                className="w-4 h-4 rounded accent-primary-lime cursor-pointer"
              />
              <label htmlFor="vibToggle" className="text-xs font-mono text-on-surface cursor-pointer">
                Vibrate on interval complete and rest timer
              </label>
            </div>
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              Adherence Score Display
            </label>
            <div className="flex items-center gap-3 mt-2">
              <input
                type="checkbox"
                id="adherenceToggle"
                checked={hideAdherence}
                onChange={(e) => setHideAdherence(e.target.checked)}
                className="w-4 h-4 rounded accent-primary-lime cursor-pointer"
              />
              <label htmlFor="adherenceToggle" className="text-xs font-mono text-on-surface cursor-pointer">
                Hide percentage badges on meal adherence
              </label>
            </div>
          </div>
        </div>
      </div>

      {saveError && (
        <div className="p-3 bg-crimson-alert/10 border border-crimson-alert/20 rounded-xl text-xs font-mono text-crimson-alert">
          {saveError}
        </div>
      )}

      {saveSuccess && (
        <div className="p-3 bg-emerald-success/10 border border-emerald-success/20 rounded-xl flex items-center gap-2 text-xs font-mono text-emerald-success">
          <CheckCircle2 className="w-4 h-4 shrink-0" />
          <span>Preferences updated successfully!</span>
        </div>
      )}

      <div className="flex justify-end pt-2">
        <button
          type="submit"
          disabled={saving}
          className="px-6 py-2.5 rounded-xl bg-primary-lime text-on-primary text-xs font-mono font-bold uppercase tracking-wider hover:bg-primary-lime-dim shadow-xs cursor-pointer disabled:bg-surface-container-high disabled:text-text-muted disabled:shadow-none disabled:cursor-not-allowed"
        >
          {saving ? "Saving..." : "Save Preferences"}
        </button>
      </div>
    </form>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  Flame,
  Moon,
  Brain,
  Droplets,
  Scale,
  AlertTriangle,
  Info,
  CheckCircle2,
  Clock,
  Sparkles,
} from "lucide-react";
import {
  UserProfile,
  UserSettings,
  SexOption,
  GoalType,
  CaloriePacing,
  checkCalorieSafeFloor,
  checkMacroCalorieMismatch,
  deriveSleepDurationHours,
  checkSleepDurationTolerance,
  getPacingDetails,
  kgToLbs,
  lbsToKg,
  saveUserProfileRow,
  saveUserSettingsRow,
} from "@/lib/settings";
import { supabase } from "@/lib/supabase/client";
import { useI18n } from "@/lib/i18n/I18nContext";

interface ProtocolTabProps {
  initialProfile: UserProfile | null;
  initialSettings: UserSettings | null;
  onRefresh: () => void;
}

export function ProtocolTab({
  initialProfile,
  initialSettings,
  onRefresh,
}: ProtocolTabProps) {
  const { locale, dict } = useI18n();
  // Biometrics & Goals (Profiles)
  const [sex, setSex] = useState<SexOption | null>(initialProfile?.sex ?? null);
  const [birthYear, setBirthYear] = useState<number | null>(initialProfile?.birth_year ?? null);
  const [heightCm, setHeightCm] = useState<number | null>(initialProfile?.height_cm ?? null);
  const [goalType, setGoalType] = useState<GoalType | null>(initialProfile?.goal_type ?? null);
  const [targetWeightDisplay, setTargetWeightDisplay] = useState<string>(
    initialProfile?.target_weight_kg
      ? initialProfile.weight_unit === "lbs"
        ? String(kgToLbs(initialProfile.target_weight_kg))
        : String(initialProfile.target_weight_kg)
      : ""
  );

  // Targets (UserSettings - All Nullable, NO invented defaults)
  const [targetCalories, setTargetCalories] = useState<string>(
    initialSettings?.target_calories ? String(initialSettings.target_calories) : ""
  );
  const [targetProtein, setTargetProtein] = useState<string>(
    initialSettings?.target_protein_g ? String(initialSettings.target_protein_g) : ""
  );
  const [targetCarbs, setTargetCarbs] = useState<string>(
    initialSettings?.target_carbs_g ? String(initialSettings.target_carbs_g) : ""
  );
  const [targetFats, setTargetFats] = useState<string>(
    initialSettings?.target_fats_g ? String(initialSettings.target_fats_g) : ""
  );
  const [waterTarget, setWaterTarget] = useState<string>(
    initialSettings?.water_target_ml ? String(initialSettings.water_target_ml) : ""
  );
  const [caloriePacing, setCaloriePacing] = useState<CaloriePacing | null>(
    initialSettings?.calorie_pacing ?? null
  );

  // Sleep Anchors & Duration
  const [bedtime, setBedtime] = useState<string>(initialSettings?.bedtime_target ?? "");
  const [wakeTime, setWakeTime] = useState<string>(initialSettings?.wake_time_target ?? "");
  const [targetSleepHours, setTargetSleepHours] = useState<string>(
    initialSettings?.target_sleep_hours ? String(initialSettings.target_sleep_hours) : ""
  );
  const [caffeineCutoff, setCaffeineCutoff] = useState<string>(
    initialSettings?.caffeine_cutoff_hours ? String(initialSettings.caffeine_cutoff_hours) : ""
  );
  const [screenCutoff, setScreenCutoff] = useState<string>(
    initialSettings?.screen_cutoff_minutes ? String(initialSettings.screen_cutoff_minutes) : ""
  );

  // Focus Goal
  const [dailyFocusGoal, setDailyFocusGoal] = useState<string>(
    initialSettings?.daily_focus_goal_minutes
      ? String(initialSettings.daily_focus_goal_minutes)
      : ""
  );

  // Feedback states
  const [saving, setSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  const unit = initialProfile?.weight_unit ?? "kg";

  // Real-time validations
  const calNum = targetCalories ? parseInt(targetCalories, 10) : null;
  const pNum = targetProtein ? parseInt(targetProtein, 10) : null;
  const cNum = targetCarbs ? parseInt(targetCarbs, 10) : null;
  const fNum = targetFats ? parseInt(targetFats, 10) : null;
  const sleepHoursNum = targetSleepHours ? parseFloat(targetSleepHours) : null;

  // 1. Safe calorie floor check (warning only, never silent clamp)
  const floorCheck = checkCalorieSafeFloor(calNum, sex);

  // 2. Macro-vs-Calorie consistency (warning only, non-blocking)
  const macroCheck = checkMacroCalorieMismatch(calNum, pNum, cNum, fNum);

  // 3. Circadian sleep derivation
  const derivedSleep = bedtime && wakeTime ? deriveSleepDurationHours(bedtime, wakeTime) : null;
  const sleepTolerance =
    sleepHoursNum !== null && derivedSleep !== null
      ? checkSleepDurationTolerance(sleepHoursNum, derivedSleep)
      : null;

  // Auto-sync sleep duration to derived value if user taps button
  const handleSyncDerivedSleep = () => {
    if (derivedSleep !== null) {
      setTargetSleepHours(String(derivedSleep));
    }
  };

  const handleSaveProtocol = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!initialProfile?.id) return;

    setSaving(true);
    setSaveError(null);
    setSaveSuccess(false);

    try {
      // 1. Calculate target weight in kg for internal storage
      let targetWeightKg: number | null = null;
      if (targetWeightDisplay.trim()) {
        const val = parseFloat(targetWeightDisplay);
        if (!isNaN(val) && val > 0) {
          targetWeightKg = unit === "lbs" ? lbsToKg(val) : val;
        }
      }

      // 2. Save Biometrics & Goals to profiles
      await saveUserProfileRow(supabase, initialProfile.id, {
        sex,
        birth_year: birthYear ? Number(birthYear) : null,
        height_cm: heightCm ? Number(heightCm) : null,
        goal_type: goalType,
        target_weight_kg: targetWeightKg,
      });

      // 3. Save Targets to user_settings
      await saveUserSettingsRow(supabase, initialProfile.id, {
        target_calories: calNum,
        target_protein_g: pNum,
        target_carbs_g: cNum,
        target_fats_g: fNum,
        water_target_ml: waterTarget ? parseInt(waterTarget, 10) : null,
        calorie_pacing: caloriePacing,
        bedtime_target: bedtime || null,
        wake_time_target: wakeTime || null,
        target_sleep_hours: sleepHoursNum,
        caffeine_cutoff_hours: caffeineCutoff ? parseFloat(caffeineCutoff) : null,
        screen_cutoff_minutes: screenCutoff ? parseInt(screenCutoff, 10) : null,
        daily_focus_goal_minutes: dailyFocusGoal ? parseInt(dailyFocusGoal, 10) : null,
      });

      setSaveSuccess(true);
      onRefresh();
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err: any) {
      setSaveError(
        err.message ||
          (locale === "ar"
            ? "فشل حفظ أهداف البروتوكول."
            : "Failed to save protocol targets.")
      );
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSaveProtocol} className="space-y-6">
      {/* Biometrics & Goals Card */}
      <div className="p-5 bg-surface-container rounded-2xl border border-border-subtle space-y-4">
        <div className="flex items-center gap-2 pb-3 border-b border-border-subtle">
          <Scale className="w-4 h-4 text-primary-lime" />
          <h3 className="text-sm font-bold font-mono text-on-surface">
            {locale === "ar" ? "القياسات الحيوية والأهداف" : "Biometrics & Goals"}
          </h3>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "الجنس البيولوجي" : "Biological Sex"}
            </label>
            <select
              value={sex || ""}
              onChange={(e) => setSex((e.target.value as SexOption) || null)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            >
              <option value="">{locale === "ar" ? "غير محدد" : "Not set"}</option>
              <option value="male">{locale === "ar" ? "ذكر" : "Male"}</option>
              <option value="female">{locale === "ar" ? "أنثى" : "Female"}</option>
              <option value="prefer_not_to_say">
                {locale === "ar" ? "أفضل عدم التحديد (محايد)" : "Prefer not to say (Neutral)"}
              </option>
            </select>
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "سنة الميلاد" : "Birth Year"}
            </label>
            <input
              type="number"
              placeholder={locale === "ar" ? "مثال: 1998" : "e.g. 1998"}
              value={birthYear ?? ""}
              onChange={(e) => setBirthYear(e.target.value ? parseInt(e.target.value, 10) : null)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            />
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "الطول (سم)" : "Height (cm)"}
            </label>
            <input
              type="number"
              placeholder={locale === "ar" ? "مثال: 180" : "e.g. 180"}
              value={heightCm ?? ""}
              onChange={(e) => setHeightCm(e.target.value ? parseFloat(e.target.value) : null)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 pt-2">
          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "نوع الهدف" : "Goal Type"}
            </label>
            <select
              value={goalType || ""}
              onChange={(e) => setGoalType((e.target.value as GoalType) || null)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            >
              <option value="">{locale === "ar" ? "غير محدد" : "Not set"}</option>
              <option value="cut">
                {locale === "ar" ? "تنشيف (خسارة دهون)" : "Cut (Fat Loss)"}
              </option>
              <option value="bulk">
                {locale === "ar" ? "تضخيم (زيادة عضلية)" : "Bulk (Muscle Hypertrophy)"}
              </option>
              <option value="recomp">
                {locale === "ar" ? "إعادة تشكيل الجسم (بناء وحرق معاً)" : "Recomp (Body Recomposition)"}
              </option>
            </select>
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar"
                ? `الوزن المستهدف (${unit === "lbs" ? "رطل" : "كجم"})`
                : `Target Weight (${unit})`}
            </label>
            <input
              type="number"
              step="0.1"
              placeholder={
                unit === "lbs"
                  ? locale === "ar"
                    ? "مثال: 165"
                    : "e.g. 165"
                  : locale === "ar"
                  ? "مثال: 75"
                  : "e.g. 75"
              }
              value={targetWeightDisplay}
              onChange={(e) => setTargetWeightDisplay(e.target.value)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            />
            <p className="text-[10px] text-text-muted mt-1">
              {locale === "ar" ? "يتم الحفظ داخلياً بوحدة الكيلوجرام." : "Stored internally in kg."}
            </p>
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "وتيرة التقدم الأسبوعي" : "Weekly Pacing"}
            </label>
            <select
              value={caloriePacing || ""}
              onChange={(e) => setCaloriePacing((e.target.value as CaloriePacing) || null)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            >
              <option value="">{locale === "ar" ? "غير محدد" : "Not set"}</option>
              <option value="conservative">
                {locale === "ar" ? "هادئ / محافظ (~0.25 كجم/أسبوع)" : "Conservative (~0.25 kg/wk)"}
              </option>
              <option value="optimal">
                {locale === "ar" ? "مثالي / متوازن (~0.50 كجم/أسبوع)" : "Optimal (~0.50 kg/wk)"}
              </option>
              <option value="aggressive">
                {locale === "ar" ? "سريع / مكثف (~0.85 كجم/أسبوع)" : "Aggressive (~0.85 kg/wk)"}
              </option>
            </select>
          </div>
        </div>
      </div>

      {/* Nutrition Targets Card */}
      <div className="p-5 bg-surface-container rounded-2xl border border-border-subtle space-y-4">
        <div className="flex items-center justify-between pb-3 border-b border-border-subtle">
          <div className="flex items-center gap-2">
            <Flame className="w-4 h-4 text-amber-core" />
            <h3 className="text-sm font-bold font-mono text-on-surface">
              {locale === "ar" ? "أهداف التغذية والسعرات" : "Nutrition Targets"}
            </h3>
          </div>
          <span className="text-[10px] font-mono text-text-muted">
            {locale === "ar" ? "غير المحدد يظهر كـ \"غير محدد\"" : "Unset targets show \"Not set\""}
          </span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3">
          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "السعرات (سعرة)" : "Calories (kcal)"}
            </label>
            <input
              type="number"
              placeholder={locale === "ar" ? "غير محدد" : "Not set"}
              value={targetCalories}
              onChange={(e) => setTargetCalories(e.target.value)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            />
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "البروتين (جرام)" : "Protein (g)"}
            </label>
            <input
              type="number"
              placeholder={locale === "ar" ? "غير محدد" : "Not set"}
              value={targetProtein}
              onChange={(e) => setTargetProtein(e.target.value)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            />
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "الكربوهيدرات (جرام)" : "Carbs (g)"}
            </label>
            <input
              type="number"
              placeholder={locale === "ar" ? "غير محدد" : "Not set"}
              value={targetCarbs}
              onChange={(e) => setTargetCarbs(e.target.value)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            />
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "الدهون (جرام)" : "Fats (g)"}
            </label>
            <input
              type="number"
              placeholder={locale === "ar" ? "غير محدد" : "Not set"}
              value={targetFats}
              onChange={(e) => setTargetFats(e.target.value)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            />
          </div>

          <div>
            <label className="text-[11px] font-mono text-text-muted uppercase">
              {locale === "ar" ? "الماء (مل)" : "Water (ml)"}
            </label>
            <input
              type="number"
              placeholder={locale === "ar" ? "غير محدد" : "Not set"}
              value={waterTarget}
              onChange={(e) => setWaterTarget(e.target.value)}
              className="w-full mt-1 px-3 py-2 bg-surface-container-low border border-border-subtle rounded-xl text-xs font-mono text-on-surface"
            />
          </div>
        </div>

        {/* Non-blocking Safe Floor Warning */}
        {floorCheck.isBelowFloor && (
          <div className="p-3 bg-amber-core/10 border border-amber-core/20 rounded-xl flex items-start gap-2.5 text-xs font-mono text-amber-core">
            <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
            <div className="leading-relaxed">
              {locale === "ar"
                ? `هدف السعرات (${calNum} سعرة) أقل من الحد الفسيولوجي الآمن الموصى به (${floorCheck.floor} سعرة). العجز الشديد والمستمر قد يسبب هدم الكتلة العضلية والإرهاق.`
                : floorCheck.warning}
            </div>
          </div>
        )}

        {/* Non-blocking Macro-vs-Calorie Discrepancy Notice */}
        {macroCheck.isDiscrepant && (
          <div className="p-3 bg-tertiary-purple/10 border border-tertiary-purple/20 rounded-xl flex items-start gap-2.5 text-xs font-mono text-tertiary-purple">
            <Info className="w-4 h-4 shrink-0 mt-0.5" />
            <div className="leading-relaxed">
              {locale === "ar"
                ? `مجموع الماكروز (${macroCheck.macroCalories} سعرة) يختلف بمقدار (${macroCheck.diff} سعرة) عن هدف السعرات البالغ (${calNum} سعرة).`
                : macroCheck.warning}
            </div>
          </div>
        )}
      </div>

      {/* Circadian & Sleep Targets Card */}
      <div className="p-5 bg-surface-container rounded-2xl border border-border-subtle space-y-4">
        <div className="flex items-center justify-between pb-3 border-b border-border-subtle">
          <div className="flex items-center gap-2">
            <Moon className="w-4 h-4 text-tertiary-purple" />
            <h3 className="text-sm font-bold font-mono text-on-surface">
