"use client";

import React from "react";
import { Sun, Moon, Coffee, ShieldAlert, Sparkles, Info } from "lucide-react";
import { useI18n } from "@/lib/i18n/I18nContext";
import { formatTimeTo12h } from "@/lib/time";

interface CircadianDialProps {
  targetBedtime?: string; // e.g. "23:00"
  targetWakeTime?: string; // e.g. "07:00"
  caffeineCutoffHours?: number; // e.g. 10
  screenCutoffMinutes?: number; // e.g. 60
}

export function CircadianDial({
  targetBedtime = "23:00",
  targetWakeTime = "07:00",
  caffeineCutoffHours = 10,
  screenCutoffMinutes = 60,
}: CircadianDialProps) {
  const { locale } = useI18n();
  // Current local time
  const [nowHour, setNowHour] = React.useState<number>(12);
  const [nowMinute, setNowMinute] = React.useState<number>(0);

  React.useEffect(() => {
    const updateTime = () => {
      const d = new Date();
      setNowHour(d.getHours());
      setNowMinute(d.getMinutes());
    };
    updateTime();
    const interval = setInterval(updateTime, 60000);
    return () => clearInterval(interval);
  }, []);

  const currentPercent = ((nowHour * 60 + nowMinute) / (24 * 60)) * 100;

  // Calculate dynamic landmark times based on bedtime & wake
  const [bedH, bedM] = targetBedtime.split(":").map(Number);
  const [wakeH, wakeM] = targetWakeTime.split(":").map(Number);

  // Caffeine cutoff: bed - caffeineCutoffHours
  const bedTotalMins = bedH * 60 + (bedM || 0);
  let caffeineTotalMins = bedTotalMins - caffeineCutoffHours * 60;
  if (caffeineTotalMins < 0) caffeineTotalMins += 1440;
  const caffH = Math.floor(caffeineTotalMins / 60);
  const caffM = caffeineTotalMins % 60;
  const caffeineTimeFormatted = `${caffH.toString().padStart(2, "0")}:${caffM.toString().padStart(2, "0")}`;

  // Screen cutoff: bed - screenCutoffMinutes
  let screenTotalMins = bedTotalMins - screenCutoffMinutes;
  if (screenTotalMins < 0) screenTotalMins += 1440;
  const screenH = Math.floor(screenTotalMins / 60);
  const screenM = screenTotalMins % 60;
  const screenTimeFormatted = `${screenH.toString().padStart(2, "0")}:${screenM.toString().padStart(2, "0")}`;

  const landmarks = [
    {
      time: formatTimeTo12h(targetWakeTime, { locale }),
      title: locale === "ar" ? "شمس الصباح والصحيان" : "Morning Light & Wake",
      desc: locale === "ar" ? "تحفيز الكورتيزول وتثبيت الساعة البيولوجية (خلال ٦٠ دقيقة)" : "Cortisol spike & phase anchor (within 60m of waking)",
      icon: Sun,
      color: "text-[#7DD3FC] border-[#7DD3FC]/30 bg-[#7DD3FC]/10",
      dotColor: "bg-[#7DD3FC]",
    },
    {
      time: formatTimeTo12h(`${((wakeH + 4) % 24).toString().padStart(2, "0")}:00`, { locale }),
      title: locale === "ar" ? "ذروة النشاط الذهني والبدني" : "Peak Physical / Cognitive",
      desc: locale === "ar" ? "أعلى درجات التركيز وقمة حرارة الجسم" : "Optimal alertness & body temperature peak",
      icon: Sparkles,
      color: "text-primary-lime border-primary-lime/30 bg-primary-lime/10",
      dotColor: "bg-primary-lime",
    },
    {
      time: formatTimeTo12h(caffeineTimeFormatted, { locale }),
      title: locale === "ar" ? "وقف الكافيين" : "Caffeine Cutoff",
      desc: locale === "ar" ? `تنظيف مستقبلات الأدينوزين (${caffeineCutoffHours} ساعات قبل النوم)` : `Adenosine receptor clearance (${caffeineCutoffHours}h before bedtime)`,
      icon: Coffee,
      color: "text-rank-bronze border-rank-bronze/30 bg-rank-bronze/10",
      dotColor: "bg-rank-bronze",
    },
    {
      time: formatTimeTo12h(screenTimeFormatted, { locale }),
      title: locale === "ar" ? "وقف الشاشات والضوء الخافت" : "Screen & Dim Light",
      desc: locale === "ar" ? `بدء إفراز الميلاتونين (${screenCutoffMinutes} دقيقة استرخاء)` : `Melatonin secretion onset (${screenCutoffMinutes}m wind-down)`,
      icon: ShieldAlert,
      color: "text-rank-platinum border-rank-platinum/30 bg-rank-platinum/10",
      dotColor: "bg-rank-platinum",
    },
    {
      time: formatTimeTo12h(targetBedtime, { locale }),
      title: locale === "ar" ? "وقت النوم المستهدف" : "Target Bedtime",
      desc: locale === "ar" ? "إصلاح الخلايا، هرمون النمو، وتثبيت الذاكرة" : "Cellular repair, growth hormone & memory consolidation",
      icon: Moon,
      color: "text-[#7DD3FC] border-[#7DD3FC]/30 bg-[#7DD3FC]/10",
      dotColor: "bg-[#7DD3FC]",
    },
  ];

  return (
    <div className="bg-surface-container rounded-2xl p-5 border border-border-subtle space-y-4">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[#7DD3FC]/10 border border-[#7DD3FC]/20 flex items-center justify-center text-[#7DD3FC]">
            <Sun className="w-4 h-4" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="text-sm font-bold font-mono text-on-surface">
                {locale === "ar" ? "مسار اليوم والنوافذ الشمسية" : "Circadian Dial & Solar Windows"}
              </h3>
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-surface-container-highest text-[10px] font-mono text-text-muted border border-border-subtle">
                <Info className="w-2.5 h-2.5" />
                {locale === "ar" ? "إرشادات عامة" : "General guidance"}
              </span>
            </div>
            <p className="text-[11px] text-on-surface-variant font-mono">
              {locale === "ar"
                ? `إيقاع بيولوجي مرتبط بوقت النوم المستهدف ${formatTimeTo12h(targetBedtime, { locale })}`
                : `Circadian biological rhythm anchored to target bedtime ${formatTimeTo12h(targetBedtime, { locale })}`}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-surface-container-high border border-border-subtle text-[11px] font-mono text-text-muted self-start sm:self-auto">
          <span className="w-1.5 h-1.5 rounded-full bg-primary-lime animate-pulse" />
          <span>
            {formatTimeTo12h(`${nowHour}:${nowMinute}`, { locale })} {locale === "ar" ? "الوقت الحالي" : "Current"}
          </span>
        </div>
      </div>

      {/* 24-Hour Timeline Bar */}
      <div className="relative pt-6 pb-2">
        {/* Track */}
        <div className="h-3 w-full rounded-full bg-surface-container-highest relative overflow-hidden border border-border-subtle">
          {/* Target sleep zone */}
          <div
            className="absolute top-0 bottom-0 bg-[#7DD3FC]/25"
            style={{ left: "0%", width: "29.1%" }}
            title="Rest Window"
          />
          <div
            className="absolute top-0 bottom-0 bg-[#7DD3FC]/25"
            style={{ left: "95.8%", width: "4.2%" }}
            title="Rest Window"
          />
          {/* Morning Sunlight window */}
          <div
            className="absolute top-0 bottom-0 bg-primary-lime/20"
            style={{ left: "29.1%", width: "8.3%" }}
            title="Morning Sunlight"
          />
        </div>

        {/* Current Time Needle */}
        <div
          className="absolute top-3 -translate-x-1/2 flex flex-col items-center pointer-events-none transition-all duration-500 z-10"
          style={{ left: `${currentPercent}%` }}
        >
          <div className="w-2.5 h-2.5 rounded-full bg-primary-lime shadow-[0_0_8px_#C6FF3D]" />
          <div className="w-0.5 h-4 bg-primary-lime" />
        </div>

        {/* Milestone Marks */}
        <div className="flex justify-between text-[10px] font-mono text-text-muted pt-2">
          <span>{formatTimeTo12h("00:00", { locale })}</span>
          <span>{formatTimeTo12h("06:00", { locale })}</span>
          <span>{formatTimeTo12h("12:00", { locale })}</span>
          <span>{formatTimeTo12h("18:00", { locale })}</span>
          <span>{formatTimeTo12h("24:00", { locale })}</span>
        </div>
      </div>

      {/* Protocol Windows Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2.5 pt-1">
        {landmarks.map((lm, idx) => {
          const Icon = lm.icon;
          return (
            <div
              key={idx}
              className="p-3 rounded-xl bg-surface-container-high/60 border border-border-subtle flex items-start gap-2.5 transition-all hover:bg-surface-container-high"
            >
              <div className={`w-7 h-7 rounded-lg border flex items-center justify-center shrink-0 ${lm.color}`}>
                <Icon className="w-3.5 h-3.5" />
              </div>
              <div className="min-w-0 flex-1">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold font-mono text-on-surface truncate">
                    {lm.title}
                  </span>
                  <span className="text-[10px] font-mono text-[#7DD3FC] ml-1 shrink-0">
                    {lm.time}
                  </span>
                </div>
                <p className="text-[10px] text-on-surface-variant line-clamp-1 mt-0.5">
                  {lm.desc}
                </p>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  Moon,
  Sparkles,
  Clock,
  RotateCcw,
  Plus,
  AlertTriangle,
  Edit2,
  Trash2,
  Settings as SettingsIcon,
  Sun,
  ShieldAlert,
  Loader2,
  Coffee,
} from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { useOnlineGuard } from "@/hooks/useOnlineGuard";
import {
  SleepEntry,
  calculateSleepScore,
  calculateCircularMidpointConsistency,
  calculateSleepStats,
} from "@/lib/sleep";
import { SleepLogModal } from "@/components/sleep/SleepLogModal";
import { CircadianDial } from "@/components/sleep/CircadianDial";
import { SleepTrendChart } from "@/components/sleep/SleepTrendChart";
import { useI18n } from "@/lib/i18n/I18nContext";
import { formatTimeTo12h } from "@/lib/time";

export function SleepDashboard() {
  const { guardAction } = useOnlineGuard();
  const { locale } = useI18n();

  const [userId, setUserId] = useState<string | null>(null);
  const [entries, setEntries] = useState<SleepEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Settings (All targets strictly nullable: NO invented defaults)
  const [sleepTargetHours, setSleepTargetHours] = useState<number | null>(null);
  const [caffeineCutoffHours, setCaffeineCutoffHours] = useState<number | null>(null);
  const [screenCutoffMinutes, setScreenCutoffMinutes] = useState<number | null>(null);
  const [timezone, setTimezone] = useState<string>("UTC");

  // Modals & UI States
  const [isLogModalOpen, setIsLogModalOpen] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<SleepEntry | null>(null);

  // Undo Toast state
  const [lastDeletedEntry, setLastDeletedEntry] = useState<SleepEntry | null>(null);
  const [showUndoBanner, setShowUndoBanner] = useState(false);

  // Load user profile & sleep logs
  const loadSleepData = async () => {
    try {
      setLoading(true);
      setError(null);

      const {
        data: { user },
      } = await supabase.auth.getUser();

      if (!user) {
        setLoading(false);
        return;
      }
      setUserId(user.id);

      // 1. Fetch user targets from user_settings (with profiles fallback)
      const { data: settData } = await supabase
        .from("user_settings")
        .select("target_sleep_hours, caffeine_cutoff_hours, screen_cutoff_minutes")
        .eq("user_id", user.id)
        .maybeSingle();

      const { data: profile } = await supabase
        .from("profiles")
        .select("sleep_target_hours, caffeine_cutoff_hours, screen_cutoff_minutes, timezone")
        .eq("id", user.id)
        .single();

      if (settData?.target_sleep_hours !== null && settData?.target_sleep_hours !== undefined) {
        setSleepTargetHours(Number(settData.target_sleep_hours));
      } else if (profile?.sleep_target_hours !== null && profile?.sleep_target_hours !== undefined) {
        setSleepTargetHours(Number(profile.sleep_target_hours));
      } else {
        setSleepTargetHours(null);
      }

      if (settData?.caffeine_cutoff_hours !== null && settData?.caffeine_cutoff_hours !== undefined) {
        setCaffeineCutoffHours(Number(settData.caffeine_cutoff_hours));
      } else if (profile?.caffeine_cutoff_hours !== null && profile?.caffeine_cutoff_hours !== undefined) {
        setCaffeineCutoffHours(Number(profile.caffeine_cutoff_hours));
      }

      if (settData?.screen_cutoff_minutes !== null && settData?.screen_cutoff_minutes !== undefined) {
        setScreenCutoffMinutes(Number(settData.screen_cutoff_minutes));
      } else if (profile?.screen_cutoff_minutes !== null && profile?.screen_cutoff_minutes !== undefined) {
        setScreenCutoffMinutes(Number(profile.screen_cutoff_minutes));
      }

      if (profile?.timezone) setTimezone(profile.timezone);

      // 2. Fetch from sleep_logs table (Single Source of Truth - NO events fallback)
      const { data: logsData, error: logsErr } = await supabase
        .from("sleep_logs")
        .select("id, user_id, sleep_date, bedtime, wake_time, duration_minutes, quality_rating, awakenings_count, nap_minutes, notes, created_at, deleted_at")
        .eq("user_id", user.id)
        .is("deleted_at", null)
        .order("sleep_date", { ascending: false });

      if (logsErr) {
        // Honest error display if table is missing or write fails
        setError(
          `sleep_logs table: ${logsErr.message} (Code: ${logsErr.code}). Please apply migration 003_sleep_and_circadian.sql in Supabase SQL Editor.`
        );
        setLoading(false);
        return;
      }

      const parsed: SleepEntry[] = (logsData || []).map((row) => ({
        id: row.id,
        user_id: row.user_id,
        sleep_date: row.sleep_date,
        bedtime: row.bedtime,
        wake_time: row.wake_time,
        duration_minutes: Number(row.duration_minutes),
        quality_rating: row.quality_rating,
        awakenings_count: row.awakenings_count ?? 0,
        nap_minutes: row.nap_minutes ?? 0,
        notes: row.notes || undefined,
        created_at: row.created_at,
        deleted_at: row.deleted_at || null,
      }));

      setEntries(parsed);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Error fetching sleep telemetry";
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadSleepData();
  }, []);

  // Save or Update Entry
  const handleSaveEntry = async (payload: {
    id?: string;
    sleep_date: string;
    bedtime: string;
    wake_time: string;
    quality_rating: number | null;
    awakenings_count: number;
    nap_minutes: number;
    notes: string;
  }) => {
    if (!userId) return;

    await guardAction(async () => {
      if (payload.id) {
        // Update existing entry
        const { error: updErr } = await supabase
          .from("sleep_logs")
          .update({
            sleep_date: payload.sleep_date,
            bedtime: payload.bedtime,
            wake_time: payload.wake_time,
            quality_rating: payload.quality_rating,
            awakenings_count: payload.awakenings_count,
            nap_minutes: payload.nap_minutes,
            notes: payload.notes || null,
          })
          .eq("id", payload.id);

        if (updErr) throw new Error(updErr.message);

        setEntries((prev) =>
          prev.map((e) =>
            e.id === payload.id
              ? {
                  ...e,
                  ...payload,
                  duration_minutes: Math.round(
                    (new Date(payload.wake_time).getTime() - new Date(payload.bedtime).getTime()) / 60000
                  ),
                }
              : e
          )
        );
      } else {
        // Insert new entry
        const { data: newRow, error: insErr } = await supabase
          .from("sleep_logs")
          .insert({
            user_id: userId,
            sleep_date: payload.sleep_date,
            bedtime: payload.bedtime,
            wake_time: payload.wake_time,
            quality_rating: payload.quality_rating,
            awakenings_count: payload.awakenings_count,
            nap_minutes: payload.nap_minutes,
            notes: payload.notes || null,
          })
          .select()
          .single();

        if (insErr) throw new Error(insErr.message);

        const newEntry: SleepEntry = {
          id: newRow.id,
          user_id: newRow.user_id,
          sleep_date: newRow.sleep_date,
          bedtime: newRow.bedtime,
          wake_time: newRow.wake_time,
          duration_minutes: Number(newRow.duration_minutes),
          quality_rating: newRow.quality_rating,
          awakenings_count: newRow.awakenings_count ?? 0,
          nap_minutes: newRow.nap_minutes ?? 0,
          notes: newRow.notes || undefined,
        };

        const updated = [newEntry, ...entries].sort((a, b) => b.sleep_date.localeCompare(a.sleep_date));
        setEntries(updated);
      }
    });
  };

  // Soft Delete with Undo
  const handleDeleteEntry = async (entry: SleepEntry) => {
    guardAction(async () => {
      try {
        const { error: delErr } = await supabase
          .from("sleep_logs")
          .update({ deleted_at: new Date().toISOString() })
          .eq("id", entry.id);

        if (delErr) throw new Error(delErr.message);

        const remaining = entries.filter((e) => e.id !== entry.id);
        setEntries(remaining);

        setLastDeletedEntry(entry);
        setShowUndoBanner(true);

        setTimeout(() => {
          setShowUndoBanner(false);
        }, 8000);
      } catch (err: unknown) {
        const msg = err instanceof Error ? err.message : "Failed to soft-delete entry";
        alert(msg);
      }
    });
  };

  // Undo Soft Delete
  const handleUndoDelete = async () => {
    if (!lastDeletedEntry) return;

    guardAction(async () => {
      try {
        const { error: undoErr } = await supabase
          .from("sleep_logs")
          .update({ deleted_at: null })
          .eq("id", lastDeletedEntry.id);

        if (undoErr) throw new Error(undoErr.message);

        const restored = [lastDeletedEntry, ...entries].sort((a, b) => b.sleep_date.localeCompare(a.sleep_date));
        setEntries(restored);
        setLastDeletedEntry(null);
        setShowUndoBanner(false);
      } catch (err: unknown) {
        const msg = err instanceof Error ? err.message : "Failed to undo delete";
        alert(msg);
      }
    });
  };

  // Save Settings Modal
  const handleSaveSettings = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userId) return;

    guardAction(async () => {
      try {
        const { error: sErr } = await supabase
          .from("profiles")
          .update({
            sleep_target_hours: sleepTargetHours,
            caffeine_cutoff_hours: caffeineCutoffHours,
            screen_cutoff_minutes: screenCutoffMinutes,
            timezone: timezone,
          })
          .eq("id", userId);

        if (sErr) throw new Error(sErr.message);
        setIsSettingsModalOpen(false);
      } catch (err: unknown) {
        alert(err instanceof Error ? err.message : "Failed to save settings");
      }
    });
  };

  // Metrics computation
  const stats = calculateSleepStats(entries, sleepTargetHours ?? undefined);
  const midpoint = calculateCircularMidpointConsistency(entries);
  const latestEntry = entries.length > 0 ? entries[0] : null;
  const latestScore = latestEntry
    ? calculateSleepScore(
        latestEntry.duration_minutes,
        sleepTargetHours ?? undefined,
        latestEntry.quality_rating,
        latestEntry.awakenings_count
      )
    : null;

  if (loading) {
    return (
      <div className="py-20 flex flex-col items-center justify-center text-center space-y-3 font-mono">
        <Loader2 className="w-8 h-8 text-[#7DD3FC] animate-spin" />
