                  All: "الكل",
                  Chest: "صدر",
                  Back: "ظهر",
                  Legs: "رجلين",
                  Shoulders: "أكتاف",
                  Arms: "دراع",
                  Core: "بطن",
                  "Full Body": "جسم كامل",
