                          ? locale === "ar"
                            ? `+${lift.kgToGo} كجم`
                            : `+${lift.kgToGo} kg`
                          : ""}
                      </span>
                    </div>
                    <div className="w-full h-1.5 bg-surface-container-high rounded-full overflow-hidden">
                      <div
                        className="h-full bg-primary-lime rounded-full"
                        style={{ width: `${lift.progressPercent}%` }}
                      />
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

