"use client";

import React, { useState, useEffect } from "react";
import {
  History,
  Calendar,
  Clock,
  Dumbbell,
  ChevronDown,
  ChevronUp,
  Trash2,
  CheckCircle2,
  Loader2,
  AlertCircle,
  Plus,
} from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { useI18n } from "@/lib/i18n/I18nContext";

interface WorkoutHistoryItem {
  id: string;
  name: string;
  started_at: string;
  completed_at: string | null;
  workout_exercises: {
    id: string;
    order_in_workout: number;
    exercise_id: string;
    exercises: {
      id: string;
      name: string;
      muscle_group: string;
    } | null;
    workout_sets: {
      id: string;
      set_number: number;
      weight_kg: number;
      reps: number;
      is_completed: boolean;
      e1rm_kg: number | null;
    }[];
  }[];
}

interface WorkoutHistoryProps {
  onStartWorkoutClick?: () => void;
}

export function WorkoutHistory({ onStartWorkoutClick }: WorkoutHistoryProps) {
  const { locale } = useI18n();
  const [workouts, setWorkouts] = useState<WorkoutHistoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedWorkoutId, setExpandedWorkoutId] = useState<string | null>(null);

  const fetchHistory = async () => {
    try {
      setLoading(true);
      setError(null);

      const {
        data: { user },
      } = await supabase.auth.getUser();

      if (!user) {
        setWorkouts([]);
        return;
      }

      const query =
        "id, name, started_at, completed_at, workout_exercises(id, order_in_workout, exercise_id, exercises(id, name, muscle_group), workout_sets(id, set_number, weight_kg, reps, is_completed, e1rm_kg))";

      const { data, error: fetchErr } = await supabase
        .from("workouts")
        .select(query)
        .eq("user_id", user.id)
        .is("deleted_at", null)
        .order("started_at", { ascending: false });

      if (fetchErr) {
        throw new Error(fetchErr.message);
      }

      if (data) {
        // cast data to WorkoutHistoryItem[]
        setWorkouts(data as unknown as WorkoutHistoryItem[]);
        if (data.length > 0) {
          setExpandedWorkoutId(data[0].id);
        }
      }
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : "Failed to load workout history";
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchHistory();
  }, []);

  const handleDelete = async (workoutId: string) => {
    const confirmMsg = locale === "ar"
      ? "متأكد إنك عاوز تحذف سجل التمرين ده؟"
      : "Are you sure you want to remove this workout log?";
    if (!confirm(confirmMsg)) return;

    try {
      const { error: delErr } = await supabase
        .from("workouts")
        .update({ deleted_at: new Date().toISOString() })
        .eq("id", workoutId);

      if (delErr) {
        alert(locale === "ar" ? `فشل الحذف: ${delErr.message}` : `Failed to delete: ${delErr.message}`);
      } else {
        setWorkouts((prev) => prev.filter((w) => w.id !== workoutId));
      }
    } catch (err) {
      console.error("Delete error:", err);
    }
  };

  return (
    <div className="space-y-6">
      {/* Top Banner */}
      <div className="bg-surface-container rounded-2xl p-5 border border-border-subtle flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 rounded-xl bg-secondary-cyan/10 border border-secondary-cyan/30 flex items-center justify-center text-secondary-cyan shadow-[0_0_16px_rgba(93,230,255,0.2)]">
            <History className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-lg font-bold font-mono text-on-surface">
              {locale === "ar" ? "سجل التمارين والحجم التدريبي" : "Session History & Volume"}
            </h2>
            <p className="text-xs text-on-surface-variant">
              {locale === "ar"
                ? "سجل زمني لجميع التمارين المنتهية، إجمالي الأوزان المرفوعة، وبيانات كل جولة"
                : "Chronological log of completed workouts, tonnage, and individual set telemetry"}
            </p>
          </div>
        </div>

        {onStartWorkoutClick && (
          <button
            onClick={onStartWorkoutClick}
            className="flex items-center gap-2 px-4 py-2 rounded-xl bg-primary-lime text-on-primary font-mono font-bold text-xs uppercase tracking-wider transition-all cursor-pointer hover:bg-primary-lime/90 shadow-xs self-start sm:self-auto"
          >
            <Plus className="w-4 h-4" />
            <span>{locale === "ar" ? "تمرين جديد" : "New Session"}</span>
          </button>
        )}
      </div>

      {error && (
        <div className="p-4 bg-crimson-alert/10 border border-crimson-alert/30 rounded-xl flex items-center gap-2 text-crimson-alert text-xs font-mono">
          <AlertCircle className="w-4 h-4 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {loading && (
        <div className="p-12 flex flex-col items-center justify-center text-on-surface-variant gap-3">
          <Loader2 className="w-6 h-6 animate-spin text-secondary-cyan" />
          <span className="text-xs font-mono">
            {locale === "ar" ? "جاري تحميل سجل التمارين..." : "Loading workout telemetry..."}
          </span>
        </div>
      )}

      {/* Empty State */}
      {!loading && workouts.length === 0 && (
        <div className="p-12 bg-surface-container rounded-2xl border border-border-subtle text-center space-y-4">
          <div className="w-12 h-12 rounded-xl bg-surface-container-high border border-border-subtle flex items-center justify-center text-text-muted mx-auto">
            <Dumbbell className="w-6 h-6" />
          </div>
          <div className="space-y-1">
            <h3 className="text-sm font-bold font-mono text-on-surface">
              {locale === "ar" ? "لسه مفيش تمارين متسجلة" : "No Workouts Recorded Yet"}
            </h3>
            <p className="text-xs text-on-surface-variant max-w-sm mx-auto">
              {locale === "ar"
                ? "تمارينك وجولات القوة هتظهر هنا فور حفظها."
                : "Your logged sessions and strength sets will appear here once saved."}
            </p>
          </div>
          {onStartWorkoutClick && (
            <button
              onClick={onStartWorkoutClick}
              className="px-4 py-2 rounded-xl bg-primary-lime text-on-primary font-mono font-bold text-xs uppercase tracking-wider inline-flex items-center gap-2 transition-all cursor-pointer hover:bg-primary-lime/90 shadow-xs"
            >
              <Plus className="w-4 h-4" />
              <span>{locale === "ar" ? "ابدأ تمرينك دلوقتي" : "Start Workout Now"}</span>
            </button>
          )}
        </div>
      )}

      {/* Workouts List */}
      {!loading && workouts.length > 0 && (
        <div className="space-y-4">
          {workouts.map((workout) => {
            const isExpanded = expandedWorkoutId === workout.id;
            const startDate = new Date(workout.started_at);
            const formattedDate = startDate.toLocaleDateString(locale === "ar" ? "ar-EG" : undefined, {
              weekday: "short",
              month: "short",
              day: "numeric",
              year: "numeric",
            });
            const formattedTime = startDate.toLocaleTimeString(locale === "ar" ? "ar-EG" : undefined, {
              hour: "numeric",
              minute: "2-digit",
              hour12: true,
            });

            // Calculate metrics
            let totalTonnage = 0;
            let totalCompletedSets = 0;
            const sortedExercises = [...(workout.workout_exercises || [])].sort(
              (a, b) => a.order_in_workout - b.order_in_workout
            );

            for (const we of sortedExercises) {
              for (const set of we.workout_sets || []) {
                if (set.is_completed) {
                  totalCompletedSets += 1;
                  totalTonnage += Number(set.weight_kg) * Number(set.reps);
                }
              }
            }

            return (
              <div
                key={workout.id}
                className="bg-surface-container rounded-2xl border border-border-subtle overflow-hidden transition-all"
              >
                {/* Header Summary */}
                <div
                  onClick={() => setExpandedWorkoutId(isExpanded ? null : workout.id)}
                  className="p-5 flex flex-col sm:flex-row sm:items-center justify-between gap-4 cursor-pointer hover:bg-surface-container-high/40 transition-colors"
                >
                  <div className="space-y-1.5">
                    <div className="flex items-center gap-2">
                      <h3 className="text-base font-bold font-mono text-on-surface">
                        {workout.name}
                      </h3>
                      {workout.completed_at && (
                        <span className="flex items-center gap-1 text-[10px] font-mono text-status-success bg-status-success/10 px-2 py-0.5 rounded-md border border-status-success/30 font-bold">
                          <CheckCircle2 className="w-3 h-3" />
                          <span>{locale === "ar" ? "مكتمل" : "Finished"}</span>
                        </span>
                      )}
                    </div>
                    <div className="flex items-center gap-3 text-xs font-mono text-text-muted">
                      <span className="flex items-center gap-1">
                        <Calendar className="w-3.5 h-3.5 text-primary-lime" />
                        <span>{formattedDate}</span>
                      </span>
                      <span>•</span>
                      <span className="flex items-center gap-1">
                        <Clock className="w-3.5 h-3.5" />
                        <span>{formattedTime}</span>
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    {/* Tonnage Badge */}
                    <div className="bg-surface-container-high px-3 py-1.5 rounded-xl border border-border-subtle text-end">
                      <span className="text-[10px] font-mono text-text-muted block">
                        {locale === "ar" ? "إجمالي الحجم" : "VOLUME"}
                      </span>
                      <span className="text-xs font-bold font-mono text-primary-lime">
                        {Math.round(totalTonnage).toLocaleString()} {locale === "ar" ? "كجم" : "kg"}
                      </span>
                    </div>

                    {/* Sets Count */}
                    <div className="bg-surface-container-high px-3 py-1.5 rounded-xl border border-border-subtle text-end">
                      <span className="text-[10px] font-mono text-text-muted block">
                        {locale === "ar" ? "الجولات" : "SETS"}
                      </span>
                      <span className="text-xs font-bold font-mono text-secondary-cyan">
                        {totalCompletedSets}
                      </span>
                    </div>

                    {/* Delete Workout */}
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDelete(workout.id);
                      }}
                      className="w-8 h-8 rounded-lg hover:bg-surface-container-highest text-text-muted hover:text-crimson-alert flex items-center justify-center transition-colors cursor-pointer"
                      title={locale === "ar" ? "حذف التمرين" : "Delete workout"}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>

                    {/* Expand Arrow */}
                    <div className="w-8 h-8 rounded-lg bg-surface-container-high flex items-center justify-center text-text-muted">
                      {isExpanded ? (
                        <ChevronUp className="w-4 h-4" />
                      ) : (
                        <ChevronDown className="w-4 h-4" />
                      )}
                    </div>
                  </div>
                </div>

                {/* Expanded Details */}
                {isExpanded && (
                  <div className="px-5 pb-5 pt-2 border-t border-border-subtle/50 space-y-4 bg-surface-container-low/40">
                    {sortedExercises.map((we, idx) => (
                      <div
                        key={we.id}
                        className="bg-surface-container border border-border-subtle rounded-xl p-4 space-y-3"
                      >
                        <div className="flex items-center justify-between pb-2 border-b border-border-subtle">
                          <div className="flex items-center gap-2">
                            <span className="text-xs font-mono font-bold text-text-muted">
                              #{idx + 1}
                            </span>
                            <span className="text-sm font-bold font-mono text-on-surface">
                              {we.exercises?.name || (locale === "ar" ? "تمرين" : "Exercise")}
                            </span>
                          </div>
                          <span className="text-[11px] font-mono text-text-muted capitalize">
                            {we.exercises?.muscle_group || ""}
                          </span>
                        </div>

                        {/* Sets table */}
                        <div className="overflow-x-auto">
                          <table className="w-full text-start text-xs font-mono">
                            <thead>
                              <tr className="text-text-muted border-b border-border-subtle/30 pb-1">
                                <th className="py-1 px-2 w-16">{locale === "ar" ? "الجولة" : "SET"}</th>
                                <th className="py-1 px-2">{locale === "ar" ? "الوزن" : "WEIGHT"}</th>
                                <th className="py-1 px-2">{locale === "ar" ? "العدات" : "REPS"}</th>
                                <th className="py-1 px-2">{locale === "ar" ? "التقديري 1RM" : "EST. 1RM"}</th>
                                <th className="py-1 px-2 text-end">{locale === "ar" ? "الحالة" : "STATUS"}</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-border-subtle/20">
                              {(we.workout_sets || []).map((s) => (
                                <tr key={s.id} className="text-on-surface">
                                  <td className="py-2 px-2 text-text-muted font-bold">
                                    {locale === "ar" ? `جولة ${s.set_number}` : `Set ${s.set_number}`}
                                  </td>
                                  <td className="py-2 px-2 font-bold text-on-surface">
                                    {s.weight_kg} {locale === "ar" ? "كجم" : "kg"}
                                  </td>
                                  <td className="py-2 px-2 font-bold text-on-surface">
                                    {s.reps} {locale === "ar" ? "عدة" : "reps"}
                                  </td>
                                  <td className="py-2 px-2">
                                    {s.e1rm_kg ? (
                                      <span className="text-primary-lime font-bold">
                                        {s.e1rm_kg} {locale === "ar" ? "كجم" : "kg"}
                                      </span>
                                    ) : (
                                      <span className="text-text-muted">-</span>
                                    )}
                                  </td>
                                  <td className="py-2 px-2 text-end">
                                    {s.is_completed ? (
                                      <span className="text-status-success font-semibold">
                                        ✓ {locale === "ar" ? "تم بنجاح" : "Completed"}
                                      </span>
                                    ) : (
                                      <span className="text-text-muted">
                                        {locale === "ar" ? "تم التخطي" : "Skipped"}
                                      </span>
                                    )}
                                  </td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import {
  CheckSquare,
  Square,
  Plus,
  Trash2,
  Calendar,
  Clock,
  Sparkles,
  ArrowRight,
  Dumbbell,
  GraduationCap,
  Brain,
  CheckCircle2,
  X,
  Loader2,
} from "lucide-react";
import { PriorityItem, PrioritySource } from "@/lib/today";
import { supabase } from "@/lib/supabase/client";
import { useI18n } from "@/lib/i18n/I18nContext";

interface PrioritiesCardProps {
  priorities: PriorityItem[];
  todayDateStr: string;
  tomorrowDateStr: string;
  onPrioritiesChange: (updated: PriorityItem[]) => void;
  userId?: string | null;
}

export function PrioritiesCard({
  priorities,
  todayDateStr,
  tomorrowDateStr,
  onPrioritiesChange,
  userId,
}: PrioritiesCardProps) {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newSource, setNewSource] = useState<PrioritySource>("custom");
  const [newEstimate, setNewEstimate] = useState<number>(30);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Toggle priority completion (strictly allowed for 'custom' tasks)
  const handleToggle = async (item: PriorityItem) => {
    const updatedStatus = !item.completed;
    const nowIso = updatedStatus ? new Date().toISOString() : null;

    const nextList = priorities.map((p) =>
      p.id === item.id
        ? {
            ...p,
            completed: updatedStatus,
            completed_at: nowIso,
            auto_completed: false,
          }
        : p
    );
    onPrioritiesChange(nextList);

    // Save to database if user is authenticated
    if (userId && !item.id.startsWith("temp-")) {
      try {
        await supabase
          .from("priorities")
          .update({
            completed: updatedStatus,
            completed_at: nowIso,
            auto_completed: false,
            updated_at: new Date().toISOString(),
          })
          .eq("id", item.id)
          .eq("user_id", userId);
      } catch {
        // Fallback gracefully
      }
    }
  };

  // Delete priority
  const handleDelete = async (id: string) => {
    const nextList = priorities.filter((p) => p.id !== id);
    onPrioritiesChange(nextList);

    if (userId && !id.startsWith("temp-")) {
      try {
        await supabase
          .from("priorities")
          .update({ deleted_at: new Date().toISOString() })
          .eq("id", id)
          .eq("user_id", userId);
      } catch {
        // Fallback gracefully
      }
    }
  };

  // Add new custom or planned priority
  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTitle.trim()) return;

    setIsSubmitting(true);
    const tempId = `temp-${Date.now()}`;
    const newItem: PriorityItem = {
      id: tempId,
      priority_date: todayDateStr,
      title: newTitle.trim(),
      source: newSource,
      estimate_minutes: newEstimate,
      sort_order: priorities.length,
      completed: false,
      auto_completed: false,
      created_at: new Date().toISOString(),
    };

    const nextList = [...priorities, newItem];
    onPrioritiesChange(nextList);

    if (userId) {
      try {
        const { data } = await supabase
          .from("priorities")
          .insert({
            user_id: userId,
            priority_date: todayDateStr,
            title: newTitle.trim(),
            source: newSource,
            estimate_minutes: newEstimate,
            sort_order: priorities.length,
            completed: false,
            auto_completed: false,
          })
          .select("id")
          .single();

        if (data?.id) {
          onPrioritiesChange(
            nextList.map((p) => (p.id === tempId ? { ...p, id: data.id } : p))
          );
        }
      } catch {
        // Fallback gracefully
      }
    }

    setNewTitle("");
    setNewEstimate(30);
    setIsAddModalOpen(false);
    setIsSubmitting(false);
  };

  // Carry over incomplete tasks to tomorrow
  const handleCarryOver = async () => {
    const incomplete = priorities.filter((p) => !p.completed);
    if (incomplete.length === 0) return;

    if (userId) {
      for (const item of incomplete) {
        try {
          await supabase.from("priorities").insert({
            user_id: userId,
            priority_date: tomorrowDateStr,
            title: item.title,
            source: item.source,
            source_id: item.source_id,
            estimate_minutes: item.estimate_minutes,
            sort_order: item.sort_order,
            completed: false,
            auto_completed: false,
          });
        } catch {
          // Graceful fallback
        }
      }
    }
    alert(`Carried over ${incomplete.length} task${incomplete.length === 1 ? '' : 's'} to tomorrow (${tomorrowDateStr}).`);
  };

  const { locale } = useI18n();
  const completedCount = priorities.filter((p) => p.completed).length;

  const getSourceLabel = (src: PrioritySource) => {
    if (locale !== "ar") return src.replace("_", " ");
    switch (src) {
      case "workout_plan":
        return "تمرين";
      case "deadline":
        return "ميعاد تسليم";
      case "study_goal":
        return "مذاكرة";
      default:
        return "مهمة خاصة";
    }
  };

  return (
    <div className="p-5 rounded-2xl bg-surface-container border border-border-subtle space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between pb-3 border-b border-border-subtle">
        <div className="flex items-center gap-2.5">
          <CheckSquare className="w-4 h-4 text-primary-lime" />
          <h3 className="text-xs font-mono uppercase tracking-wider text-on-surface font-semibold">
            {locale === "ar" ? "أولويات النهاردة" : "Today's Priorities"}
          </h3>
          <span className="text-[11px] font-mono text-text-muted">
            ({completedCount}/{priorities.length} {locale === "ar" ? "اتنفذوا" : "done"})
          </span>
        </div>

        <button
          onClick={() => setIsAddModalOpen(true)}
          className="flex items-center gap-1 px-2.5 py-1 rounded-lg bg-surface-container-high hover:bg-surface-container-highest border border-border-subtle text-[11px] font-mono text-on-surface transition-colors cursor-pointer"
        >
          <Plus className="w-3.5 h-3.5 text-primary-lime" />
          <span>{locale === "ar" ? "أضف مهمة" : "Add Task"}</span>
        </button>
      </div>

      {/* List */}
      {priorities.length === 0 ? (
        <div className="py-6 text-center space-y-2">
          <p className="text-xs text-text-muted">
            {locale === "ar"
              ? "مفيش أولويات متسجلة للنهاردة لسه."
              : "No priorities scheduled for today."}
          </p>
          <button
            onClick={() => setIsAddModalOpen(true)}
            className="text-xs font-mono text-secondary-cyan hover:underline cursor-pointer"
          >
            {locale === "ar" ? "+ حدد أول أولوياتك للنهاردة" : "+ Set your first priority"}
          </button>
        </div>
      ) : (
        <div className="space-y-2">
          {priorities.map((item) => {
            const isCustom = item.source === "custom";

            const getSourceIcon = () => {
              switch (item.source) {
                case "workout_plan":
                  return <Dumbbell className="w-3.5 h-3.5 text-secondary-cyan" />;
                case "deadline":
                  return <GraduationCap className="w-3.5 h-3.5 text-amber-core" />;
                case "study_goal":
                  return <Brain className="w-3.5 h-3.5 text-tertiary-purple" />;
                default:
                  return <CheckSquare className="w-3.5 h-3.5 text-text-muted" />;
              }
            };

            return (
              <div
                key={item.id}
                className={`p-3 rounded-xl border flex items-center justify-between gap-3 transition-colors ${
                  item.completed
                    ? "bg-surface-container-low/60 border-border-subtle/60 text-text-muted"
                    : "bg-surface-container-low border-border-subtle text-on-surface"
                }`}
              >
                <div className="flex items-center gap-3 min-w-0">
                  {/* Checkbox button */}
                  <button
                    onClick={() => isCustom && handleToggle(item)}
                    disabled={!isCustom}
                    className={`shrink-0 cursor-pointer ${
                      !isCustom ? "cursor-default opacity-80" : ""
                    }`}
                    title={
                      !isCustom
                        ? (locale === "ar" ? "مهمة سيستم: بتتعلم تلقائي لما تسجل الداتا" : "System task: automatically completed when record is logged")
                        : (locale === "ar" ? "تغيير حالة المهمة" : "Toggle task")
                    }
                  >
                    {item.completed ? (
                      <CheckCircle2 className="w-4 h-4 text-status-success" />
                    ) : (
                      <Square className="w-4 h-4 text-text-muted hover:text-on-surface" />
                    )}
                  </button>

                  <div className="min-w-0 text-start">
                    <div
                      className={`text-xs font-semibold truncate ${
                        item.completed ? "line-through text-text-muted" : "text-on-surface"
                      }`}
                    >
                      {item.title}
                    </div>
                    <div className="flex items-center gap-2 mt-0.5 text-[10px] font-mono text-text-muted">
                      <span className="flex items-center gap-1">
                        {getSourceIcon()}
                        <span className="capitalize">{getSourceLabel(item.source)}</span>
                      </span>
                      {item.estimate_minutes && (
                        <span>• {item.estimate_minutes} {locale === "ar" ? "دقيقة" : "m"}</span>
                      )}
                      {item.auto_completed && (
                        <span className="text-secondary-cyan font-semibold">
                          • {locale === "ar" ? "تم تلقائيًا" : "Auto-completed"}
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                <div className="flex items-center gap-1 shrink-0">
                  <button
                    onClick={() => handleDelete(item.id)}
                    className="p-1.5 rounded text-text-muted hover:text-status-danger transition-colors cursor-pointer"
                    title={locale === "ar" ? "حذف المهمة" : "Delete task"}
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Carry Over Action */}
      {priorities.some((p) => !p.completed) && (
        <div className="pt-2">
          <button
            onClick={handleCarryOver}
            className="w-full py-2.5 px-3 rounded-xl bg-surface-container-high hover:bg-surface-container-highest border border-border-subtle flex items-center justify-between text-xs font-mono text-text-muted hover:text-on-surface transition-colors cursor-pointer"
          >
            <span>{locale === "ar" ? "ترحيل المهام المتبقية لبكرة" : "Carry over incomplete tasks to tomorrow"}</span>
            <ArrowRight className="w-3.5 h-3.5 text-primary-lime rtl:rotate-180" />
          </button>
        </div>
      )}

      {/* Add Priority Modal */}
      {isAddModalOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-bg-darkest/80 backdrop-blur-md"
          onClick={() => setIsAddModalOpen(false)}
        >
          <div
            className="w-full max-w-sm bg-surface-container border border-border-subtle rounded-2xl p-5 shadow-2xl relative space-y-4"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between pb-3 border-b border-border-subtle">
              <h4 className="text-sm font-bold font-mono text-on-surface">
                {locale === "ar" ? "أولوية يومية جديدة" : "New Daily Priority"}
              </h4>
              <button
                onClick={() => setIsAddModalOpen(false)}
                className="w-7 h-7 rounded-lg bg-surface-container-high border border-border-subtle flex items-center justify-center text-text-muted hover:text-on-surface cursor-pointer"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <form onSubmit={handleAdd} className="space-y-3.5">
              <div>
                <label className="text-[11px] font-mono text-text-muted block mb-1">
                  {locale === "ar" ? "اسم المهمة" : "Task Title"}
                </label>
                <input
                  type="text"
                  required
                  placeholder={locale === "ar" ? "مثال: مراجعة فيزياء أو جلسة تمرين بنش" : "e.g. Bench press progression session"}
                  value={newTitle}
                  onChange={(e) => setNewTitle(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl bg-surface-container-low border border-border-subtle text-xs text-on-surface focus:outline-none focus:border-primary-lime/60 font-mono text-start"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[11px] font-mono text-text-muted block mb-1">
                    {locale === "ar" ? "المصدر" : "Source"}
                  </label>
                  <select
                    value={newSource}
                    onChange={(e) => setNewSource(e.target.value as PrioritySource)}
                    className="w-full px-3 py-2 rounded-xl bg-surface-container-low border border-border-subtle text-xs text-on-surface font-mono"
                  >
                    <option value="custom">{locale === "ar" ? "مهمة خاصة" : "Custom Task"}</option>
                    <option value="workout_plan">{locale === "ar" ? "خطة التمرين" : "Workout Plan"}</option>
                    <option value="study_goal">{locale === "ar" ? "هدف مذاكرة" : "Study Goal"}</option>
                    <option value="deadline">{locale === "ar" ? "ميعاد تسليم" : "Deadline"}</option>
                  </select>
                </div>

                <div>
                  <label className="text-[11px] font-mono text-text-muted block mb-1">
                    {locale === "ar" ? "الوقت المقدر" : "Estimate"}
                  </label>
                  <select
                    value={newEstimate}
                    onChange={(e) => setNewEstimate(Number(e.target.value))}
                    className="w-full px-3 py-2 rounded-xl bg-surface-container-low border border-border-subtle text-xs text-on-surface font-mono"
                  >
                    <option value={15}>15 {locale === "ar" ? "دقيقة" : "min"}</option>
                    <option value={30}>30 {locale === "ar" ? "دقيقة" : "min"}</option>
                    <option value={45}>45 {locale === "ar" ? "دقيقة" : "min"}</option>
                    <option value={60}>60 {locale === "ar" ? "دقيقة" : "min"}</option>
                    <option value={90}>90 {locale === "ar" ? "دقيقة" : "min"}</option>
                  </select>
                </div>
              </div>

              <div className="pt-2 flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => setIsAddModalOpen(false)}
                  className="flex-1 py-2 rounded-xl bg-surface-container-high text-xs font-mono text-text-muted hover:text-on-surface cursor-pointer"
                >
                  {locale === "ar" ? "إلغاء" : "Cancel"}
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="flex-1 py-2 rounded-xl bg-primary-lime text-on-primary text-xs font-mono font-bold hover:opacity-90 cursor-pointer flex items-center justify-center gap-1.5"
                >
                  {isSubmitting ? (
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  ) : (
                    locale === "ar" ? "حفظ المهمة" : "Save Priority"
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

