import { useSearchParams, useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase/client";
import {
  SubjectItem,
  GradeItem,
  DeadlineItem,
  MistakeItem,
  AcademicTopicItem,
  ScheduleItem,
  FocusSessionTelemetry,
  MistakeCause,
  RedoResult,
  calculateSubjectGradeAverage,
  calculateOverallAcademicStats,
